INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d82ede85-a84e-5f53-b925-ffb19e969eac', '5a1f523a-c9bb-504f-ba33-fcd3dd8d5c9d', NULL, 'Chuyên đề 10.3: Phương pháp xác định tiết điệu đệm', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.473Z', '2026-10-26T13:43:03.473Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('58e0a7ba-909c-5bc6-83a6-294534ccf539', 'ddfd7e77-bd4f-5610-9282-7ad8708a80bd', NULL, 'Chuyên đề 11.3: Kĩ năng chỉ huy', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.520Z', '2026-10-26T13:43:03.520Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('1d08ac92-4eeb-5fcf-b2b5-b3bc3c8d17b4', '0ea7da0b-edd8-5bc4-a782-fc0802c37354', NULL, 'Yếu tố và nguyên lí tạo hình Lựa chọn, kết hợp: Yếu tố tạo hình – Chấm, nét, hình, khối, màu sắc, đậm nhạt, chất cảm, không gian. Nguyên lí tạo hình – Cân bằng, tương phản, lặp lại, nhịp điệu, nhấn mạnh, chuyển động, tỉ lệ, hài hoà. Thể loại Lựa chọn, kết hợp: – Lí luận và lịch sử mĩ thuật – Hội hoạ – Đồ hoạ (tranh in)', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.617Z', '2026-10-26T13:43:03.617Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c8978e00-7625-553f-bd25-9c132dc49b00', 'e4c087b9-0e99-5703-9bb4-1db6b2597575', NULL, 'Thể loại: Thủ công Lựa chọn, kết hợp: – Đồ thủ công bằng vật liệu tự nhiên. – Đồ thủ công bằng vật liệu nhân tạo. – Đồ thủ công bằng vật liệu sưu tầm, tái sử dụng. Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm thủ công 2D. – Thực hành sáng tạo sản phẩm thủ công 3D. Thảo luận Lựa chọn, kết hợp: – Sản phẩm thủ công. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Đồ chơi, đồ dùng học tập.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.639Z', '2026-10-26T13:43:03.639Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d199eeea-1c86-5a84-b47c-f40301365f77', 'd63618b2-7651-512b-a3f0-5d9d7275d727', NULL, '– Thực hành sáng tạo sản phẩm thủ công 3D. Thảo luận Lựa chọn, kết hợp: – Sản phẩm thủ công. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Đồ chơi, đồ dùng học tập, đồ dùng cá nhân.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.666Z', '2026-10-26T13:43:03.666Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('751ed426-01da-5e48-a696-dfbb80f199eb', '5d4664a8-caf3-5f6b-9d2d-8bfe342cfa03', NULL, '– Đồ chơi, đồ dùng học tập, đồ dùng cá nhân, đồ lưu niệm.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.693Z', '2026-10-26T13:43:03.693Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0a3fcf8c-d7d5-5b55-b560-15b77d0529b4', '88809b6d-379a-5eec-be9d-e0ce8ce972aa', NULL, 'Thể loại: Thủ công Lựa chọn, kết hợp: – Đồ thủ công bằng vật liệu tự nhiên. – Đồ thủ công bằng vật liệu nhân tạo. – Đồ thủ công bằng vật liệu sưu tầm, tái sử dụng. Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm thủ công 2D. – Thực hành sáng tạo sản phẩm thủ công 3D. Thảo luận Lựa chọn, kết hợp: – Sản phẩm thủ công. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Đồ chơi, đồ dùng học tập, đồ dùng cá nhân, đồ lưu niệm, đồ gia dụng.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.711Z', '2026-10-26T13:43:03.711Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('20c2f7f2-6c14-54ec-80d6-ae46b4cb9fb2', 'bbdda13d-8a21-5eb5-87fb-dca3650ee43e', NULL, 'Thực hành – Thực hành sáng tạo sản phẩm thủ công 2D. – Thực hành sáng tạo sản phẩm thủ công 3D. Thảo luận Lựa chọn, kết hợp: – Sản phẩm thủ công. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Đồ chơi, đồ dùng học tập, đồ dùng cá nhân, đồ lưu niệm, đồ gia dụng, đồ trang trí nội thất.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.738Z', '2026-10-26T13:43:03.738Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c985e157-a053-5f97-a515-b8b08e82d795', '38e39d41-2b13-5473-a5ee-44f3a8a604c6', NULL, 'Định hướng chủ đề Lựa chọn, kết hợp: – Văn hoá, xã hội – Nghệ thuật Tiền sử và Cổ đại Việt Nam, thế giới.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.762Z', '2026-10-26T13:43:03.762Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('23d7d6b1-09a3-58f6-aea7-006559a8f882', 'ca7c86d6-e36b-5db6-bbb8-c8452bee7b47', NULL, 'chuyển động, tỉ lệ, hài hoà. Thể loại Lựa chọn, kết hợp: – Lí luận và lịch sử mĩ thuật – Thiết kế công nghiệp – Thiết kế đồ hoạ – Thiết kế thời trang Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm thiết kế 2D. – Thực hành sáng tạo sản phẩm thiết kế 3D. Thảo luận – Tìm hiểu tác giả, tác phẩm, sản phẩm, di sản văn hoá nghệ thuật. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Văn hoá, xã hội. – Nghệ thuật Trung đại Việt Nam và thế giới.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.791Z', '2026-10-26T13:43:03.791Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('82858555-d7a6-57be-973f-3472712015db', '599366f2-9e65-5a4d-af9b-4a340a7a64bb', NULL, '– Sản phẩm thực hành của học sinh. Định hướng chủ đề: Mĩ thuật tạo hình và ngành nghề.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.829Z', '2026-10-26T13:43:03.829Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c06fb066-a462-58be-80ad-3ec4c77d81d6', '0b3c75e8-9615-5028-bca9-02d3f8d4bbde', NULL, 'Hoạt động thực hành và thảo luận Thực hành Lựa chọn, kết hợp – Tìm hiểu ngành nghề liên quan đến mĩ thuật ứng dụng. - Thực hành sáng tạo sản phẩm mĩ thuật ứng dụng. Thảo luận Lựa chọn, kết hợp – Một số ngành nghề liên quan đến mĩ thuật ứng dụng. – Sản phẩm thực hành của học sinh. Định hướng chủ đề: Mĩ thuật ứng dụng và ngành nghề.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.853Z', '2026-10-26T13:43:03.853Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('59131839-0f59-53cb-a354-6e2d4d013cfe', '4e4363a7-42c9-594d-9b3b-18e1b9397a2a', NULL, '– Sản phẩm thực hành của học sinh.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.956Z', '2026-10-26T13:43:03.956Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('909ed8dc-022d-594d-841b-48c70df7fe14', '8ee7c875-490d-5a40-a102-5e0264926143', NULL, 'Thực hành – Vẽ tranh bố cục nhân vật bằng chất liệu màu bột, màu nước hoặc chất liệu tương đương. Thảo luận – Tranh bố cục nhân vật. – Sản phẩm thực hành của học sinh. Định hướng chủ đề: Tự chọn.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:04.047Z', '2026-10-26T13:43:04.047Z');
