INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('845e9121-9cec-5318-aeb9-8398773786d0', '3abe78bc-5040-596f-8791-68248ccd2af7', NULL, 'Tri thức lịch sử và cuộc sống Vai trò, ý nghĩa của tri thức lịch sử – Nhu cầu nhận thức về cội nguồn, về bản sắc văn hoá của con người trong mọi thời đại – Đúc rút và vận dụng kinh nghiệm trong thực tế cuộc sống – Dự báo về tương lai Học tập và khám phá lịch sử suốt đời – Sự cần thiết của việc học tập, khám phá lịch sử suốt đời – Thu thập thông tin, sử liệu, làm giàu tri thức lịch sử – Kết nối kiến thức, bài học lịch sử vào cuộc sống', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.256Z', '2026-10-26T13:42:59.256Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('96557d56-a3aa-5fe8-b237-337cc51583f1', '76292f4e-349e-5c0d-b604-978666a1929e', NULL, 'Sự phát triển của chủ nghĩa tư bản Sự xác lập chủ nghĩa tư bản ở châu Âu và Bắc Mỹ – Sự xác lập chủ nghĩa tư bản ở châu Âu và Bắc Mỹ Sự phát triển của chủ nghĩa tư bản – Chủ nghĩa đế quốc và quá trình xâm lược thuộc địa – Sự mở rộng và phát triển của chủ nghĩa tư bản – Chủ nghĩa tư bản từ tự do cạnh tranh sang độc quyền Chủ nghĩa tư bản hiện đại – Khái niệm chủ nghĩa tư bản hiện đại – Tiềm năng và thách thức của chủ nghĩa tư bản hiện đại', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.421Z', '2026-10-26T13:42:59.421Z');
