INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('7654549e-bca0-5e8e-a46f-890f4e00837b', '5edff9c6-809a-5999-9918-2d4cb852d471', NULL, 'Hệ thống điện quốc gia', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:02.826Z', '2026-10-26T13:43:02.826Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4da5df36-a540-5976-8af3-82ce2db98d14', '8f3dcc9b-6da6-5204-a4f4-4263f108f234', NULL, 'KIẾN THỨC CHUNG Vệ sinh cá nhân, đảm bảo an toàn trong tập luyện. VẬN ĐỘNG CƠ BẢN Đội hình đội ngũ – Biến đổi đội hình – Động tác giậm chân tại chỗ, đứng lại – Trò chơi rèn luyện đội hình đội ngũ Bài tập thể dục – Các động tác thể dục phù hợp với đặc điểm lứa tuổi – Trò chơi bổ trợ khéo léo', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:02.990Z', '2026-10-26T13:43:02.990Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('8ea41017-ff24-56b9-a265-f9b856732d1c', 'd0f29314-be29-5098-ac86-233145f7e462', NULL, 'KIẾN THỨC CHUNG Những yếu tố môi trường tự nhiên có lợi, có hại trong tập luyện. VẬN ĐỘNG CƠ BẢN Đội hình đội ngũ – Biến đổi đội hình – Động tác đi đều – Trò chơi rèn luyện đội hình đội ngũ Bài tập thể dục – Các động tác thể dục phù hợp với đặc điểm', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:02.998Z', '2026-10-26T13:43:02.998Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('37636233-0b1d-584c-9420-c44d37b43ae2', '2e94c07b-cf52-54c1-9bb2-0b48b0db182a', NULL, 'KIẾN THỨC CHUNG Vệ sinh trong giờ học: khởi động, tập luyện, hồi phục, nghỉ ngơi sau tập luyện. VẬN ĐỘNG CƠ BẢN Đội hình đội ngũ – Động tác đi đều vòng các hướng – Trò chơi rèn luyện đội hình đội ngũ Bài tập thể dục', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.005Z', '2026-10-26T13:43:03.005Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b32fdf28-737c-56ea-b91e-91e7bc6093a9', '46c8e4a9-9ef6-5e95-adf7-52e89131312c', NULL, 'KIẾN THỨC CHUNG Chế độ ăn uống đảm bảo dinh dưỡng trong tập luyện. VẬN ĐỘNG CƠ BẢN Đội hình đội ngũ – Luyện tập các nội dung đội hình, đội ngũ đã học – Trò chơi rèn luyện đội hình đội ngũ Bài tập thể dục', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.013Z', '2026-10-26T13:43:03.013Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('90ef390c-5ea8-5d1a-be6d-c3fd7f3b7dfd', 'db3c6e64-c3ec-532b-82df-f8010f8e2613', NULL, 'KIẾN THỨC CHUNG Chế độ dinh dưỡng trong tập luyện thể dục thể thao. VẬN ĐỘNG CƠ BẢN Chạy cự li ngắn (60m) – Các động tác bổ trợ kĩ thuật chạy – Chạy cự li ngắn 60m', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.021Z', '2026-10-26T13:43:03.021Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0a03c1e7-a23f-5eb5-bcf2-05b9854f594f', '1e531433-fca9-5599-9e25-6bd9871b078c', NULL, 'KIẾN THỨC CHUNG Sử dụng chế độ dinh dưỡng thích hợp với bản thân trong tập luyện thể dục thể thao. VẬN ĐỘNG CƠ BẢN Chạy cự li ngắn (100m) – Các động tác bổ trợ kĩ thuật chạy – Chạy cự li ngắn 100m – Một số trò chơi phát triển sức nhanh Nhảy cao kiểu bước qua – Các động tác bổ trợ kĩ thuật nhảy cao kiểu bước qua', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.040Z', '2026-10-26T13:43:03.040Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b3dcf82b-44d9-5377-9627-5b0ac69f81f5', 'f9f99ec5-a91b-51c1-9e2b-7a692baab4e3', NULL, 'KIẾN THỨC CHUNG Sử dụng các yếu tố tự nhiên (không khí, nước, ánh sáng,...) và dinh dưỡng để rèn luyện sức khoẻ và phát triển thể chất. MÔN THỂ THAO TỰ CHỌN Căn cứ vào điều kiện dạy học của địa phương và nhà', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.074Z', '2026-10-26T13:43:03.074Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d6174d3b-5c3e-58ae-98b4-76a49ac6cd8b', '22c0a128-549f-50bb-97fc-0913b249fa74', NULL, 'Nghe nhạc – Quốc ca Việt Nam. – Một số bản nhạc có lời và không lời phù hợp với độ tuổi.', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.116Z', '2026-10-26T13:43:03.116Z');
