INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0b21b947-fdce-5b5b-9bdd-018cb52d5ab2', 'ddfd7e77-bd4f-5610-9282-7ad8708a80bd', NULL, 'Hát Bài hát tuổi học sinh (17 – 18 tuổi), dân ca Việt Nam và bài hát nước ngoài. Các bài hát có nội dung, âm vực phù hợp với độ tuổi; đa dạng về loại nhịp và tính chất âm nhạc. Một số bài hợp xướng đơn giản.', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.525Z', '2026-10-26T13:43:03.525Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('29a86bc8-8122-56f4-b3fe-f60f8017699d', '0ea7da0b-edd8-5bc4-a782-fc0802c37354', NULL, '– Điêu khắc Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm mĩ thuật 2D. – Thực hành sáng tạo sản phẩm mĩ thuật 3D. Thảo luận Lựa chọn, kết hợp: – Tìm hiểu tác giả, tác phẩm, di sản văn hoá nghệ thuật. – Sản phẩm thực hành của học sinh. Định hướng chủ đề Lựa chọn, kết hợp: – Thiên nhiên; Con người; Gia đình; Nhà trường.', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:03.626Z', '2026-10-26T13:43:03.626Z');
