INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f1eeeed2-9774-51b2-ba60-c9a36c771e35', 'db3c6e64-c3ec-532b-82df-f8010f8e2613', NULL, '– Một số trò chơi phát triển sức nhanh Ném bóng – Các động tác bổ trợ kĩ thuật ném bóng – Kĩ thuật ném bóng – Trò chơi phát triển sức mạnh tay – ngực Chạy cự li trung bình – Các động tác bổ trợ kĩ thuật chạy – Kĩ thuật chạy cự li trung bình – Trò chơi phát triển sức bền Bài tập thể dục – Bài thể dục liên hoàn dành cho học sinh lớp 6 – Trò chơi phát triển khéo léo THỂ THAO TỰ CHỌN – Căn cứ vào điều kiện thực tế của địa phương và nhà trường, định hướng cho học sinh lựa chọn một trong những nội dung thể thao phù hợp với đặc điểm cá nhân và lứa tuổi: Điền kinh; Thể dục; Bơi; Bóng đá; Bóng chuyền; Bóng rổ; Cầu lông; Đá cầu; Bóng bàn; Võ; Khiêu vũ thể thao; Thể dục nhịp điệu; các môn thể thao truyền thống của địa phương;... – Trò chơi vận động bổ trợ cho môn thể thao lựa chọn', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.024Z', '2026-10-26T13:43:03.024Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('24637382-e502-5791-ac6d-21e999f518f7', '1e531433-fca9-5599-9e25-6bd9871b078c', NULL, '– Kĩ thuật nhảy cao kiểu bước qua – Trò chơi phát triển sức mạnh Chạy cự li trung bình – Các động tác bổ trợ kĩ thuật chạy – Kĩ thuật chạy cự li trung bình – Trò chơi phát triển sức bền Bài tập thể dục – Bài thể dục nhịp điệu dành cho học sinh lớp 8 – Trò chơi phát triển sự khéo léo THỂ THAO TỰ CHỌN – Căn cứ vào điều kiện thực tế của địa phương và nhà trường, định hướng cho học sinh lựa chọn một trong những nội dung thể thao phù hợp để học tập và rèn luyện: Điền kinh; Thể dục; Bơi; Bóng đá; Bóng chuyền; Bóng rổ; Cầu lông; Đá cầu; Bóng bàn; Võ; Khiêu vũ thể thao; Thể dục nhịp điệu; các môn thể thao truyền thống của địa phương;... – Trò chơi vận động bổ trợ cho môn thể thao lựa chọn', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.044Z', '2026-10-26T13:43:03.044Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('192bfa91-abfd-58ce-a557-6644885e9a7d', 'f9f99ec5-a91b-51c1-9e2b-7a692baab4e3', NULL, 'trường, định hướng cho học sinh lựa chọn nội dung môn thể thao phù hợp trong số các môn thể thao được sử dụng trong Hội khoẻ Phù đổng các cấp, trong giải thi đấu quốc gia và quốc tế, các môn thể thao truyền thống của địa phương: Điền kinh; Thể dục; Bơi; Bóng đá; Bóng chuyền; Bóng rổ; Cầu lông; Đá cầu; Bóng bàn; Võ (Vovinam, Võ dân tộc cổ truyền, Karatedo, Taekwondo,...); Quần vợt; Bóng ném; Khiêu vũ thể thao; Thể dục nhịp điệu; Cầu mây; các môn thể thao truyền thống của địa phương;…', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.077Z', '2026-10-26T13:43:03.077Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0b5f9ae2-de28-5c01-919c-9e1c2dc86fdf', '22c0a128-549f-50bb-97fc-0913b249fa74', NULL, 'Đọc nhạc Giọng Đô trưởng. Các mẫu âm ngắn, đơn giản, dễ đọc, âm vực phù hợp với độ tuổi. Chủ yếu sử dụng trường độ: trắng, đen, móc đơn, và dấu lặng đen.', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.119Z', '2026-10-26T13:43:03.119Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6b1909dc-b404-5312-a611-a6f5aee5e867', '622b3d8a-d517-54ef-8c16-42de13ce392c', NULL, 'Đọc nhạc Giọng Đô trưởng. Các mẫu âm ngắn, đơn giản, dễ đọc, âm vực phù hợp với độ tuổi. Chủ yếu sử dụng trường độ: trắng, đen, móc đơn, và dấu lặng đen.', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.142Z', '2026-10-26T13:43:03.142Z');
