INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b55e5d22-c196-556f-bc8a-69c429cfe653', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'Hát Bài hát tuổi học sinh (9 – 10 tuổi), dân ca Việt Nam và bài hát nước ngoài. Các bài hát có nội dung, âm vực phù hợp với độ tuổi; đa dạng về loại nhịp và tính chất âm nhạc.', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.179Z', '2026-10-26T13:43:03.179Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f1b0dd6f-9503-5627-88d6-73d372fb234c', 'af0cd753-c156-5400-9932-779033ac06a6', NULL, 'Nghe nhạc Nghe một số bản nhạc có lời và không lời phù hợp với độ', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.266Z', '2026-10-26T13:43:03.266Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('40e3e640-32e8-5f8c-8e4d-45f7fd95c70f', '166916b1-806d-5b60-8595-cc63d9ec7eb0', NULL, 'Đọc nhạc Giọng Đô trưởng. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc dễ đọc, âm vực phù hợp với độ tuổi. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, và các dấu lặng. Một số bài có 2 bè đơn giản.', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.305Z', '2026-10-26T13:43:03.305Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('8b6ca0cf-a6e9-5165-acd9-78ecb2f334d8', 'e490382e-bb21-502c-9386-f8d6d7914781', NULL, 'Đọc nhạc Giọng Đô trưởng và La thứ. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc dễ đọc, âm vực phù hợp với độ tuổi. Sử dụng trường độ:', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.347Z', '2026-10-26T13:43:03.347Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('874e04cc-d1bc-53a0-a8cb-ff92e60598af', '25437a8b-ca68-58e2-8801-5410d80e8e51', NULL, '– Thể loại âm nhạc: Hợp xướng.', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:03.373Z', '2026-10-26T13:43:03.373Z');
