INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e92dbc07-c48e-5b8a-97d8-7227982ae5bb', '22c0a128-549f-50bb-97fc-0913b249fa74', NULL, 'Nhạc cụ Một số mẫu tiết tấu ngắn, đơn giản. Chủ yếu sử dụng trường độ: trắng, đen, móc đơn, và dấu lặng đen.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.122Z', '2026-10-26T13:43:03.122Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('849b9513-6e29-544a-bdcd-5e8876f4ea3c', '622b3d8a-d517-54ef-8c16-42de13ce392c', NULL, 'Nhạc cụ', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.144Z', '2026-10-26T13:43:03.144Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('a7bee7b0-43ac-5df8-bd45-beaa7ba838b9', '3682b40f-fcfb-5a03-b8e2-093925de8b23', NULL, 'Hát – Quốc ca Việt Nam. – Bài hát tuổi học sinh (8 – 9 tuổi), đồng dao, dân ca Việt Nam, bài hát nước ngoài. Các bài hát ngắn gọn,', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.157Z', '2026-10-26T13:43:03.157Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('67d78be3-2d65-537b-b587-a687a4d62f57', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'Nghe nhạc Một số bản nhạc có lời và', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.184Z', '2026-10-26T13:43:03.184Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('fdc20f0c-8ab8-5a94-bdff-6e2ba0a17c53', 'af0cd753-c156-5400-9932-779033ac06a6', NULL, 'tuổi.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.269Z', '2026-10-26T13:43:03.269Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('34314ee9-4d04-52b6-ac80-4532a7b65e87', '166916b1-806d-5b60-8595-cc63d9ec7eb0', NULL, 'Nhạc cụ Một số bài tập tiết tấu, giai điệu và hoà âm đơn giản. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, và các dấu lặng.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.309Z', '2026-10-26T13:43:03.309Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('689bf1de-4ad3-54b9-921d-98080fe236f0', 'e490382e-bb21-502c-9386-f8d6d7914781', NULL, 'tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, móc kép và các dấu lặng. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.352Z', '2026-10-26T13:43:03.352Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('378cec7d-7daa-5de0-bc68-e48085abe154', '25437a8b-ca68-58e2-8801-5410d80e8e51', NULL, '– Âm nhạc và đời sống: Một số di sản văn hoá phi vật thể (liên quan đến âm nhạc) được UNESCO công nhận.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.375Z', '2026-10-26T13:43:03.375Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4c0ff5a9-0d05-564c-ba6f-12f2df4528c7', '3701fa32-a718-5dd0-9ffa-4b65550ecf52', NULL, 'Hát Bài hát tuổi học sinh (15 – 16 tuổi), dân ca Việt Nam và bài hát nước ngoài. Các bài hát có nội dung, âm vực phù hợp với độ tuổi; đa dạng về loại nhịp và tính chất âm nhạc. Một số bài hợp xướng đơn giản.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.427Z', '2026-10-26T13:43:03.427Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('29df7f41-3b3b-5e03-b563-5cbee246c6b8', '5a1f523a-c9bb-504f-ba33-fcd3dd8d5c9d', NULL, 'Đọc nhạc Giọng Pha trưởng, Rê thứ. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc phù hợp với năng lực học sinh. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.488Z', '2026-10-26T13:43:03.488Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c5c91258-afdc-5727-836b-d14fa81b9587', 'ddfd7e77-bd4f-5610-9282-7ad8708a80bd', NULL, 'Đọc nhạc Giọng Son trưởng, Mi thứ, Pha trưởng, Rê thứ. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc phù hợp với năng lực học sinh. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 4, NULL, NULL, '2026-10-26T13:43:03.535Z', '2026-10-26T13:43:03.535Z');
