INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('dd9ab10c-1112-5f73-9263-7e97866a7447', '6559f5e4-30bc-53b7-9a4b-4d18a2f0537a', NULL, 'Giới thiệu chung về trồng trọt', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:02.856Z', '2026-10-26T13:43:02.856Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('16c6c3da-bd5b-5032-b47d-0e798634d1fa', '22c0a128-549f-50bb-97fc-0913b249fa74', NULL, 'Thường thức âm nhạc – Tìm hiểu nhạc cụ: Một số nhạc cụ gõ của Việt Nam và nước ngoài.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.126Z', '2026-10-26T13:43:03.126Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('29cf1c48-42d6-5d73-abe0-08fbf3dd05fc', '3682b40f-fcfb-5a03-b8e2-093925de8b23', NULL, 'đơn giản, có nội dung, âm vực phù hợp với độ tuổi; đa dạng về loại nhịp và tính chất âm nhạc.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.162Z', '2026-10-26T13:43:03.162Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('aab65798-227f-524a-a492-f380e51462d4', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'không lời phù hợp với độ tuổi.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.187Z', '2026-10-26T13:43:03.187Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('1be4253c-d8d3-5e75-a204-ea99da984514', 'af0cd753-c156-5400-9932-779033ac06a6', NULL, 'Đọc nhạc Giọng Đô trưởng. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc dễ đọc, âm vực phù hợp với độ tuổi. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, và các dấu lặng. Một số bài có 2 bè đơn giản.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.271Z', '2026-10-26T13:43:03.271Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('465c1b3d-046b-56b6-bdb0-b82b8a190126', '166916b1-806d-5b60-8595-cc63d9ec7eb0', NULL, 'Lí thuyết âm nhạc – Nhịp lấy đà. – Kí hiệu để tăng trường độ nốt nhạc: dấu nối, dấu chấm dôi, dấu miễn nhịp.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.314Z', '2026-10-26T13:43:03.314Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('7d527cfb-043a-57ff-abf5-0dcc41d4b391', 'e490382e-bb21-502c-9386-f8d6d7914781', NULL, 'Nhạc cụ Một số bài tập tiết tấu, giai điệu và hoà âm đơn giản. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, móc kép và các dấu lặng.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.355Z', '2026-10-26T13:43:03.355Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3ee84ee3-20e8-5ee7-af0c-501a83e24cf3', '25437a8b-ca68-58e2-8801-5410d80e8e51', NULL, 'Hát Bài hát tuổi học sinh (14 – 15 tuổi), dân ca Việt Nam và bài hát nước ngoài. Các bài hát có nội dung, âm vực phù hợp', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.378Z', '2026-10-26T13:43:03.378Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3eaff764-70f8-5bc7-9557-c51700fcd1f4', '3701fa32-a718-5dd0-9ffa-4b65550ecf52', NULL, 'Nghe nhạc Nghe một số bản nhạc có lời và không lời phù hợp với độ tuổi.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.434Z', '2026-10-26T13:43:03.434Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('405a9917-48c7-5a29-9981-6041dcb4c63d', '5a1f523a-c9bb-504f-ba33-fcd3dd8d5c9d', NULL, 'Nhạc cụ Các bài tập tiết tấu, giai điệu và hoà âm.', 'lesson', 5, NULL, NULL, '2026-10-26T13:43:03.493Z', '2026-10-26T13:43:03.493Z');
