INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3584ac95-5207-5a13-9dd5-54af733ac542', '22c0a128-549f-50bb-97fc-0913b249fa74', NULL, '– Câu chuyện âm nhạc: Một số câu chuyện âm nhạc phù hợp với độ tuổi.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.129Z', '2026-10-26T13:43:03.129Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6126e006-c504-5758-b1b8-ac18d5987bf4', '3682b40f-fcfb-5a03-b8e2-093925de8b23', NULL, 'Nghe nhạc Một số bản nhạc có lời và không lời phù hợp với độ tuổi.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.163Z', '2026-10-26T13:43:03.163Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3c6988c8-d1b2-5ff5-9793-e0873d92fadd', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'Đọc nhạc Giọng Đô trưởng. Các bài đọc nhạc ngắn, dễ đọc, âm vực phù hợp với độ tuổi. Sử dụng trường độ: trắng, trắng có chấm dôi, đen, móc đơn, và các dấu lặng.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.190Z', '2026-10-26T13:43:03.190Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d4ed287a-a2c3-5222-a383-8abcae59670d', 'af0cd753-c156-5400-9932-779033ac06a6', NULL, 'Nhạc cụ Một số bài tập tiết tấu, giai điệu và hoà âm đơn giản. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, và các dấu lặng.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.274Z', '2026-10-26T13:43:03.274Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c9ef2da3-dc9c-52a8-ac7e-5a7223ff85dd', '166916b1-806d-5b60-8595-cc63d9ec7eb0', NULL, '– Một số kí hiệu, thuật ngữ về nhịp độ, cường độ và sắc thái. – Dấu nhắc lại, dấu quay lại, khung thay đổi.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.318Z', '2026-10-26T13:43:03.318Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d49eebcf-d95a-5cdb-880e-3daf29ed43ee', 'e490382e-bb21-502c-9386-f8d6d7914781', NULL, 'Lí thuyết âm nhạc – Sơ lược về giọng, giọng Đô trưởng, giọng La thứ. – Đảo phách. – Nhịp , .', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.360Z', '2026-10-26T13:43:03.360Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3bdc00e5-6505-51fe-ab06-65809b2f6cd3', '25437a8b-ca68-58e2-8801-5410d80e8e51', NULL, 'với độ tuổi; đa dạng về loại nhịp và tính chất âm nhạc. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.382Z', '2026-10-26T13:43:03.382Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f51461dd-37e4-53db-921d-da4181248862', '3701fa32-a718-5dd0-9ffa-4b65550ecf52', NULL, 'Đọc nhạc Giọng Son trưởng, Mi thứ. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc phù hợp với năng lực học sinh. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.438Z', '2026-10-26T13:43:03.438Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f36b8303-c291-5137-96bd-88f7ad0843c6', '5a1f523a-c9bb-504f-ba33-fcd3dd8d5c9d', NULL, 'Lí thuyết âm nhạc – Giọng và gam: Pha trưởng, Rê thứ. – Một số hợp âm của các giọng: Pha trưởng, Rê thứ.', 'lesson', 6, NULL, NULL, '2026-10-26T13:43:03.498Z', '2026-10-26T13:43:03.498Z');
