INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4568b32e-4378-5d72-b48c-78c1dfa6abdb', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'Nhạc cụ Một số bài tập tiết tấu và giai điệu đơn giản. Sử dụng trường độ: trắng, trắng có chấm dôi, đen, móc đơn, và các dấu lặng.', 'lesson', 7, NULL, NULL, '2026-10-26T13:43:03.196Z', '2026-10-26T13:43:03.196Z');
