INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('fb5a7927-b4ab-57c1-a88a-461c04da7a69', '3682b40f-fcfb-5a03-b8e2-093925de8b23', NULL, 'Nhạc cụ Một số mẫu tiết tấu ngắn, đơn giản. Chủ yếu sử dụng trường độ: trắng, đen, móc đơn, và dấu lặng đen.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.169Z', '2026-10-26T13:43:03.169Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('dbdc4f99-dd43-509e-8558-eb5c907c04e2', 'd4bc10a2-5ed9-59a4-b3cc-c759eafa19e2', NULL, 'Lí thuyết âm nhạc – Khuông nhạc, khoá Son, dòng kẻ phụ, nốt nhạc. – Các hình nốt: tròn, trắng, đen, móc đơn, móc kép và', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.201Z', '2026-10-26T13:43:03.201Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f9da5ad9-b7f7-591b-9e8f-92ffcb98e25d', 'af0cd753-c156-5400-9932-779033ac06a6', NULL, 'Thường thức âm nhạc – Tìm hiểu nhạc cụ: Một số nhạc cụ phổ biến của Việt Nam và nước ngoài.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.283Z', '2026-10-26T13:43:03.283Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6cc484d3-329b-5f73-9e6d-f464849416b2', '166916b1-806d-5b60-8595-cc63d9ec7eb0', NULL, '– Tác giả và tác phẩm: Một số nhạc sĩ tiêu biểu của Việt Nam và thế giới.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.324Z', '2026-10-26T13:43:03.324Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3fd41eff-6fd9-59e4-870e-cd6805f930a3', '25437a8b-ca68-58e2-8801-5410d80e8e51', NULL, 'Đọc nhạc Giọng Đô trưởng và La thứ. Bài luyện tập cơ bản về quãng, về tiết tấu. Các bài đọc nhạc dễ đọc, âm vực phù hợp với độ tuổi. Sử dụng trường độ: tròn, trắng, trắng có chấm dôi, đen, đen có chấm dôi, móc đơn, móc kép và các dấu lặng. Một số bài có 2 hoặc 3 bè đơn giản.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.390Z', '2026-10-26T13:43:03.390Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('cd97df60-4e75-5c77-9a66-d5fc9f54f168', '3701fa32-a718-5dd0-9ffa-4b65550ecf52', NULL, 'Lí thuyết âm nhạc – Quãng hoà thanh, quãng giai điệu, các loại quãng (quãng đơn, quãng diatonic), tính chất các quãng. – Sơ lược về điệu thức (trưởng và thứ tự nhiên, thứ hoà thanh); giọng và gam. – Giọng và gam: Son trưởng, Mi thứ. – Một số hợp âm của các', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.451Z', '2026-10-26T13:43:03.451Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('27da328e-39e8-559f-9904-a6826e10105a', '5a1f523a-c9bb-504f-ba33-fcd3dd8d5c9d', NULL, '– Âm nhạc và đời sống: Vài nét về lịch sử âm nhạc Việt Nam.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.505Z', '2026-10-26T13:43:03.505Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3a3a662a-f487-5278-b690-bf4f1ad1b078', 'ddfd7e77-bd4f-5610-9282-7ad8708a80bd', NULL, 'Thường thức âm nhạc – Thể loại âm nhạc: Sơ lược về thể loại nhạc nhẹ phổ biến.', 'lesson', 8, NULL, NULL, '2026-10-26T13:43:03.554Z', '2026-10-26T13:43:03.554Z');
