INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e3992293-3fe7-5f54-9990-ac0959d15d55', '6a55e953-6790-50dd-a87a-d30bfade5cc7', '3096b28c-188d-5328-b1a7-40c7edeffc13', '– Hệ thống kinh vĩ tuyến. Toạ độ địa lí của một địa điểm trên bản đồ – Các yếu tố cơ bản của bản đồ – Các loại bản đồ thông dụng – Lược đồ trí nhớ', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:58.896Z', '2026-10-26T13:42:58.896Z');
