INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('2f2c08fc-9019-5abf-9ca8-9c03e15acdef', '6a55e953-6790-50dd-a87a-d30bfade5cc7', 'ca4df0c2-15c4-5b68-b3ea-b2eab2dbe9b7', '+ Nhà nước Âu Lạc – Thời kì Bắc thuộc và chống Bắc thuộc từ thế kỉ II trước Công nguyên đến năm 938 + Chính sách cai trị của các triều đại phong kiến phương Bắc + Sự chuyển biến về kinh tế, văn hoá trong thời kì Bắc thuộc + Các cuộc đấu tranh giành lại độc lập và bảo vệ bản sắc văn hoá của dân tộc + Bước ngoặt lịch sử ở đầu thế kỉ X', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:58.968Z', '2026-10-26T13:42:58.968Z');
