INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('2e485eb5-97ca-54f9-b280-304d53d827d6', '3abe78bc-5040-596f-8791-68248ccd2af7', '3529fb4a-f424-5017-9604-657f032215ba', 'Các dân tộc trên đất nước Việt Nam Thành phần dân tộc theo dân số Thành phần dân tộc theo ngữ hệ – Khái niệm ngữ hệ và việc phân chia tộc người theo ngữ hệ', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:59.349Z', '2026-10-26T13:42:59.349Z');
