INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('1bf68e64-b1bd-5ef6-a257-2bd26e72f23c', 'f24fc9c1-5b58-504b-8d04-adede0146230', '7b96c129-fc41-5f3f-9cbe-aaa95dff6ffb', 'Quan hệ bang giao Việt Nam thời cổ – trung đại Quan hệ bang giao Việt Nam với Trung Quốc – Sự thiết lập quan hệ bang giao Việt Nam – Trung Quốc ở thế kỉ X – Đặc điểm của quan hệ bang giao Việt Nam – Trung Quốc Quan hệ bang giao Việt Nam với Đông Nam Á – Quan hệ bang giao Việt Nam – Đông Nam Á', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:59.623Z', '2026-10-26T13:42:59.623Z');
