INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6f51595d-ff87-5817-ad39-384a72284f3f', '0ea7da0b-edd8-5bc4-a782-fc0802c37354', '23cd7b5f-dc79-58e6-b1f0-7d881d1d76e0', 'Yếu tố và nguyên lí tạo hình Lựa chọn, kết hợp: Yếu tố tạo hình – Chấm, nét, hình, khối, màu sắc, đậm nhạt, chất cảm, không gian. Nguyên lí tạo hình – Cân bằng, tương phản, lặp lại, nhịp điệu, nhấn mạnh, chuyển động, tỉ lệ, hài hoà.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.633Z', '2026-10-26T13:43:03.633Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e1406456-f724-57e0-a49e-7d96c2ea7e85', 'e4c087b9-0e99-5703-9bb4-1db6b2597575', '5e1b7505-103b-5c95-b8b3-42f727d9ebf6', 'Yếu tố và nguyên lí tạo hình Lựa chọn, kết hợp: Yếu tố tạo hình – Chấm, nét, hình, khối, màu sắc, đậm nhạt, chất cảm, không gian. Nguyên lí tạo hình – Cân bằng, tương phản, lặp lại, nhịp điệu, nhấn mạnh, chuyển động, tỉ lệ, hài hoà. Thể loại Lựa chọn, kết hợp: – Lí luận và lịch sử mĩ thuật – Hội hoạ – Đồ hoạ (tranh in) – Điêu khắc Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm mĩ thuật 2D. – Thực hành sáng tạo sản phẩm mĩ thuật 3D. Thảo luận Lựa chọn, kết hợp: – Tìm hiểu tác giả, tác phẩm, di sản văn hoá nghệ thuật.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.645Z', '2026-10-26T13:43:03.645Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b0d36fa2-38a5-5142-a595-7088eb9ab13b', 'e4c087b9-0e99-5703-9bb4-1db6b2597575', 'c3efbc17-3768-5914-a3e2-6bb7b24f2b7e', 'Yếu tố và nguyên lí tạo hình Lựa chọn, kết hợp: Yếu tố tạo hình – Chấm, nét, hình, khối, màu sắc, đậm nhạt, chất cảm, không gian. Nguyên lí tạo hình – Cân bằng, tương phản, lặp lại, nhịp điệu, nhấn mạnh, chuyển động, tỉ lệ, hài hoà. Thể loại: Thủ công Lựa chọn, kết hợp: – Đồ thủ công bằng vật liệu tự nhiên. – Đồ thủ công bằng vật liệu nhân tạo. – Đồ thủ công bằng vật liệu sưu tầm, tái sử dụng. Hoạt động thực hành và thảo luận Thực hành – Thực hành sáng tạo sản phẩm thủ công 2D.', 'lesson', 1, NULL, NULL, '2026-10-26T13:43:03.658Z', '2026-10-26T13:43:03.658Z');
