INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('22d42375-0e27-5d53-9048-cf5a66878a1e', '3abe78bc-5040-596f-8791-68248ccd2af7', 'cf909885-7ccc-5615-a039-622b1284d1f9', '– Lịch sử dân tộc – Lịch sử thế giới', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.371Z', '2026-10-26T13:42:59.371Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('739edc30-735f-5fd9-b778-5f1ad8d1ceea', '3abe78bc-5040-596f-8791-68248ccd2af7', 'db9ae25e-f5cb-52f8-bbfd-d404f0995ea2', 'Sử học với sự phát triển công nghiệp văn hoá – Vai trò của sử học đối với một số ngành, nghề trong lĩnh vực công nghiệp văn hoá – Vai trò của các ngành nghề thuộc lĩnh vực công nghiệp văn hoá đối với sử học Sử học với sự phát triển du lịch – Vai trò của lịch sử và văn hoá đối với sự phát triển du lịch – Vai trò của du lịch đối với việc bảo tồn di tích lịch sử và di sản văn hoá', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.266Z', '2026-10-26T13:42:59.266Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4d7195b2-9225-55fe-bf9d-081e190a4fe7', '3abe78bc-5040-596f-8791-68248ccd2af7', '3e8fcabc-3ec9-5c69-8d36-81235cc3a6f8', '– Khái quát tiến trình phát triển lịch sử văn minh thế giới', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.274Z', '2026-10-26T13:42:59.274Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4758df21-6bea-5ed1-aa92-271a274038a4', '3abe78bc-5040-596f-8791-68248ccd2af7', 'f3185067-2245-54fe-a783-6365e8cfacb3', 'Cách mạng công nghiệp thời kì hiện đại Cách mạng công nghiệp lần thứ ba – Bối cảnh lịch sử – Những thành tựu cơ bản Cách mạng công nghiệp lần thứ tư (Cách mạng 4.0) – Bối cảnh lịch sử – Những thành tựu cơ bản Ý nghĩa của Cách mạng công nghiệp lần thứ ba và lần thứ tư – Về kinh tế – Về xã hội, văn hoá', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.299Z', '2026-10-26T13:42:59.299Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6a4455da-f414-5ffc-a5ed-ef9064320532', '3abe78bc-5040-596f-8791-68248ccd2af7', '6c3f1b66-b102-517c-a508-e91f70d00861', 'Hành trình phát triển và thành tựu của văn minh Đông Nam Á Hành trình phát triển của văn minh Đông Nam Á', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.311Z', '2026-10-26T13:42:59.311Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0c0c3dfc-f184-53bf-b44a-149d8df2560e', '3abe78bc-5040-596f-8791-68248ccd2af7', '84f50920-ac78-5799-81ed-91a47bc79bc2', 'Ý nghĩa của văn minh Đại Việt trong lịch sử dân tộc Việt Nam – Ưu điểm và hạn chế của văn minh Đại Việt – Ý nghĩa của nền văn minh Đại Việt trong lịch sử dân tộc Việt Nam', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.345Z', '2026-10-26T13:42:59.345Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('fad579f5-7bc4-5de4-92b8-cacfa425e521', '3abe78bc-5040-596f-8791-68248ccd2af7', '3529fb4a-f424-5017-9604-657f032215ba', 'Khái quát về đời sống vật chất và tinh thần của cộng đồng các dân tộc Việt Nam – Đời sống vật chất – Đời sống tinh thần', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.353Z', '2026-10-26T13:42:59.353Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e65417c0-7872-52b2-8022-de134022257e', '3abe78bc-5040-596f-8791-68248ccd2af7', '769cd45d-a1b5-5ae2-840e-b2eb5bc5bbed', 'văn hoá – Các giải pháp bảo tồn và phát huy giá trị di sản văn hoá Vai trò, trách nhiệm của các bên liên quan – Vai trò của hệ thống chính trị, doanh nghiệp, cộng đồng dân cư và của mỗi cá nhân trong việc bảo tồn và phát huy giá trị di sản văn hoá. – Trách nhiệm của các bên liên quan: Nhà nước, tổ chức xã hội, nhà trường, cộng đồng, công dân trong việc bảo tồn và phát huy giá trị các di sản văn hoá', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.389Z', '2026-10-26T13:42:59.389Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c28c6f6b-7b27-5e76-9287-76a082a287a2', '3abe78bc-5040-596f-8791-68248ccd2af7', 'be34c357-7976-5fd9-b677-2681046fdefb', 'Nhà nước Việt Nam Dân chủ Cộng hoà (1945 – 1976) Sự ra đời của Nhà nước Việt Nam Dân chủ Cộng hoà – Bối cảnh ra đời của Nhà nước Việt Nam Dân chủ Cộng hoà – Ý nghĩa lịch sử của việc ra đời Nhà nước Việt Nam Dân chủ Cộng hoà Vai trò của Nhà nước Việt Nam Dân chủ Cộng hoà – Đặc điểm và tính chất của Nhà nước Việt Nam Dân chủ', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.402Z', '2026-10-26T13:42:59.402Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('bd0ad83f-ed3b-58ca-aa95-39184db78b9b', '76292f4e-349e-5c0d-b604-978666a1929e', '2fd3f23e-b143-5f69-b926-ddddc6564305', 'Nghệ thuật thời Lê sơ và thời Mạc Nghệ thuật thời Lê sơ – Kiến trúc – Điêu khắc Nghệ thuật thời Mạc – Kiến trúc – Điêu khắc', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.516Z', '2026-10-26T13:42:59.516Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('46e1e3ce-0121-5e81-94cc-17dbfe80742e', '76292f4e-349e-5c0d-b604-978666a1929e', 'cacd717b-8d4d-5027-9c41-5fcdc23dd3e4', 'tiên trên thế giới. Sự phát triển của chủ nghĩa xã hội sau Chiến tranh thế giới thứ hai – Sự phát triển của chủ nghĩa xã hội ở Đông Âu – Sự mở rộng chủ nghĩa xã hội ở châu Á và Cuba – Nguyên nhân khủng hoảng và sụp đổ của chủ nghĩa xã hội ở Đông Âu và Liên Xô Chủ nghĩa xã hội từ năm 1991 đến nay – Thành tựu chính của công cuộc cải cách mở cửa ở Trung Quốc và công cuộc Đổi mới ở Việt Nam – Thách thức và triển vọng của chủ nghĩa xã hội ở Trung Quốc, Việt Nam', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.432Z', '2026-10-26T13:42:59.432Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('54077679-b84f-54ae-ade6-f55740fe1d35', '76292f4e-349e-5c0d-b604-978666a1929e', 'dd0aa9c1-76f9-5a30-a54b-30e7992e5175', '– Đàm phán hoà bình với chính quyền thực dân ở các thuộc địa của Anh, Mỹ,... Thời kì tái thiết và phát triển sau khi giành được độc lập – Những ảnh hưởng của chế độ thực dân – Quá trình tái thiết và phát triển', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.442Z', '2026-10-26T13:42:59.442Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0f70682f-930a-50c0-baa6-ceabc10c05dc', '76292f4e-349e-5c0d-b604-978666a1929e', '7c10c386-ab47-5cbc-afa1-6cbb240bb4ab', 'Một số cuộc kháng chiến thắng lợi tiêu biểu', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.451Z', '2026-10-26T13:42:59.451Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('1e770f0f-c63c-5525-ac4b-f50a89e143f5', '76292f4e-349e-5c0d-b604-978666a1929e', 'd1ecf0da-2f09-5696-83af-74c934e678e8', 'Cuộc cải cách của Lê Thánh Tông thế kỉ XV – Bối cảnh lịch sử – Nội dung chính – Kết quả Cuộc cải cách Minh Mạng nửa đầu thế kỉ XIX – Bối cảnh lịch sử – Nội dung chính – Kết quả', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.501Z', '2026-10-26T13:42:59.501Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('976fd135-b541-5321-a12d-213ab152c9e2', '46741ca8-f5a1-5005-ae08-244498e0f812', 'b3bcfdac-ab67-5ed8-b426-02268c1f1cc5', '– Ý nghĩa – Chuyển dịch cơ cấu kinh tế theo hướng công nghiệp hoá, hiện đại hoá – Chuyển dịch cơ cấu kinh tế theo ngành, theo thành phần kinh tế, theo lãnh thổ Vấn đề phát triển nông nghiệp, lâm nghiệp và thuỷ sản', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.954Z', '2026-10-26T13:42:59.954Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('2dc67c7d-718a-5dde-be36-b09e8b606e92', '76292f4e-349e-5c0d-b604-978666a1929e', 'f268d0be-dbdc-5c54-9c3a-8bff4135e916', 'Chủ trương của Việt Nam giải quyết các tranh chấp ở Biển Đông bằng biện pháp hoà bình – Ban hành văn bản pháp luật khẳng định chủ quyền – Tham gia Công ước Luật biển năm 1982 của Liên hợp quốc (UNCLOS) – Thông qua Luật Biển Việt Nam năm 2012 – Thúc đẩy và thực hiện đầy đủ Tuyên bố về ứng xử của các bên ở Biển Đông (DOC) – Tiến tới xây dựng Bộ Quy tắc ứng xử ở Biển Đông (COC)', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.507Z', '2026-10-26T13:42:59.507Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('df5f0867-2642-5c29-98ba-3bf9e9361749', '76292f4e-349e-5c0d-b604-978666a1929e', 'd0b096e7-3e8f-5883-8d84-a19fb4cdefda', 'giới thứ hai – Phong trào kháng chiến chống phát xít ở châu Âu, châu Á, châu Phi – Cuộc chiến tranh vệ quốc vĩ đại của nhân dân Liên Xô', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.526Z', '2026-10-26T13:42:59.526Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('9157ce63-33e5-53b8-89ca-5f3d3e016bb5', '76292f4e-349e-5c0d-b604-978666a1929e', '13900579-44d7-5353-a8eb-b78d9350174a', 'Một số nhà chính trị nổi tiếng của Việt Nam thời cổ – trung đại (Gợi ý lựa chọn) Đinh Bộ Lĩnh Trần Thủ Độ Lê Thánh Tông Minh Mệnh ...', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.539Z', '2026-10-26T13:42:59.539Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('dabb8f83-b914-5323-855e-979399cd5d85', 'f24fc9c1-5b58-504b-8d04-adede0146230', '8d253aec-14af-55cd-9243-a83410670762', '– Sự hình thành – Nội dung Sự sụp đổ của Trật tự thế giới hai cực Yalta – Nguyên nhân sụp đổ – Hệ quả và tác động', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.557Z', '2026-10-26T13:42:59.557Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d43bad40-cefd-5def-8b6a-54fcb7faa394', 'f24fc9c1-5b58-504b-8d04-adede0146230', '38b7cfda-ac5d-578a-8001-225a60a60520', 'Thời kì tăng trưởng (thập niên 90 của thế kỉ XX) – Tăng trưởng kinh tế, tự do hoá thương mại – Tình hình chính trị – xã hội', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.567Z', '2026-10-26T13:42:59.567Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e4534955-8cdb-51d8-86ab-44b253f23539', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'fc45161a-38fc-5b99-860d-8cea6dc1c71d', 'Quá trình cải cách mở cửa Đường lối cải cách – Trọng tâm cải cách: phát triển kinh tế – Kiên trì bốn nguyên tắc cơ bản – Tiến hành cải cách mở cửa, phát triển kinh tế thị trường – Xây dựng chủ nghĩa xã hội mang đặc sắc Trung Quốc Các giai đoạn cải cách mở cửa: – Giai đoạn 1978 – 1991 – Giai đoạn 1992 – 2000 – Giai đoạn 2001 – 2012', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.579Z', '2026-10-26T13:42:59.579Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('31d55c82-46de-5834-b814-fc05157559e1', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'aaf4217a-c4a6-59c2-b1dd-0bc0da05fbbd', '– Cộng đồng Kinh tế ASEAN (AEC) – Cộng đồng Văn hoá – Xã hội (ASCC) Cộng đồng ASEAN sau năm 2015 – Tầm nhìn ASEAN sau năm 2015 – Những thách thức và triển vọng của Cộng đồng ASEAN', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.590Z', '2026-10-26T13:42:59.590Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('fd220386-e57d-5a37-a60b-ac2332ae28cb', 'f24fc9c1-5b58-504b-8d04-adede0146230', '5ffd9f6d-a6bb-59cf-b723-43e6cdfbf2e1', '– Những diễn biến chính Nguyên nhân thắng lợi, vị trí, ý nghĩa lịch sử của cuộc kháng chiến chống thực dân Pháp trong tiến trình lịch sử Việt Nam – Nguyên nhân thắng lợi – Vị trí, ý nghĩa lịch sử', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.596Z', '2026-10-26T13:42:59.596Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('587b2b63-72e9-52e3-84a1-82f825ab53de', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'c1339d33-090e-5288-945b-32e70b33f827', '– Đổi mới kinh tế là trọng tâm, đồng thời từng bước đổi mới về chính trị, xã hội, văn hoá Về phương thức – Đổi mới ở Việt Nam diễn ra từ hai chiều: vừa có sự chỉ đạo từ trên xuống, vừa có sự sáng tạo của nhân dân từ dưới lên – Đổi mới gắn liền với quá trình hội nhập quốc tế', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.615Z', '2026-10-26T13:42:59.615Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('221735e5-c373-5001-ba1b-112cd69a6128', 'f24fc9c1-5b58-504b-8d04-adede0146230', '7b96c129-fc41-5f3f-9cbe-aaa95dff6ffb', '(1945 – 1954) – Hoàn cảnh lịch sử – Chủ trương đối ngoại – Những thành tựu chính Quan hệ đối ngoại Việt Nam trong kháng chiến chống Mỹ (1954 – 1975) – Hoàn cảnh lịch sử – Chủ trương đối ngoại – Những thành tựu chính Quan hệ đối ngoại Việt Nam trong giai đoạn 1975 – 1985 – Hoàn cảnh lịch sử – Chủ trương đối ngoại – Những thành tựu chính Quan hệ đối ngoại Việt Nam thời kì Đổi mới (từ năm 1986 đến nay) – Hoàn cảnh lịch sử – Chủ trương hội nhập quốc tế – Thành tựu và thách thức của đối ngoại Việt Nam thời kì Đổi mới', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.626Z', '2026-10-26T13:42:59.626Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('59708fb9-a322-57e3-b7c2-08e5c3427044', 'f24fc9c1-5b58-504b-8d04-adede0146230', '3c7ad644-7d7d-5d49-960d-94eea3812bcb', 'Xác định con đường cứu nước – Hành trình đi tìm đường cứu nước – Con đường cứu nước – Ý nghĩa của việc tìm ra con đường cứu nước Sáng lập Đảng Cộng sản Việt Nam – Chuẩn bị về chính trị, tư tưởng, tổ chức cho sự ra đời của Đảng – Triệu tập và chủ trì hội nghị thành lập Đảng Cộng sản Việt Nam – Ý nghĩa của việc thành lập Đảng Cộng sản Việt Nam Lãnh đạo Cách mạng tháng Tám 1945 – Triệu tập và chủ trì Hội nghị Trung ương 8 (tháng 5 năm 1941) – Sáng lập Mặt trận Việt Minh (ngày 19 tháng 5 năm 1941) – Trực tiếp lãnh đạo và tiến hành các hoạt động đấu tranh ngoại giao trong thời gian từ năm 1941 đến năm 1945 – Cùng Trung ương Đảng và Mặt trận Việt Minh lãnh đạo Cách mạng tháng Tám năm 1945 thắng lợi, lập ra nước Việt Nam Dân chủ Cộng hoà Lãnh đạo kháng chiến chống Pháp (1945 – 1954) và chống Mỹ (1954 – 1969)', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.637Z', '2026-10-26T13:42:59.637Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('853bf9e7-5445-5d55-b8a8-6536c662d708', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'b9bc0760-f686-562d-ac29-046612935296', 'Một số tín ngưỡng ở Việt Nam Tín ngưỡng thờ cúng tổ tiên và Quốc tổ Hùng Vương Thờ Mẫu Thờ Thành hoàng Thờ anh hùng dân tộc', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.654Z', '2026-10-26T13:42:59.654Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('1f37fab8-3c54-54b9-8321-1921499076c8', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'd2d13623-c1c9-5d16-b13e-f8f0212aaf9b', 'Nhật Bản từ năm 1973 đến nay Thời kì khủng hoảng và điều chỉnh (1973 – 2000) – Sự phát triển không ổn định về kinh tế – Tình hình chính trị, xã hội Nhật Bản những năm đầu thế kỉ XXI – Cải cách và quá trình phục hồi kinh tế – Những chuyển biến về chính trị, xã hội', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.668Z', '2026-10-26T13:42:59.668Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4912f80d-8d21-5b32-8a40-9b73511304a5', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'de02bdef-00c3-53b3-89e0-c18c6a570630', 'Việt Nam hội nhập khu vực và quốc tế Tác động của toàn cầu hoá đối với Việt Nam – Tác động tích cực – Tác động tiêu cực Việt Nam hội nhập khu vực và quốc tế – Việt Nam hội nhập khu vực Đông Nam Á, vai trò và đóng góp của Việt Nam trong ASEAN – Việt Nam tham gia các tổ chức quốc tế', 'lesson', 2, NULL, NULL, '2026-10-26T13:42:59.684Z', '2026-10-26T13:42:59.684Z');
