INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0805a0e4-f823-5f56-bbe4-09977fbadd57', '8ee7c875-490d-5a40-a102-5e0264926143', '55563d84-3105-54ea-9b0b-2042b1274ab1', 'Lựa chọn, kết hợp: Yếu tố tạo hình – Chấm, nét, hình, khối, màu sắc, đậm nhạt, chất cảm, không gian. Nguyên lí tạo hình – Cân bằng, tương phản, lặp lại, nhịp điệu, nhấn mạnh, chuyển động, tỉ lệ, hài hoà. Hoạt động thực hành và thảo luận Thực hành – Vẽ tranh bố cục từ những hình khối cơ bản bằng chất liệu màu bột (hoặc màu nước, hoặc chất liệu tương đương). Thảo luận – Tranh bố cục hình khối cơ bản. – Sản phẩm thực hành của học sinh. Định hướng chủ đề: Tự chọn.', 'lesson', 2, NULL, NULL, '2026-10-26T13:43:04.133Z', '2026-10-26T13:43:04.133Z');
