INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('a3a35e0a-59c7-578f-ae60-b463f58ca458', '3abe78bc-5040-596f-8791-68248ccd2af7', '6c3f1b66-b102-517c-a508-e91f70d00861', '– Các thời kì phát triển của văn minh Đông Nam Á Một số thành tựu tiêu biểu của văn minh Đông Nam Á – Tôn giáo và tín ngưỡng – Văn tự và văn học – Kiến trúc và điêu khắc', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.314Z', '2026-10-26T13:42:59.314Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('a57a7b96-3200-5d35-b33c-eaf2541a00e8', 'f5caeec6-d931-5019-a22a-ce7e574d5cac', 'fb69a3b5-d746-519d-a93f-ae31d2f34e49', '– Khái niệm thạch quyển – Nội lực và ngoại lực – Sự phân bố các vành đai động đất, núi lửa Khí quyển', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.778Z', '2026-10-26T13:42:59.778Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('3221e715-3701-5fe4-bc1b-b0c91e075d42', 'f5caeec6-d931-5019-a22a-ce7e574d5cac', 'd27c2f33-7ff5-5946-9a03-ebb8db94f1fe', 'Địa lí các ngành kinh tế', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.817Z', '2026-10-26T13:42:59.817Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('53fae08c-7728-5719-8380-c0ed4e175dcd', '06bad7ec-6930-5ee7-98a7-0adb0c6c1338', 'bb66fdb7-944d-5ec1-bf32-7abac2a464ba', 'Cấu trúc tế bào', 'topic', 3, NULL, NULL, '2026-10-26T13:43:01.456Z', '2026-10-26T13:43:01.456Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e7f1bdc2-bebd-540e-9ea8-130d26375a5c', 'e49a08b8-a8c2-5c16-856d-6a7115406dda', '97c29557-6a9e-551e-b6db-cfc57c82b2da', ' Sự vận chuyển các chất trong cây', 'lesson', 3, NULL, NULL, '2026-10-26T13:43:01.531Z', '2026-10-26T13:43:01.531Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('5bbb157f-a74b-5851-a0af-65887fc4ba0b', '3abe78bc-5040-596f-8791-68248ccd2af7', '3529fb4a-f424-5017-9604-657f032215ba', 'Khối đại đoàn kết dân tộc trong lịch sử Việt Nam Khối đại đoàn kết dân tộc trong lịch sử Việt Nam – Sự hình thành khối đại đoàn kết dân tộc – Vai trò của khối đại đoàn kết dân tộc trong lịch sử dựng nước và giữ nước – Vai trò của khối đại đoàn kết dân tộc trong sự nghiệp xây dựng và bảo vệ Tổ quốc hiện nay Chính sách dân tộc của Đảng và Nhà nước hiện nay – Quan điểm của Đảng và Nhà nước về chính sách dân tộc – Nội dung cơ bản trong chính sách dân tộc của Đảng và Nhà nước – Tiến hành các hoạt động giáo dục lịch sử gắn với thực địa, tham quan di sản lịch sử, văn hoá,... – Tham quan các bảo tàng, xem phim tài liệu lịch sử. – Tổ chức các câu lạc bộ “Em yêu lịch sử”, “Nhà sử học trẻ tuổi”,... – Tổ chức các cuộc thi tìm hiểu lịch sử, các trò chơi lịch sử,...', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.357Z', '2026-10-26T13:42:59.357Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('82a43c83-2a7c-5970-9c46-6d1f4bd90565', '3abe78bc-5040-596f-8791-68248ccd2af7', 'cf909885-7ccc-5615-a039-622b1284d1f9', 'Một số lĩnh vực của lịch sử Việt Nam Lịch sử văn hoá Việt Nam – Đối tượng và phạm vi của lịch sử văn hoá Việt Nam – Khái lược tiến trình lịch sử văn hoá Việt Nam Lịch sử tư tưởng Việt Nam – Đối tượng, phạm vi của lịch sử tư tưởng Việt Nam – Khái lược lịch sử tư tưởng Việt Nam Lịch sử xã hội Việt Nam – Đối tượng của lịch sử xã hội – Khái lược về xã hội Việt Nam truyền thống và hiện đại Lịch sử kinh tế Việt Nam – Đối tượng của lịch sử kinh tế – Khái lược lịch sử kinh tế Việt Nam', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.375Z', '2026-10-26T13:42:59.375Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e08b94a7-9182-5341-bbe2-6151bf370310', '3abe78bc-5040-596f-8791-68248ccd2af7', '769cd45d-a1b5-5ae2-840e-b2eb5bc5bbed', 'Giới thiệu một số di sản văn hoá vật thể tiêu biểu – Trống đồng Đông Sơn – Thành Cổ Loa – Hoàng thành Thăng Long – Văn Miếu – Quốc Tử Giám (Hà Nội) – Quảng trường Ba Đình và Di tích lịch sử Khu lưu niệm Chủ tịch Hồ Chí Minh – Thành Nhà Hồ – Cố đô Huế – Tháp Chăm – ... Giới thiệu một số di sản thiên nhiên tiêu biểu – Các Công viên địa chất: Cao nguyên đá Đồng Văn, Non nước Cao Bằng – Vịnh Hạ Long – Vườn quốc gia Cúc Phương – Vườn quốc gia Cát Tiên – ... Giới thiệu một số di sản phức hợp tiêu biểu – Khu di tích – danh thắng Tràng An (Ninh Bình) – Khu di tích – danh thắng Yên Tử (Quảng Ninh)', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.392Z', '2026-10-26T13:42:59.392Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('940039c1-4a25-5fa5-97f3-4ef557d609e3', '3abe78bc-5040-596f-8791-68248ccd2af7', 'be34c357-7976-5fd9-b677-2681046fdefb', 'Cộng hoà – Vai trò của Nhà nước Việt Nam Dân chủ Cộng hoà trong quá trình kháng chiến chống giặc ngoại xâm và xây dựng đất nước thời kì 1945 – 1976', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.406Z', '2026-10-26T13:42:59.406Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0add09c7-b8af-5a54-ba42-b695519c8869', '76292f4e-349e-5c0d-b604-978666a1929e', '7c10c386-ab47-5cbc-afa1-6cbb240bb4ab', '– Cuộc kháng chiến chống quân Nam Hán và chiến thắng Bạch Đằng năm 938 – Cuộc kháng chiến chống Tống năm 981 và năm 1075 – 1077 – Ba lần kháng chiến chống quân Mông – Nguyên – Kháng chiến chống quân Xiêm năm 1784 – 1785 – Kháng chiến chống quân Thanh năm 1789', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.457Z', '2026-10-26T13:42:59.457Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('db373e3d-f71b-5a74-81e5-38a71536f8f1', '76292f4e-349e-5c0d-b604-978666a1929e', 'd0b096e7-3e8f-5883-8d84-a19fb4cdefda', 'Chiến tranh và hoà bình từ sau năm 1945 đến nay Chiến tranh lạnh (1947 – 1989) – Nguyên nhân, đặc điểm – Hậu quả – Kết thúc Chiến tranh lạnh: nguyên nhân và tác động Chiến tranh, xung đột quân sự sau Chiến tranh lạnh – Các cuộc nội chiến, xung đột quân sự khu vực – Cuộc tấn công khủng bố ngày 11 tháng 9 năm 2001 và cuộc chiến chống khủng bố toàn cầu của Mỹ Đấu tranh vì hoà bình của nhân dân thế giới – Đấu tranh chống chạy đua vũ trang, vì hoà bình của nhân dân', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.529Z', '2026-10-26T13:42:59.529Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('4b845729-7968-5373-946a-3cf1f36a5735', '76292f4e-349e-5c0d-b604-978666a1929e', '13900579-44d7-5353-a8eb-b78d9350174a', 'Một số danh nhân quân sự Việt Nam (Gợi ý lựa chọn) Ngô Quyền Trần Quốc Tuấn Nguyễn Huệ Võ Nguyên Giáp ...', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.543Z', '2026-10-26T13:42:59.543Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('97500900-b7da-5037-ae07-1f5c4c489d3c', 'f24fc9c1-5b58-504b-8d04-adede0146230', '8d253aec-14af-55cd-9243-a83410670762', 'Trật tự thế giới sau Chiến tranh lạnh Những chuyển biến của tình hình thế giới sau Chiến tranh lạnh – Xu thế phát triển chính của thế giới sau Chiến tranh lạnh – Sự điều chỉnh chiến lược phát triển của các quốc gia Xu thế đa cực trong quan hệ quốc tế – Khái niệm đa cực – Xu thế đa cực', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.560Z', '2026-10-26T13:42:59.560Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('c5874285-9617-545d-a978-4bf35ab50cb4', 'f24fc9c1-5b58-504b-8d04-adede0146230', '38b7cfda-ac5d-578a-8001-225a60a60520', 'Những năm đầu thế kỉ XXI đến nay Nước Mỹ từ đầu thế kỉ XXI đến nay – Tác động của sự kiện ngày 11 tháng 9 năm 2001 đối với nước Mỹ – Khái lược tình hình kinh tế – xã hội Mỹ những năm đầu thế kỉ XXI Những nét chính về quá trình phát triển kinh tế – xã hội Mỹ từ năm 1945 đến nay – Về sự phát triển kinh tế – Về những biến đổi chính trị, xã hội', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.571Z', '2026-10-26T13:42:59.571Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('5368dbd6-b3e8-520c-8793-ff7b718192a1', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'fc45161a-38fc-5b99-860d-8cea6dc1c71d', '– Giai đoạn 2012 – 2020', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.581Z', '2026-10-26T13:42:59.581Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('0982bdf6-f6c6-52cc-83c6-91b5d96c039c', 'f24fc9c1-5b58-504b-8d04-adede0146230', '5ffd9f6d-a6bb-59cf-b723-43e6cdfbf2e1', 'Cuộc kháng chiến chống Mỹ, cứu nước (1954 – 1975) Khái quát về cuộc kháng chiến chống Mỹ, cứu nước – Bối cảnh lịch sử – Các giai đoạn phát triển chính Nguyên nhân thắng lợi, vị trí, ý nghĩa lịch sử của cuộc kháng chiến chống Mỹ, cứu nước trong tiến trình lịch sử Việt Nam – Nguyên nhân thắng lợi – Vị trí, ý nghĩa lịch sử', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.599Z', '2026-10-26T13:42:59.599Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('cccb4bab-e926-5a16-b7df-1ab47fc92321', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'c1339d33-090e-5288-945b-32e70b33f827', '– Xây dựng, hoàn thiện hệ thống chính trị – Vượt qua tình trạng bị bao vây cấm vận, tích cực và chủ động hội nhập quốc tế – Giải quyết các vấn đề xã hội, phát triển văn hoá, con người Một số bài học kinh nghiệm – Kiên trì mục tiêu độc lập dân tộc và chủ nghĩa xã hội trên nền tảng chủ nghĩa Mác – Lênin và tư tưởng Hồ Chí Minh – Đổi mới toàn diện, đồng bộ, có bước đi, hình thức và cách làm phù hợp – Đổi mới phải vì lợi ích của nhân dân, phát huy vai trò chủ động, sáng tạo của nhân dân – Kết hợp sức mạnh nội lực và ngoại lực, kết hợp sức mạnh dân tộc với sức mạnh thời đại trong điều kiện mới', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.618Z', '2026-10-26T13:42:59.618Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('930350f0-7de2-5451-b115-c4dcb20a6439', 'f24fc9c1-5b58-504b-8d04-adede0146230', '3c7ad644-7d7d-5d49-960d-94eea3812bcb', '– Giai đoạn 1945 – 1946 – Giai đoạn 1946 – 1954 – Giai đoạn 1954 – 1969', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.642Z', '2026-10-26T13:42:59.642Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('153b2f97-56b4-5271-ba4f-4b898f1b1d27', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'b9bc0760-f686-562d-ac29-046612935296', 'Nho giáo Phật giáo Cơ Đốc giáo Đạo giáo Tôn giáo khác', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.657Z', '2026-10-26T13:42:59.657Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('65afe06c-0f3d-524b-8b17-41e5846060e5', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'd2d13623-c1c9-5d16-b13e-f8f0212aaf9b', 'Bài học thành công từ lịch sử Nhật Bản – Về nhân tố con người – Về vai trò của Nhà nước – Về hệ thống tổ chức, quản lí sản xuất – Về truyền thống lịch sử, văn hoá', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.675Z', '2026-10-26T13:42:59.675Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('ac9ab8be-69d7-50fb-81a9-0ea7efd22ee7', 'a604fc8e-f22a-5223-9b62-d948ea1a064a', 'd755c5c1-417b-54e0-9c62-0eb3d3ac2dcb', '– Vị trí địa lí và điều kiện tự nhiên – Dân cư, xã hội – Kinh tế – Hiệp hội các quốc gia Đông Nam Á (ASEAN) – Hoạt động kinh tế đối ngoại Khu vực Tây Nam Á', 'lesson', 3, NULL, NULL, '2026-10-26T13:42:59.878Z', '2026-10-26T13:42:59.878Z');
