INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('51834085-a614-517c-94a2-cd58c563ccfa', '3abe78bc-5040-596f-8791-68248ccd2af7', 'be34c357-7976-5fd9-b677-2681046fdefb', 'Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam từ năm 1976 đến nay Sự ra đời của Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam – Bối cảnh ra đời của Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam – Ý nghĩa lịch sử của việc ra đời Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam Vai trò của Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam – Vai trò của Nhà nước Cộng hoà Xã hội chủ nghĩa Việt Nam trong quá trình đổi mới và hội nhập quốc tế', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.409Z', '2026-10-26T13:42:59.409Z');
