INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('33d7ccd6-c6ab-50d5-b659-665f783f15ad', '76292f4e-349e-5c0d-b604-978666a1929e', 'd0b096e7-3e8f-5883-8d84-a19fb4cdefda', 'thế giới trong Chiến tranh lạnh – Phong trào quốc tế ủng hộ cuộc đấu tranh giải phóng dân tộc, ủng hộ cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam – Đấu tranh vì hoà bình của nhân dân thế giới sau Chiến tranh lạnh', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.533Z', '2026-10-26T13:42:59.533Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('79002408-c6d7-5ea7-8dd0-9517399bcbd5', '76292f4e-349e-5c0d-b604-978666a1929e', '13900579-44d7-5353-a8eb-b78d9350174a', 'Một số danh nhân văn hoá Việt Nam (Gợi ý lựa chọn) Trần Nhân Tông Nguyễn Trãi Nguyễn Du Hồ Xuân Hương …', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.546Z', '2026-10-26T13:42:59.546Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('a60526e1-d54f-5edd-a057-e44aedd7e5f1', 'f24fc9c1-5b58-504b-8d04-adede0146230', 'fc45161a-38fc-5b99-860d-8cea6dc1c71d', 'Thành tựu chính và một số đặc điểm của cải cách mở cửa Những thành tựu chính – Về kinh tế – xã hội – Về khoa học công nghệ, văn hoá, giáo dục – Về đối ngoại Một số đặc điểm của cải cách mở cửa – Về bối cảnh lịch sử – Về phương thức cải cách mở cửa – Về quá trình cải cách mở cửa', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.583Z', '2026-10-26T13:42:59.583Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('88dca6aa-aa84-5a1d-8e5c-3adb9459d620', 'f24fc9c1-5b58-504b-8d04-adede0146230', '5ffd9f6d-a6bb-59cf-b723-43e6cdfbf2e1', 'Đấu tranh bảo vệ Tổ quốc từ sau tháng 4 năm 1975 đến nay Khái quát về cuộc đấu tranh bảo vệ Tổ quốc từ sau tháng 4 năm 1975 đến nay – Bối cảnh lịch sử – Diễn biến chính Ý nghĩa lịch sử của cuộc đấu tranh bảo vệ Tổ quốc từ sau tháng 4 năm 1975 đến nay – Ý nghĩa lịch sử', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.605Z', '2026-10-26T13:42:59.605Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('e670ce59-e204-5d06-a0a3-e84d4b1d97eb', 'f24fc9c1-5b58-504b-8d04-adede0146230', '3c7ad644-7d7d-5d49-960d-94eea3812bcb', 'Dấu ấn Hồ Chí Minh trong lòng nhân dân thế giới và Việt Nam Hồ Chí Minh trong lòng nhân dân thế giới – Danh hiệu: + Năm 1987, UNESCO công nhận Hồ Chí Minh là anh hùng giải phóng dân tộc, nhà văn hoá lớn + Nhân dân thế giới đánh giá cao những cống hiến và những giá trị tư tưởng và văn hoá của Hồ Chí Minh – Tưởng niệm: Nhà lưu niệm; Đài kỉ niệm; Đặt tên một số đại lộ,... Hồ Chí Minh trong lòng nhân dân Việt Nam – Bảo tàng, Nhà lưu niệm – Hình tượng văn học, nghệ thuật – Phong trào học tập và làm theo tư tưởng, đạo đức và phong cách Hồ Chí Minh', 'lesson', 4, NULL, NULL, '2026-10-26T13:42:59.645Z', '2026-10-26T13:42:59.645Z');
