INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('931ebcc4-d731-5cc3-939c-a57b6ed3963e', '46741ca8-f5a1-5005-ae08-244498e0f812', '1a5b41d9-1987-5c83-bb4f-73484ee0cd86', '– Ý nghĩa chiến lược của Biển Đông trong việc phát triển kinh tế và đảm bảo an ninh cho đất nước; hướng chung trong giải quyết các tranh chấp vùng biển - đảo Thực hành tìm hiểu Địa lí địa phương (tỉnh, thành phố trực thuộc trung ương) theo các chủ đề sau đây: – Vị trí địa lí, phạm vi lãnh thổ và sự – Trình bày được vị trí địa lí, phạm vi lãnh thổ và sự phân chia hành chính của phân chia hành chính tỉnh, thành phố trực thuộc trung ương dựa trên bản đồ của địa phương, Việt Nam hoặc atlat địa lí Việt Nam và kiến thức đã có. – Tự nhiên và tài nguyên thiên nhiên – Sử dụng bản đồ, lược đồ, biểu đồ, số liệu thống kê,..., phân tích được một số đặc điểm nổi bật về tự nhiên, dân cư - xã hội, kinh tế của địa phương. – Dân cư và xã hội – Kinh tế – Thu thập được tài liệu, tranh ảnh, số liệu,... để giới thiệu về địa lí địa phương. – Viết được báo cáo giới thiệu địa lí địa phương theo một số chủ đề.', 'lesson', 10, NULL, NULL, '2026-10-26T13:43:00.016Z', '2026-10-26T13:43:00.016Z');
