INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('60dc560a-8e1d-5639-98a1-51a82bb06caf', '0f18d272-722d-5b4f-ae27-e3b37420a5a9', 'afd27f74-15ac-5bbd-ac37-f70ef42d3df3', 'Nói nghe tương tác', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:56.567Z', '2026-10-26T13:42:56.567Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b6be8ff4-89b5-580f-a09a-20b0d5e53835', 'a89be4d8-5938-5fd9-8661-218c4a328bbf', 'e85bf343-589e-5f81-b4bc-96dc2a94abcd', 'Quy trình viết', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:56.759Z', '2026-10-26T13:42:56.759Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('52f1dd5a-3a83-550c-abe4-fb6ed1047def', 'a89be4d8-5938-5fd9-8661-218c4a328bbf', 'ec0e1b89-bd8b-5be1-a62b-b879773b15bd', 'Thực hành viết', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:56.763Z', '2026-10-26T13:42:56.763Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('6610324e-cdbd-575f-8491-2bcc053d7edc', 'e5f9f989-ea21-562d-a385-98d537b75522', '11a02d6d-4843-5cca-8a50-78efd13d0831', '1.1. Âm, vần, thanh; chữ và dấu thanh 1.2. Quy tắc chính tả phân biệt: c và k, g và gh, ng và ngh 1.3. Quy tắc viết hoa: viết hoa chữ cái đầu câu, viết hoa tên riêng 2. Vốn từ theo chủ điểm: Từ chỉ sự vật, hoạt động, đặc điểm gần gũi 3. Công dụng của dấu chấm, dấu chấm hỏi: đánh dấu kết thúc câu 4.1. Từ xưng hô thông dụng khi giao tiếp ở nhà và ở trường 4.2. Một số nghi thức giao tiếp thông dụng ở nhà và ở trường: chào hỏi, giới thiệu, cảm ơn, xin lỗi, xin phép 5. Thông tin bằng hình ảnh (phương tiện giao tiếp phi ngôn ngữ)', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:55.977Z', '2026-10-26T13:42:55.977Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('604890a4-ba03-522e-a0a8-82a06e586443', 'e5f9f989-ea21-562d-a385-98d537b75522', '11bede1a-4b5e-5cdc-96fe-369b7eafdbbe', '1. Câu chuyện, bài thơ 2. Nhân vật trong truyện', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:55.979Z', '2026-10-26T13:42:55.979Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b5893066-d193-5425-8139-89b566f9bf51', 'f152dd73-2f20-510f-9ce0-a11cb5143864', '78fb2f49-0d51-5d7f-bab1-b16a702c5776', '1. Chủ đề 2. Kết thúc câu chuyện 3. Chuyện có thật và chuyện tưởng tượng 4. Chi tiết, thời gian, địa điểm trong câu chuyện; hình ảnh trong thơ 5. Nhân vật trong văn bản kịch và lời thoại', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:56.282Z', '2026-10-26T13:42:56.282Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('7a5f2a0b-e084-5da0-9262-8ca149d27997', 'e5f9f989-ea21-562d-a385-98d537b75522', '5a2b6e7d-4481-5e86-906e-3e794d114230', '1.1. Văn bản văn học – Cổ tích, ngụ ngôn, truyện ngắn, truyện tranh, đoạn văn miêu tả – Đoạn thơ, bài thơ (gồm cả đồng dao) Độ dài của văn bản: truyện và đoạn văn miêu tả khoảng 90 – 130 chữ, thơ khoảng 50 – 70 chữ 1.2. Văn bản thông tin: giới thiệu những sự vật, sự việc gần gũi với học sinh Độ dài của văn bản: khoảng 90 chữ 2. Gợi ý chọn văn bản: xem danh mục gợi ý 3. Các từ ngữ có ý nghĩa tích cực, phù hợp với học sinh lớp 1', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:55.982Z', '2026-10-26T13:42:55.982Z');
