INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('d98798a7-4a30-561b-ad07-501a76bca577', 'bd38778b-25cf-5bab-a2d4-daf42241e103', '0ee74691-4298-50a5-8c1c-5102231ed676', '- Màu sắc - Các con vật - Đồ vật trong lớp - Đồ chơi - Hoạt động hằng ngày - Số đếm - Hoạt động trong lớp/ gia đình - Ngôi nhà - Các loại quả/ đồ ăn - Bộ phận cơ thể - Số đếm - ...', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:56.926Z', '2026-10-26T13:42:56.926Z');
