INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('50de680d-c063-53de-aaa1-0acfbf5f1b57', '4c30aa32-10be-5051-bbb8-ddbb880dfd6b', '227e379c-a0af-50e4-9649-7f1b195b8b2b', '- Bản thân - Những người bạn của em - Những việc có thể làm - Hoạt động hằng ngày - Hoạt động tương lai - Thói quen, sở thích …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.403Z', '2026-10-26T13:42:57.403Z');
