INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('b89369b0-b16c-5697-a943-6ee8ca5dc114', '4c30aa32-10be-5051-bbb8-ddbb880dfd6b', '7a4d9679-1011-5ba8-b2b7-df4326110675', '- Ngôi nhà của em - Phòng và đồ vật trong nhà - Thành viên trong gia đình - Ngoại hình, nghề nghiệp của các thành viên trong gia đình - Hoạt động của các thành viên trong gia đình …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.421Z', '2026-10-26T13:42:57.421Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('98def913-4f17-59d9-a610-75dfb082c00f', '4c30aa32-10be-5051-bbb8-ddbb880dfd6b', 'b44472e2-e432-59c3-96f2-c6b6e114a902', '- Đồ chơi của em - Động vật - Màu sắc yêu thích - Quần áo - Chỉ đường và biển chỉ dẫn - Mùa và thời tiết - Phương tiện giao thông …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.425Z', '2026-10-26T13:42:57.425Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('f90b957c-d27b-5e62-bedd-175b7446e599', '9b1583b5-1b17-5bcf-b8ae-2dff7cbb55d3', '4e83ebec-ad22-53ea-9fde-77dfff755c44', '- Ngôi trường của tôi - Sở thích - Những người bạn của tôi - Tuổi thiếu niên - Hoạt động trong thời gian rảnh rỗi - Môi trường địa phương - Dịch vụ cộng đồng …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.431Z', '2026-10-26T13:42:57.431Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('65252b2d-4fa5-5c81-a4b6-90523e928426', '9b1583b5-1b17-5bcf-b8ae-2dff7cbb55d3', 'd06566f4-c398-5e21-a956-24e7fdad1b49', '- Kỳ quan và địa danh nổi tiếng - Lễ hội - Phong tục và tập quán - Thức ăn và đồ uống - Âm nhạc và mỹ thuật …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.435Z', '2026-10-26T13:42:57.435Z');
INSERT INTO "curriculum_nodes" ("id", "curriculum_id", "parent_id", "title", "kind", "position", "duration_periods", "duration_percent", "created_at", "updated_at") VALUES ('05c40c5f-737d-5d32-a8c0-a5cec3a8aed5', '9b1583b5-1b17-5bcf-b8ae-2dff7cbb55d3', '85d3e40d-8865-5a4b-9666-f492cb12aa2b', '- Các thành phố trên thế giới - Văn hoá của các quốc gia trên thế giới - Lễ hội - Giao thông - Các môn thể thao và trò chơi - Du lịch - Giải trí …', 'lesson', 1, NULL, NULL, '2026-10-26T13:42:57.439Z', '2026-10-26T13:42:57.439Z');
