INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-253a-7972-8d29-93c22da5467b', NULL, '465f6e52-a1d2-5863-8332-616da16e5dd7', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn, chẳng hạn: – Thực hành đếm, nhận biết số, thực hiện phép tính trong một số tình huống thực tiễn hằng ngày (ví dụ: đếm số bàn học và số cửa sổ trong lớp học,...). – Thực hành các hoạt động liên quan đến vị trí, định hướng không gian (ví dụ: xác định được một vật ở trên hoặc dưới mặt bàn, một vật cao hơn hoặc thấp hơn vật khác,...). – Thực hành đo và ước lượng độ dài một số đồ vật trong thực tế gắn với đơn vị đo cm; thực hành đọc giờ đúng trên đồng hồ, xem lịch loại lịch tờ hằng ngày.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 24 — bản ghi TOAN-0011', NULL, NULL, '2026-10-26T13:42:54.522Z', '2026-10-26T13:42:54.522Z');
