INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25e0-7106-bbf6-2a8707d55ed7', NULL, '68b704fc-8308-55f8-bda1-0c03e863f8ab', 'Nêu được một số nhận xét đơn giản từ bảng số liệu.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 33 — bản ghi TOAN-0048', NULL, NULL, '2026-10-26T13:42:54.686Z', '2026-10-26T13:42:54.686Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25e6-7979-8f83-9c87768b99ea', NULL, '0c83c7e5-f82a-5b13-8c54-22d96f1f704b', 'Nhận biết và mô tả được các khả năng xảy ra (có tính ngẫu nhiên) của một sự kiện khi thực hiện (1 lần) thí nghiệm đơn giản (ví dụ: nhận ra được hai khả năng xảy ra đối với mặt xuất hiện của đồng xu khi tung 1 lần; nhận ra được hai khả năng xảy ra đối với màu của quả bóng lấy ra từ hộp kín đựng các quả bóng có hai màu xanh hoặc đỏ;...).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 33 — bản ghi TOAN-0049', NULL, NULL, '2026-10-26T13:42:54.693Z', '2026-10-26T13:42:54.693Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25ec-7851-b521-fe73069cca6e', NULL, '56b414a4-72a7-509a-8637-b83624e0f634', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 33, 34 — bản ghi TOAN-0050', NULL, NULL, '2026-10-26T13:42:54.699Z', '2026-10-26T13:42:54.699Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25f1-70bb-a88d-6e65b50dcb67', NULL, '54e2cc02-169e-587e-a247-65216442e17b', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn, chẳng hạn: – Thực hành các hoạt động liên quan đến tính toán, đo lường và ước lượng như: thực hành tính và ước lượng chu vi, diện tích của một số hình phẳng trong thực tế liên quan đến các hình phẳng đã được học; thực hành đo, cân, đong và ước lượng độ dài, khối lượng, dung tích, nhiệt độ,... – Thực hành thu thập, phân loại, sắp xếp số liệu thống kê (theo các tiêu chí cho trước) về một số đối tượng thống kê trong trường, lớp.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 33, 34 — bản ghi TOAN-0051', NULL, NULL, '2026-10-26T13:42:54.704Z', '2026-10-26T13:42:54.704Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25f5-7918-9b6a-3fd29f51ef16', NULL, '4bf41d53-9e14-5424-9412-83d275e31e6a', 'Tổ chức các hoạt động ngoài giờ chính khoá (ví dụ: trò chơi học Toán hoặc các hoạt động “Học vui – Vui học”; trò chơi liên quan đến mua bán, trao đổi hàng hoá; lắp ghép, gấp, xếp hình; tung đồng xu, xúc xắc,...) liên quan đến ôn tập, củng cố các kiến thức toán.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 33, 34 — bản ghi TOAN-0052', NULL, NULL, '2026-10-26T13:42:54.706Z', '2026-10-26T13:42:54.706Z');
