INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2640-7c04-a7c2-639e3fa0ef3d', NULL, 'abdeae2a-d552-5135-bf29-2b03f5fce2f3', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán có đến hai hoặc ba bước tính (trong phạm vi các số và phép tính đã học) liên quan đến thành phần và kết quả của phép tính; liên quan đến các mối quan hệ so sánh trực tiếp hoặc các mối quan hệ phụ thuộc trực tiếp và đơn giản (ví dụ: bài toán liên quan đến tìm số trung bình cộng của hai số; tìm hai số khi biết tổng và hiệu của hai số đó; bài toán liên quan đến rút về đơn vị).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 36 — bản ghi TOAN-0060', NULL, NULL, '2026-10-26T13:42:54.783Z', '2026-10-26T13:42:54.783Z');
