INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2677-7eb1-a9ff-28a147684259', NULL, '62f43ea9-6a41-51ff-a3bb-f0de36ae1b86', 'Kiểm đếm được số lần lặp lại của một khả năng xảy ra (nhiều lần) của một sự kiện khi thực hiện (nhiều lần) thí nghiệm, trò chơi đơn giản (ví dụ: trong một vài trò chơi như tung đồng xu, lấy bóng từ hộp kín,...).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 39 — bản ghi TOAN-0074', NULL, NULL, '2026-10-26T13:42:54.838Z', '2026-10-26T13:42:54.838Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-267b-734e-be4a-a036bc2659af', NULL, '2dbb158d-aa76-5493-a543-3177b82db156', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 39, 40 — bản ghi TOAN-0075', NULL, NULL, '2026-10-26T13:42:54.842Z', '2026-10-26T13:42:54.842Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-267d-717e-bc03-f039bbc23269', NULL, '5cec7c04-e5e1-5ea3-9101-6aaccffb4d5f', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Thực hành các hoạt động liên quan đến tính toán, đo lường và ước lượng như: tính toán và ước lượng chu vi, diện tích, góc của một số hình phẳng trong thực tế liên quan đến các hình phẳng đã học; tính toán và ước lượng về khối lượng, dung tích,...; xác định năm, thế kỉ đánh dấu sự ra đời (diễn ra) của một số phát minh khoa học, sự kiện văn hoá – xã hội, lịch sử,... – Thực hành thu thập, phân tích, biểu diễn các số liệu thống kê (thông qua một số tình huống đơn giản gắn với những vấn đề phát triển kinh tế, xã hội hoặc có tính toàn cầu như biến đổi khí hậu, phát triển bền vững, giáo dục tài chính, chủ quyền biển đảo, biên giới, giáo dục STEM,...). – Thực hành mua bán, trao đổi tiền tệ.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 39, 40 — bản ghi TOAN-0076', NULL, NULL, '2026-10-26T13:42:54.844Z', '2026-10-26T13:42:54.844Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-267f-71f9-9d42-030d656bce69', NULL, 'b8cef45b-7738-52ed-b493-a6b43c422996', 'Tổ chức các hoạt động ngoài giờ chính khoá (ví dụ: trò chơi học toán hoặc các hoạt động “Học vui – Vui học”; trò chơi liên quan đến mua bán, trao đổi hàng hoá; lắp ghép, gấp, xếp hình; tung đồng xu, xúc xắc,...) liên quan đến ôn tập, củng cố các kiến thức toán hoặc giải quyết vấn đề nảy sinh trong tình huống thực tiễn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 39, 40 — bản ghi TOAN-0077', NULL, NULL, '2026-10-26T13:42:54.846Z', '2026-10-26T13:42:54.846Z');
