INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-26bf-7b22-9121-dd2a64c6b16f', NULL, 'bde979cc-a43b-57ef-ab69-cdbb58e14295', 'Sử dụng được tỉ số để mô tả số lần lặp lại của một khả năng xảy ra (nhiều lần) của một sự kiện trong một thí nghiệm so với tổng số lần thực hiện thí 2 nghiệm đó ở những trường hợp đơn giản (ví dụ: sử dụng tỉ số để mô tả 5 2 lần xảy ra khả năng “mặt sấp đồng xu xuất hiện” của khi tung đồng xu 5 lần).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 45, 46 — bản ghi TOAN-0096', NULL, NULL, '2026-10-26T13:42:54.911Z', '2026-10-26T13:42:54.911Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-26c1-7c8b-97a7-43fefd40d342', NULL, '20232856-242a-5521-b2e9-ebfc4c05183f', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 46 — bản ghi TOAN-0097', NULL, NULL, '2026-10-26T13:42:54.913Z', '2026-10-26T13:42:54.913Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-26c4-7899-88c0-525e74763a27', NULL, 'f34fcfd5-ed13-5deb-95bb-bf2446014390', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Thực hành tổng hợp các hoạt động liên quan đến tính toán, đo lường và ước lượng như: tính toán và ước lượng thể tích của một số hình khối trong thực tiễn liên quan đến các hình đã học; tính toán và ước lượng về vận tốc, quãng đường, thời gian trong chuyển động đều. – Thực hành thu thập, phân tích, biểu diễn các số liệu thống kê (thông qua một số tình huống đơn giản gắn với những vấn đề phát triển kinh tế – xã hội hoặc có tính toàn cầu như biến đổi khí hậu, phát triển bền vững, giáo dục tài chính, chủ quyền biên giới, biển đảo, giáo dục STEM,...). – Thực hành mua bán, trao đổi, chi tiêu hợp lí; thực hành tính tiền lãi, lỗ trong mua bán; tính lãi suất trong tiền gửi tiết kiệm và vay vốn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 46 — bản ghi TOAN-0098', NULL, NULL, '2026-10-26T13:42:54.915Z', '2026-10-26T13:42:54.915Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-26c6-72a7-b941-a17e1db30edf', NULL, '399db6df-d74f-581c-badd-5729817f4573', 'Tổ chức các hoạt động ngoài giờ chính khoá (ví dụ: trò chơi “Bảy mảnh nghìn hình (tangram)” hoặc các hoạt động “Học vui – Vui học”; trò chơi liên quan đến mua bán, trao đổi hàng hoá; lắp ghép, gấp, xếp hình; tung đồng xu, xúc xắc,...) liên quan đến ôn tập, củng cố các kiến thức toán hoặc giải quyết vấn đề nảy sinh trong tình huống thực tiễn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 46 — bản ghi TOAN-0099', NULL, NULL, '2026-10-26T13:42:54.917Z', '2026-10-26T13:42:54.917Z');
