INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2713-7435-944f-352304e52777', NULL, 'eca7ad51-4c07-55c6-8c7f-c97287f4a8d6', 'Sử dụng được phân số để mô tả xác suất (thực nghiệm) của khả năng xảy ra nhiều lần thông qua kiểm đếm số lần lặp lại của khả năng đó trong một số mô hình xác suất đơn giản.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54 — bản ghi TOAN-0122', NULL, NULL, '2026-10-26T13:42:54.994Z', '2026-10-26T13:42:54.994Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-271d-76c5-9fac-b0bd55afab92', NULL, '7818b98b-7f17-51e7-a980-181b7d045cb9', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54, 55 — bản ghi TOAN-0123', NULL, NULL, '2026-10-26T13:42:55.003Z', '2026-10-26T13:42:55.003Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2722-7761-b4b9-4ee64b657420', NULL, '62f9906a-1635-5e79-815a-faae6fb926a5', 'Tìm hiểu một số kiến thức về tài chính: – Làm quen với việc gửi tiền tiết kiệm và vay vốn ngân hàng; tính lỗ, lãi và dư nợ; thực hành tính lãi suất trong tiền gửi tiết kiệm và vay vốn. – Trả số tiền đúng theo hoá đơn hoặc tính tiền thừa khi mua hàng; thực hành ghi chép thu nhập và chi tiêu, cất giữ hoá đơn trong trường hợp cần sử dụng đến.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54, 55 — bản ghi TOAN-0124', NULL, NULL, '2026-10-26T13:42:55.009Z', '2026-10-26T13:42:55.009Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2726-7773-ad52-26f391465a61', NULL, '470cf526-be7a-5061-8638-c66312abe073', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Vận dụng kiến thức thống kê để đọc hiểu các bảng biểu trong môn Lịch sử và Địa lí lớp 6. – Thu thập và biểu diễn các dữ liệu từ một vài tình huống trong thực tiễn, ví dụ: thu thập nhiệt độ của địa phương tại mốc thời gian nhất định trong một tuần lễ, từ đó đưa ra những nhận xét về biến đổi thời tiết của địa phương trong tuần.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54, 55 — bản ghi TOAN-0125', NULL, NULL, '2026-10-26T13:42:55.013Z', '2026-10-26T13:42:55.013Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-272a-7c24-b834-dd92d764ad2c', NULL, '6a9d7578-f7d8-5e6b-897e-68437e38bfb0', 'Tổ chức các hoạt động ngoài giờ chính khoá như thực hành ngoài lớp học, dự án học tập, các trò chơi học toán, cuộc thi về Toán, chẳng hạn: – Vận dụng tính đối xứng vào thực tiễn: gấp giấy tạo dựng các hình có trục đối xứng hoặc tâm đối xứng; sưu tầm các hình trong tự nhiên có tâm đối xứng hoặc có trục đối xứng; tìm kiếm các video về hình có tâm đối xứng, hình có trục đối xứng trong thế giới tự nhiên. – Vận dụng khái niệm ba điểm thẳng hàng vào thực tiễn như: trồng cây thẳng hàng, để các đồ vật thẳng hàng,... – Vận dụng các công thức tính diện tích và thể tích vào thực tiễn. Đo đạc và tính diện tích bề mặt, tính thể tích của các đồ vật có liên quan đến các hình đã học.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54, 55 — bản ghi TOAN-0126', NULL, NULL, '2026-10-26T13:42:55.017Z', '2026-10-26T13:42:55.017Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-272d-7532-a2cd-fe218af4ebd9', NULL, '42501ffb-c0ea-5ec4-ac3e-335cb00b1bfa', 'Tổ chức giao lưu với học sinh có khả năng và yêu thích môn Toán trong trường và trường bạn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 54, 55 — bản ghi TOAN-0127', NULL, NULL, '2026-10-26T13:42:55.020Z', '2026-10-26T13:42:55.020Z');
