INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2798-7d8f-9d34-369c8ceb400d', NULL, '56ee6f3c-4d74-5e82-a66a-efa999ed09b8', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 62, 63 — bản ghi TOAN-0149', NULL, NULL, '2026-10-26T13:42:55.128Z', '2026-10-26T13:42:55.128Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-279b-77c2-8e33-d162ddf1714d', NULL, '5fcf2010-c379-59bc-8d51-b57dd29b6ac9', 'Tìm hiểu một số kiến thức về tài chính: – Thực hành tính toán việc tăng, giảm theo giá trị phần trăm của một mặt hàng hoặc một kế hoạch sản xuất, kinh doanh. – Làm quen với giao dịch ngân hàng. – Làm quen với thuế và việc tính thuế.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 62, 63 — bản ghi TOAN-0150', NULL, NULL, '2026-10-26T13:42:55.130Z', '2026-10-26T13:42:55.130Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-279e-7188-9bbd-a3701dd2251d', NULL, '60ec181b-7da3-54b6-804d-417d049e8b7f', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Vận dụng kiến thức thống kê để đọc hiểu các bảng biểu trong Lịch sử và Địa lí lớp 7, Khoa học tự nhiên lớp 7. – Thu thập, phân loại và biểu diễn dữ liệu (theo các tiêu chí cho trước) vào biểu đồ hình quạt tròn (pie chart) hoặc biểu đồ đoạn thẳng (line graph) từ một vài tình huống trong thực tiễn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 62, 63 — bản ghi TOAN-0151', NULL, NULL, '2026-10-26T13:42:55.133Z', '2026-10-26T13:42:55.133Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27a0-790c-bda8-570427bcd1d5', NULL, 'b71e5fbd-5904-557e-832d-4aa054538850', 'Tổ chức các hoạt động ngoài giờ chính khoá như thực hành ngoài lớp học, dự án học tập, các trò chơi học Toán, cuộc thi về Toán, chẳng hạn: – Tạo dựng các hình có liên quan đến tia phân giác của một góc, liên quan đến hai đường song song, liên quan đến hình lăng trụ đứng. – Vận dụng kiến thức về tam giác bằng nhau trong thực tiễn, ví dụ: đo khoảng cách giữa hai vị trí mà giữa chúng có vật cản hoặc chỉ đến được một trong hai vị trí. – Thu thập một số vật thể trong thực tiễn có dạng hình lăng trụ đứng và tính diện tích xung quanh của các vật thể đó.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 62, 63 — bản ghi TOAN-0152', NULL, NULL, '2026-10-26T13:42:55.135Z', '2026-10-26T13:42:55.135Z');
