INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27f0-7284-97da-eb8cb8424f93', NULL, '13a7342c-2a64-5eae-af06-750d8cee7f09', 'Thực hiện và lí giải được việc thu thập, phân loại dữ liệu theo các tiêu chí cho trước từ nhiều nguồn khác nhau: văn bản; bảng biểu; kiến thức trong các lĩnh vực giáo dục khác (Địa lí, Lịch sử, Giáo dục môi trường, Giáo dục tài chính,...); phỏng vấn, truyền thông, Internet; thực tiễn (môi trường, tài chính, y tế, giá cả thị trường,...).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 68 — bản ghi TOAN-0167', NULL, NULL, '2026-10-26T13:42:55.215Z', '2026-10-26T13:42:55.215Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27f2-7b23-a095-493f7cb0ff16', NULL, 'c7acc1f0-69e3-5269-b9d5-b3d1b1f0100c', 'Lựa chọn và biểu diễn được dữ liệu vào bảng, biểu đồ thích hợp ở dạng: bảng thống kê; biểu đồ tranh; biểu đồ dạng cột/cột kép (column chart), biểu đồ hình quạt tròn (cho sẵn) (pie chart); biểu đồ đoạn thẳng (line graph).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 68, 69 — bản ghi TOAN-0168', NULL, NULL, '2026-10-26T13:42:55.218Z', '2026-10-26T13:42:55.218Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27f5-7be1-9285-893f2963a76c', NULL, '635a5f40-5cda-5cf5-b24e-0aff49555de5', 'Phát hiện được vấn đề hoặc quy luật đơn giản dựa trên phân tích các số liệu thu được ở dạng: bảng thống kê; biểu đồ tranh; biểu đồ dạng cột/cột kép (column chart), biểu đồ hình quạt tròn (pie chart); biểu đồ đoạn thẳng (line graph).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 69 — bản ghi TOAN-0169', NULL, NULL, '2026-10-26T13:42:55.221Z', '2026-10-26T13:42:55.221Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27f9-7caf-868e-b6dcb0fff84a', NULL, '85b83cbb-2a6e-52de-96e3-d76728a6fc59', 'Sử dụng được tỉ số để mô tả xác suất của một biến cố ngẫu nhiên trong một số ví dụ đơn giản.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 69 — bản ghi TOAN-0170', NULL, NULL, '2026-10-26T13:42:55.225Z', '2026-10-26T13:42:55.225Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-27fe-7a48-b2e8-d1ef2eaf9e6d', NULL, '082588fe-3ece-59a7-9d33-b2b980af7ea7', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 70 — bản ghi TOAN-0172', NULL, NULL, '2026-10-26T13:42:55.230Z', '2026-10-26T13:42:55.230Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2800-7675-8f6b-19a474550965', NULL, '43c987c7-5690-5d9e-a414-8f4083ae0af2', 'Tìm hiểu một số kiến thức về tài chính như: – Lập kế hoạch chi tiêu của bản thân. – Làm quen với bài toán về đầu tư cá nhân (xác định vốn đầu tư để đạt được lãi suất mong đợi). – Hiểu được các bản sao kê của ngân hàng (bản sao kê thật hoặc ví dụ) để xác định giao dịch và theo dõi thu nhập và chi tiêu; lựa chọn hình thức thanh toán phù hợp.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 70 — bản ghi TOAN-0173', NULL, NULL, '2026-10-26T13:42:55.231Z', '2026-10-26T13:42:55.231Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2802-7b37-93ad-e6a57741dc6c', NULL, '396489a7-c399-547d-aeff-489042e2bf4d', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Vận dụng kiến thức Đại số để giải thích một số quy tắc trong Hoá học, Sinh học. Ví dụ: Ứng dụng phương trình bậc nhất trong các bài toán về xác định nồng độ phần trăm.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 70 — bản ghi TOAN-0174', NULL, NULL, '2026-10-26T13:42:55.233Z', '2026-10-26T13:42:55.233Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2804-7c1c-91db-d984a32bc1cd', NULL, '993993c7-f56f-58a7-8e11-aa9bc000c869', 'Tổ chức các hoạt động ngoài giờ chính khoá như thực hành ngoài lớp học, dự án học tập, các trò chơi học toán, cuộc thi về Toán, chẳng hạn: – Tìm kiếm hoặc thực hành tạo dựng các đoạn video về ứng dụng của hình chóp, hình đồng dạng phối cảnh trong thế giới tự nhiên. – Vận dụng kiến thức về tam giác đồng dạng và định lí Pythagore trong thực tiễn (ví dụ: đo khoảng cách giữa hai vị trí mà giữa chúng có vật cản hoặc chỉ đến được một trong hai vị trí). – Thực hành tính diện tích, thể tích của một số hình, khối trong thực tế.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 70 — bản ghi TOAN-0175', NULL, NULL, '2026-10-26T13:42:55.236Z', '2026-10-26T13:42:55.236Z');
