INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2888-7d58-bbc6-3c34f201b2a8', NULL, '276102dd-131b-5b7f-8402-dc9fae78d86c', 'Tìm hiểu một số kiến thức về tài chính như: – Thực hành lập kế hoạch đầu tư cá nhân. – Làm quen với bảo hiểm. – Làm quen với bài toán về tăng trưởng (xác định vốn đầu tư để đạt được tỉ lệ tăng trưởng mong đợi).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 78 — bản ghi TOAN-0199', NULL, NULL, '2026-10-26T13:42:55.368Z', '2026-10-26T13:42:55.368Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-288b-7454-944b-d14005ef74f9', NULL, 'a648c33e-1518-5ad7-8caa-b3761f79dd37', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Vận dụng kiến thức về hệ phương trình bậc nhất hai ẩn trong bài toán cân bằng hệ số ở phương trình hoá học. – Vận dụng kiến thức về xác suất trong việc tính xác suất kết quả đời con của các phép lai.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 78 — bản ghi TOAN-0200', NULL, NULL, '2026-10-26T13:42:55.370Z', '2026-10-26T13:42:55.370Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-288d-71df-bff5-46002211e05c', NULL, '24e58a1c-7276-53c6-ae14-7ec69cd48e8b', 'Tổ chức các hoạt động ngoài giờ chính khoá như thực hành ngoài lớp học, dự án học tập, các trò chơi học toán, cuộc thi về Toán, chẳng hạn: – Vận dụng kiến thức về tỉ số lượng giác trong thực tiễn (ví dụ: đo khoảng cách giữa hai vị trí mà giữa chúng có vật cản hoặc chỉ đến được một trong hai vị trí). – Vận dụng các công thức tính diện tích, thể tích vào thực tiễn: đo đạc và tính diện tích, thể tích của các hình khối trong khuôn viên của trường có liên quan đến hình trụ, hình nón, hình cầu. – Tìm kiếm hoặc thực hành tạo dựng các đoạn video liên quan đến đường tròn, tam giác vuông, đa giác đều và phép quay.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 78 — bản ghi TOAN-0201', NULL, NULL, '2026-10-26T13:42:55.372Z', '2026-10-26T13:42:55.372Z');
