INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2b33-703a-89ad-b768cd8d6624', NULL, 'c14d2ed5-8260-55b0-b2cc-47d1c5fc9950', 'Biết trao đổi trong nhóm về các nhân vật trong một câu chuyện dựa vào gợi ý.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 26 — bản ghi NV-0032', NULL, NULL, '2026-10-26T13:42:56.050Z', '2026-10-26T13:42:56.050Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-28e8-7931-bad8-5e768e068e01', NULL, '752cd20b-1c43-5d8b-ae1c-d184e2fb3063', 'Nhà trường tổ chức cho học sinh một số hoạt động sau và có thể bổ sung các hoạt động khác tuỳ vào điều kiện cụ thể.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 87 — bản ghi TOAN-0225', NULL, NULL, '2026-10-26T13:42:55.462Z', '2026-10-26T13:42:55.462Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-28ec-713c-90e6-bbf11340a336', NULL, '6dd09f9f-ad04-5491-b59d-a9defabcee66', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Thực hành tổng hợp các hoạt động liên quan đến tính toán, đo lường, ước lượng và tạo lập hình, như: tính tiền khi đi taxi theo các khung giá: dưới 1km, từ 1 – 10km, từ 10 – 31km, trên 31km,...; đo đạc một vài yếu tố của vật thể mà chúng ta không thể dùng dụng cụ đo đạc để đo trực tiếp; tính chiều cao của công trình kiến trúc dạng Parabola (như cầu Nhật Tân, cầu Trường Tiền, cầu Mỹ Thuận,...); giải thích các hiện tượng, quy luật trong Vật lí; thực hành vẽ, cắt hình có dạng Ellipse (elip). – Thực hành mô tả và biểu diễn dữ liệu trên các bảng, biểu đồ.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 87 — bản ghi TOAN-0226', NULL, NULL, '2026-10-26T13:42:55.467Z', '2026-10-26T13:42:55.467Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-28ee-7bea-bc1e-5149d1489c81', NULL, 'c65dda40-f038-5d45-8962-aaa0fac64ec1', 'Tìm hiểu một số kiến thức về tài chính, như: – Hiểu sự khác biệt giữa tiết kiệm và đầu tư. – Thực hành thiết lập kế hoạch đầu tư cá nhân để đạt được tỉ lệ tăng trưởng như mong đợi.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 87 — bản ghi TOAN-0227', NULL, NULL, '2026-10-26T13:42:55.470Z', '2026-10-26T13:42:55.470Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-28f1-77f7-b45a-fa95b7a43376', NULL, '9e03eb72-3c51-510d-92b5-6652fdb1b734', 'Tổ chức các hoạt động ngoài giờ chính khoá như các câu lạc bộ toán học, dự án học tập, trò chơi học toán, cuộc thi về Toán, chẳng hạn: thi tìm hiểu lịch sử toán học, tổ chức sinh hoạt câu lạc bộ toán học theo các chủ đề (tìm hiểu các ứng dụng của hàm số bậc hai, vectơ trong thực tiễn,...).', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 87 — bản ghi TOAN-0228', NULL, NULL, '2026-10-26T13:42:55.472Z', '2026-10-26T13:42:55.472Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-28f4-7bd5-9da0-7ecaeccde09e', NULL, '943973e4-3e56-5eb2-b8c0-3560e0849995', 'Tổ chức giao lưu học sinh giỏi trong trường và trường bạn, với các chuyên gia nhằm hiểu nhiều hơn về vai trò của Toán học trong thực tiễn và trong các ngành nghề.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 87 — bản ghi TOAN-0229', NULL, NULL, '2026-10-26T13:42:55.475Z', '2026-10-26T13:42:55.475Z');
