INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2995-7f94-8132-dad101adfea5', NULL, '2c0f4de5-bbea-5aef-ba31-1cbc9e2de185', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: Thực hành tổng hợp các hoạt động liên quan đến tính toán, đo lường, ước lượng và vận dụng các kiến thức hình học không gian vào đồ hoạ, vẽ kĩ thuật, như: vận dụng kiến thức về hàm số lượng giác vào tìm hiểu hệ thống hướng dẫn cất cánh và hạ cánh của máy bay, tìm hiểu hệ thống xác định phần tử bắn của pháo binh, tên lửa; vận dụng kiến thức về xác suất thống kê để giải thích các quy luật di truyền học; vận dụng các kiến thức hình học không gian vào đồ hoạ, vẽ kĩ thuật và thiết kế trong công nghệ.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 103 — bản ghi TOAN-0266', NULL, NULL, '2026-10-26T13:42:55.637Z', '2026-10-26T13:42:55.637Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2997-7b5f-bba6-565e38536c52', NULL, '9819fbc7-7313-5714-8d40-715c46d637df', 'Thực hành ứng dụng các kiến thức toán học vào lĩnh vực Giáo dục dân số, chẳng hạn: vận dụng cấp số cộng, cấp số nhân để giải thích quy luật tăng trưởng dân số; vận dụng hàm số mũ, hàm số lôgarit để giải thích ảnh hưởng của sự tăng trưởng dân số tới tiến bộ kinh tế – xã hội, giải thích mối liên hệ giữa sự tăng trưởng dân số với môi trường sinh thái,...', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 103 — bản ghi TOAN-0267', NULL, NULL, '2026-10-26T13:42:55.639Z', '2026-10-26T13:42:55.639Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2999-7702-b9b7-3f93a9d41fa5', NULL, '92166a7a-f27a-5030-b6ce-81ce6f87d67b', 'Tìm hiểu một số kiến thức về tài chính, như: – Thực hành lên kế hoạch và quản lí thu nhập và tích luỹ của cải trong khoảng thời gian ngắn hạn và trung hạn. – Xác định được các phương thức để bảo vệ bản thân khỏi rủi ro.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 103 — bản ghi TOAN-0268', NULL, NULL, '2026-10-26T13:42:55.640Z', '2026-10-26T13:42:55.640Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-299b-7366-81c5-5e45893c4d51', NULL, 'd0bd5f6f-6421-5bc3-a9a8-7b3d535c8436', 'Tổ chức các hoạt động ngoài giờ chính khoá: câu lạc bộ toán học; cuộc thi về Toán, dự án học tập, ra báo tường (hoặc nội san) về Toán, như: câu lạc bộ về ứng dụng toán học trong khoa học máy tính và công nghệ thông tin,...', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 103 — bản ghi TOAN-0269', NULL, NULL, '2026-10-26T13:42:55.642Z', '2026-10-26T13:42:55.642Z');
