INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-29ec-798c-879d-367e8d4f3490', NULL, 'e4343ed7-5a73-51c3-a65e-ef46b50806e5', 'Thực hành ứng dụng các kiến thức toán học vào thực tiễn và các chủ đề liên môn, chẳng hạn: – Thực hành tổng hợp các hoạt động liên quan đến tính toán, đo lường, ước lượng và tạo lập hình. – Vận dụng kiến thức về phương pháp toạ độ trong hình học không gian để tìm hiểu hệ thống GPS, tìm hiểu về đồ hoạ, vẽ kĩ thuật và thiết kế trong Công nghệ. – Vận dụng kiến thức về đạo hàm để giải thích các quy luật của Vật lí (quy luật âm học, quang học), Hoá học và giải quyết bài toán tối ưu về kinh tế, thời gian, quãng đường,...', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 111 — bản ghi TOAN-0291', NULL, NULL, '2026-10-26T13:42:55.724Z', '2026-10-26T13:42:55.724Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-29ee-7494-8cd5-01727d91958c', NULL, '540319f0-e83d-5b6c-ad54-33ee21ab3376', 'Vận dụng các kiến thức toán học vào một số vấn đề liên quan đến tài chính.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 111 — bản ghi TOAN-0292', NULL, NULL, '2026-10-26T13:42:55.725Z', '2026-10-26T13:42:55.725Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-29f0-7f81-8306-ceb4a742a9d0', NULL, '70ea62c9-8c5d-5b67-b444-0a77f710c7c6', 'Tổ chức các hoạt động ngoài giờ chính khoá: câu lạc bộ toán học; cuộc thi về Toán; dự án học tập; ra báo tường (hoặc nội san) về Toán, chẳng hạn: câu lạc bộ về ứng dụng toán học trong khoa học máy tính và công nghệ thông tin.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 111 — bản ghi TOAN-0293', NULL, NULL, '2026-10-26T13:42:55.728Z', '2026-10-26T13:42:55.728Z');
