INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2bf5-78be-94dd-2c38094ed5d7', NULL, '402eeb34-8edf-5335-8e48-7ed6223ee76c', 'Biết viết hoa danh từ chung trong một số trường hợp đặc biệt khi muốn thể hiện sự tôn kính. Biết viết đúng tên người, tên địa lí nước ngoài.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 38 — bản ghi NV-0081', NULL, NULL, '2026-10-26T13:42:56.244Z', '2026-10-26T13:42:56.244Z');
