INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dbf-7609-a3d0-4e1594b1c515', NULL, '3711af70-6dcf-565a-ba85-37d493054835', 'Phân tích được các chi tiết tiêu biểu, đề tài, câu chuyện, sự kiện, nhân vật và mối quan hệ của chúng trong tính chỉnh thể của tác phẩm; nhận xét được những chi tiết quan trọng trong việc thể hiện nội dung văn bản.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 65, 66 — bản ghi NV-0193', NULL, NULL, '2026-10-26T13:42:56.702Z', '2026-10-26T13:42:56.702Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dc6-7b73-bc26-3877c623802e', NULL, '1a167205-e661-5015-9b62-a33d3aa0b4ba', 'Nhận biết và phân tích được một số đặc điểm cơ bản của ngôn ngữ văn học. Phân tích được tính đa nghĩa của ngôn từ trong tác phẩm văn học.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 66 — bản ghi NV-0194', NULL, NULL, '2026-10-26T13:42:56.709Z', '2026-10-26T13:42:56.709Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dd2-7c38-b5f3-210db1c8b5ff', NULL, 'c49f3c64-60de-52c1-9898-3efcf577b9ec', 'Vận dụng được những hiểu biết về tác giả Nguyễn Du để đọc hiểu một số tác phẩm của tác giả này.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 67 — bản ghi NV-0195', NULL, NULL, '2026-10-26T13:42:56.721Z', '2026-10-26T13:42:56.721Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dd9-729a-84e7-cee33063cce2', NULL, '8f4ab6ba-3bc1-5849-8a95-f65f4b1f4593', 'Trong 1 năm học, đọc tối thiểu 35 văn bản văn học (bao gồm cả văn bản được hướng dẫn đọc trên mạng Internet) có thể loại và độ dài tương đương với các văn bản đã học. Học thuộc lòng một số đoạn thơ, bài thơ yêu thích trong chương trình.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 67 — bản ghi NV-0196', NULL, NULL, '2026-10-26T13:42:56.728Z', '2026-10-26T13:42:56.728Z');
