INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2de6-7212-a316-2ac0c6dd6a40', NULL, '3b73684f-029a-5072-bf99-323488b75a74', 'Liên hệ được nội dung văn bản với một tư tưởng, quan niệm, xu thế (kinh tế, chính trị, văn hoá, xã hội, khoa học) của giai đoạn mà văn bản ra đời để hiểu sâu hơn.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68 — bản ghi NV-0199', NULL, NULL, '2026-10-26T13:42:56.741Z', '2026-10-26T13:42:56.741Z');
