INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2def-7178-a53b-bdcdb8eaf4dc', NULL, '3bacd9b6-c630-5861-9136-4babd9e10d55', 'Nhận biết được bố cục, mạch lạc của văn bản, cách trình bày dữ liệu, thông tin của người viết và đánh giá hiệu quả của chúng.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68, 69 — bản ghi NV-0202', NULL, NULL, '2026-10-26T13:42:56.750Z', '2026-10-26T13:42:56.750Z');
