INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2df7-7e63-bdf2-ace46d379a8d', NULL, 'b6be8ff4-89b5-580f-a09a-20b0d5e53835', 'Biết viết văn bản đúng quy trình, bảo đảm các bước đã được hình thành và rèn luyện ở các lớp trước.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 69 — bản ghi NV-0205', NULL, NULL, '2026-10-26T13:42:56.759Z', '2026-10-26T13:42:56.759Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dfc-7d5d-8e68-f168b76cdf62', NULL, '52f1dd5a-3a83-550c-abe4-fb6ed1047def', 'Viết được văn bản nghị luận về một vấn đề xã hội, trình bày rõ quan điểm và hệ thống các luận điểm; cấu trúc chặt chẽ, có mở đầu và kết thúc gây ấn tượng; sử dụng các lí lẽ và bằng chứng thuyết phục: chính xác, tin cậy, thích hợp, đầy đủ.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 69, 70 — bản ghi NV-0206', NULL, NULL, '2026-10-26T13:42:56.763Z', '2026-10-26T13:42:56.763Z');
