INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2e48-7a7b-9930-dfeb12877262', NULL, '506c2625-6372-5d37-8d6f-723565a956ac', 'Nhận biết, phân tích được nội dung của luận đề, luận điểm, lí lẽ và bằng chứng tiêu biểu, độc đáo trong văn bản; chỉ ra mối liên hệ của chúng; đánh giá được mức độ phù hợp giữa nội dung nghị luận với nhan đề của văn bản.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 74 — bản ghi NV-0220', NULL, NULL, '2026-10-26T13:42:56.839Z', '2026-10-26T13:42:56.839Z');
