INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2e5b-7022-bd62-23a5fec316cb', NULL, '74667321-6b14-5e84-83a7-69d8d543898b', 'Nhận biết được bố cục, mạch lạc của văn bản; đánh giá được sự phù hợp giữa nội dung và nhan đề văn bản; đề xuất được các nhan đề văn bản khác.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 75 — bản ghi NV-0225', NULL, NULL, '2026-10-26T13:42:56.858Z', '2026-10-26T13:42:56.858Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2e5d-7c16-be14-434dffa87b13', NULL, 'a084805f-a6f3-5547-b6b0-f5b205076e80', 'So sánh được hiệu quả biểu đạt của văn bản thông tin chỉ dùng ngôn ngữ và văn bản thông tin có kết hợp với các yếu tố phi ngôn ngữ.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 75 — bản ghi NV-0226', NULL, NULL, '2026-10-26T13:42:56.861Z', '2026-10-26T13:42:56.861Z');
