INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2e68-7dbb-a422-e736e0c070b5', NULL, '3e3191c3-7eac-579f-8209-30bbfa59664e', 'Viết được một bài phát biểu trong lễ phát động một phong trào hoặc một hoạt động xã hội; trình bày rõ hệ thống các luận điểm; có cấu trúc chặt chẽ, có mở đầu và kết thúc gây ấn tượng; sử dụng các lí lẽ và bằng chứng thuyết phục: chính xác, tin cậy, thích hợp, đầy đủ; biết đặt ra các ý kiến phản bác để trao đổi, tranh luận lại; sử dụng các yếu tố thuyết minh và biểu cảm.', 1, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 76 — bản ghi NV-0229', NULL, NULL, '2026-10-26T13:42:56.871Z', '2026-10-26T13:42:56.871Z');
