INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-383e-7755-9570-fdfde0d720d7', NULL, 'e65417c0-7872-52b2-8022-de134022257e', 'văn hoá trong quá trình phát triển bền vững của đất nước. – Nêu được các giải pháp bảo tồn và phát huy giá trị di sản văn hoá: tuyên truyền giáo dục ý thức bảo tồn di sản, đầu tư cơ sở vật chất, tăng cường biện pháp bảo vệ di sản,... – Giải thích được vai trò của hệ thống chính trị, doanh nghiệp, cộng đồng dân cư và của mỗi cá nhân trong công tác bảo tồn và phát huy giá trị di sản văn hoá. – Trình bày được trách nhiệm của Nhà nước, tổ chức xã hội, nhà trường, cộng đồng, công dân trong việc bảo tồn và phát huy giá trị di sản thông qua ví dụ cụ thể. – Có ý thức trách nhiệm và sẵn sàng đóng góp và vận động người khác cùng tham gia vào việc bảo tồn và phát huy giá trị các di sản văn hoá ở địa phương và đất nước.', 1, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 27 — bản ghi LS-0024', NULL, NULL, '2026-10-26T13:42:59.389Z', '2026-10-26T13:42:59.389Z');
