INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3b26-7bad-927a-880370bc90d2', NULL, '371c37d9-10ba-5c7a-972c-9c9e4b083ba7', 'Dựa vào sơ đồ, hình ảnh, mẫu vật, phân biệt được các nhóm thực vật: Thực vật không có mạch (Rêu); Thực vật có mạch, không có hạt (Dương xỉ); Thực vật có mạch, có hạt (Hạt trần); Thực vật có mạch, có hạt, có hoa (Hạt kín).', 1, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 29 — bản ghi KHTN-0015', NULL, NULL, '2026-10-26T13:43:00.132Z', '2026-10-26T13:43:00.132Z');
