INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c49-72d8-bc95-f171dd1e4729', NULL, '9ffe208c-79d2-50a9-9399-11fe9670ece1', 'Nêu được khái niệm môi trường sống của sinh vật, phân biệt được 4 môi trường sống chủ yếu: môi trường trên cạn, môi trường dưới nước, môi trường trong đất và môi trường sinh vật. Lấy được ví dụ minh hoạ các môi trường sống của sinh vật.', 1, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 57 — bản ghi KHTN-0077', NULL, NULL, '2026-10-26T13:43:00.424Z', '2026-10-26T13:43:00.424Z');
