INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d0b-7a75-904e-b03911291d84', NULL, '16769d44-95db-56f8-bf75-b12d4b831326', 'Quan sát hình ảnh (hoặc sơ đồ), mô tả sơ lược quá trình tái bản của DNA gồm các giai đoạn: tháo xoắn tách hai mạch đơn, các nucleotide tự do trong môi trường tế bào kết hợp 2 mạch đơn theo nguyên tắc bổ sung. Kết quả tạo 2 DNA con giống DNA mẹ, từ đó nêu được ý nghĩa di truyền của tái bản DNA.', 1, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 72 — bản ghi KHTN-0116', NULL, NULL, '2026-10-26T13:43:00.618Z', '2026-10-26T13:43:00.618Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d0d-7e54-bee9-6248f1945d9c', NULL, '81443fda-047c-5599-9f14-0213d37389c0', 'Dựa vào sơ đồ, hình ảnh quá trình phiên mã, nêu được khái niệm phiên mã.', 1, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 72 — bản ghi KHTN-0117', NULL, NULL, '2026-10-26T13:43:00.621Z', '2026-10-26T13:43:00.621Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d10-708e-a8c5-0a95f0be8149', NULL, '46e58a4b-0b99-58ff-91a2-edf27cc14e96', 'Nêu được khái niệm mã di truyền, giải thích được từ 4 loại nucleotide tạo ra được sự đa dạng của mã di truyền; nêu được ý nghĩa của đa dạng mã di truyền, mã di truyền quy định thành phần hoá học và cấu trúc của protein.', 1, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 72, 73 — bản ghi KHTN-0118', NULL, NULL, '2026-10-26T13:43:00.623Z', '2026-10-26T13:43:00.623Z');
