INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3dea-789f-ab7e-f74e27c3cd89', NULL, 'd073e7dd-cf1b-5296-a700-0b4815206bf6', 'Thảo luận qua quan sát hình ảnh (hoặc tài liệu đa phương tiện) nêu được điện thế tại một điểm trong điện trường đặc trưng cho điện trường tại điểm đó về thế năng, được xác định bằng công dịch chuyển một đơn vị điện tích dương từ vô cực về điểm đó; thế năng của một điện tích q trong điện trường đặc trưng cho khả năng sinh công của điện trường khi đặt điện tích q tại điểm đang xét.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 20 — bản ghi VL-0042', NULL, NULL, '2026-10-26T13:43:00.841Z', '2026-10-26T13:43:00.841Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ded-7f3b-9d2d-0e113763fecb', NULL, 'b48c11c0-917d-5f87-853d-fea25fb128b6', 'Định nghĩa được điện dung và đơn vị đo điện dung (fara).', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 20 — bản ghi VL-0043', NULL, NULL, '2026-10-26T13:43:00.845Z', '2026-10-26T13:43:00.845Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3df2-7fd8-a078-54ac3e10a38d', NULL, '3a2a1fb4-422f-5977-bda6-833492519dcd', 'Thực hiện thí nghiệm (hoặc dựa vào tài liệu đa phương tiện), nêu được cường độ dòng điện đặc trưng cho tác dụng mạnh yếu của dòng điện và được xác định bằng điện lượng chuyển qua tiết diện thẳng của vật dẫn trong một đơn vị thời gian.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 20, 21 — bản ghi VL-0044', NULL, NULL, '2026-10-26T13:43:00.850Z', '2026-10-26T13:43:00.850Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3df6-7fb5-b11f-d90f0f512158', NULL, '98ef322c-a257-5e43-80c0-9393204cc3ed', 'Định nghĩa được điện trở, đơn vị đo điện trở và nêu được các nguyên nhân chính gây ra điện trở.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 21 — bản ghi VL-0045', NULL, NULL, '2026-10-26T13:43:00.854Z', '2026-10-26T13:43:00.854Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3dfd-72eb-8088-0fe123854928', NULL, '44e73c8c-e39f-5fa5-9018-a05a34aa4114', 'Nêu được năng lượng điện tiêu thụ của đoạn mạch được đo bằng công của lực điện thực hiện khi dịch chuyển các điện tích; công suất tiêu thụ năng lượng điện của một đoạn mạch là năng lượng điện mà đoạn mạch tiêu thụ trong một đơn vị thời gian.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 21, 22 — bản ghi VL-0046', NULL, NULL, '2026-10-26T13:43:00.860Z', '2026-10-26T13:43:00.860Z');
