INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e1f-7bcd-bd08-617de0d2dc8f', NULL, '8ac0b6af-cf3f-561b-b947-ea025190de3a', 'Tham quan thực tế (hoặc qua tài liệu đa phương tiện), thảo luận để nêu được một số ứng dụng chính của thiết bị cảm biến và nguyên tắc hoạt động của thiết bị cảm biến.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 24 — bản ghi VL-0056', NULL, NULL, '2026-10-26T13:43:00.895Z', '2026-10-26T13:43:00.895Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e21-79f6-aa59-3b00948dbb6e', NULL, '526c46dc-008c-5ce4-8aee-caccefc2d261', 'Sử dụng mô hình động học phân tử, nêu được sơ lược cấu trúc của chất rắn, chất lỏng, chất khí.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 24 — bản ghi VL-0057', NULL, NULL, '2026-10-26T13:43:00.897Z', '2026-10-26T13:43:00.897Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e23-7e98-999e-20875a57c014', NULL, '8a8f20ad-8f32-504b-af6b-6a1c71fafc6e', 'Thực hiện thí nghiệm, nêu được: mối liên hệ nội năng của vật với năng lượng của các phân tử tạo nên vật, định luật 1 của nhiệt động lực học.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 24 — bản ghi VL-0058', NULL, NULL, '2026-10-26T13:43:00.899Z', '2026-10-26T13:43:00.899Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e26-7343-a6d1-a3307b9d85b6', NULL, 'e263c04c-472d-51ac-8fae-9dd557ca8aca', 'Thực hiện thí nghiệm đơn giản, thảo luận để nêu được sự chênh lệch nhiệt độ giữa hai vật tiếp xúc nhau có thể cho ta biết chiều truyền năng lượng nhiệt giữa chúng; từ đó nêu được khi hai vật tiếp xúc với nhau, ở cùng nhiệt độ, sẽ không có sự truyền năng lượng nhiệt giữa chúng.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 24, 25 — bản ghi VL-0059', NULL, NULL, '2026-10-26T13:43:00.901Z', '2026-10-26T13:43:00.901Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e29-77c3-b890-c4e6c9c6983b', NULL, '2681c1a0-66f2-53ea-b3b9-02207971f7c5', 'Nêu được định nghĩa nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 25 — bản ghi VL-0060', NULL, NULL, '2026-10-26T13:43:00.905Z', '2026-10-26T13:43:00.905Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e2d-7023-80c4-cd59cd66f204', NULL, 'c094003c-cd30-5430-b6e0-da5914818299', 'Phân tích mô hình chuyển động Brown, nêu được các phân tử trong chất khí chuyển động hỗn loạn.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 25 — bản ghi VL-0061', NULL, NULL, '2026-10-26T13:43:00.908Z', '2026-10-26T13:43:00.908Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e30-7234-bb09-e14bd20c7727', NULL, '09a07d79-5960-53c4-9422-f48f23873d7b', 'Thực hiện thí nghiệm khảo sát được định luật Boyle: Khi giữ không đổi nhiệt độ của một khối lượng khí xác định thì áp suất gây ra bởi khí tỉ lệ nghịch với thể tích của nó.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 25 — bản ghi VL-0062', NULL, NULL, '2026-10-26T13:43:00.911Z', '2026-10-26T13:43:00.911Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e33-78cf-a830-984ef45544b5', NULL, 'dd25e683-3794-5109-80e7-e7a94633436c', 'Giải thích được chuyển động của các phân tử ảnh hưởng như thế nào đến áp suất tác dụng lên thành bình và từ đó rút ra được hệ thức p = (1/3)nmv2 với n là số phân tử trong một đơn vị thể tích (dùng mô hình va chạm một chiều đơn giản, rồi mở rộng ra cho trường hợp ba chiều bằng cách sử dụng hệ thức (1/3)v2 = v2x, không yêu cầu chứng minh một cách chính xác và chi tiết).', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 25, 26 — bản ghi VL-0063', NULL, NULL, '2026-10-26T13:43:00.915Z', '2026-10-26T13:43:00.915Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e36-7c4d-8671-ea2c5c767bf0', NULL, '59dbe531-a68c-5afb-bf36-cb5e65ba4c9a', 'Nêu được biểu thức hằng số Boltzmann, k = R/NA.', 1, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 26 — bản ghi VL-0065', NULL, NULL, '2026-10-26T13:43:00.918Z', '2026-10-26T13:43:00.918Z');
