INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-409c-7677-9e22-a42f41e9e69f', NULL, 'e7f1bdc2-bebd-540e-9ea8-130d26375a5c', 'Nêu được sự vận chuyển các chất trong cây theo hai dòng: dòng mạch gỗ và dòng mạch rây.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 25 — bản ghi SH-0023', NULL, NULL, '2026-10-26T13:43:01.531Z', '2026-10-26T13:43:01.531Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-409f-78fb-838c-1c4fca823cb4', NULL, 'e69579cf-2e56-54d5-a4c7-879a169d5148', 'Trình bày được cơ chế đóng mở khí khổng thực hiện chức năng điều tiết quá trình thoát hơi nước. Giải thích được vai trò quan trọng của sự thoát hơi nước đối với đời sống của cây.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 25 — bản ghi SH-0024', NULL, NULL, '2026-10-26T13:43:01.534Z', '2026-10-26T13:43:01.534Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40a1-7af2-aa67-d21e7bb33f1f', NULL, '7f87f6ef-bc81-54f8-9c37-ee5144554514', 'Nêu được khái niệm dinh dưỡng ở thực vật và vai trò sinh lí của một số nguyên tố khoáng đối với thực vật (cụ thể một số nguyên tố đa lượng, vi lượng).', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 25, 26 — bản ghi SH-0025', NULL, NULL, '2026-10-26T13:43:01.536Z', '2026-10-26T13:43:01.536Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40a3-7c4d-bd52-e73bd8dc55e7', NULL, '6e6777ae-b6fb-5b8f-ba73-27dfbbb6fb9e', 'Quan sát và nhận biết được một số biểu hiện của cây do thiếu khoáng.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 26 — bản ghi SH-0026', NULL, NULL, '2026-10-26T13:43:01.539Z', '2026-10-26T13:43:01.539Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40a8-7843-8a64-323b18b1fdb8', NULL, '65523b24-a177-5072-9431-1038858dcef6', 'Phân tích được một số nhân tố ảnh hưởng đến trao đổi nước ở thực vật và ứng dụng hiểu biết này vào thực tiễn.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 26 — bản ghi SH-0028', NULL, NULL, '2026-10-26T13:43:01.543Z', '2026-10-26T13:43:01.543Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40ad-79b6-b7c0-35f0a97dbddf', NULL, 'bb849537-b9fd-5ee0-91de-17d1510b5b4c', 'Phát biểu được khái niệm quang hợp ở thực vật. Viết được phương trình quang hợp. Nêu được vai trò của quang hợp ở thực vật (vai trò đối với cây, với sinh vật và sinh quyển).', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 26 — bản ghi SH-0029', NULL, NULL, '2026-10-26T13:43:01.548Z', '2026-10-26T13:43:01.548Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40b0-7fa2-bd8d-63a6780ddd67', NULL, 'bcfcaf93-31b0-50e8-952b-448b55bb8f59', 'Trình bày được vai trò của sắc tố trong việc hấp thụ năng lượng ánh sáng. Nêu được các sản phẩm của quá trình biến đổi năng lượng ánh sáng thành năng lượng hoá học (ATP và NADPH).', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 27 — bản ghi SH-0030', NULL, NULL, '2026-10-26T13:43:01.552Z', '2026-10-26T13:43:01.552Z');
