INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-40d3-7bc3-908c-8bab3d5a2a98', NULL, '32e9d577-d009-5a0d-ba7d-8673de259372', 'Giải thích được một số hiện tượng trong thực tiễn, ví dụ: nuôi tôm, cá thường cần có máy sục khí oxygen, nuôi ếch chú ý giữ môi trường ẩm ướt,...', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 28, 29 — bản ghi SH-0043', NULL, NULL, '2026-10-26T13:43:01.587Z', '2026-10-26T13:43:01.587Z');
