INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41fd-707f-a3ba-21c6109f9c78', NULL, 'ee1a0d27-9a53-522c-a510-6cdba8995c44', 'Trình bày được các đặc trưng cơ bản của quần thể sinh vật (số lượng cá thể, kích thước quần thể, tỉ lệ giới tính, nhóm tuổi, kiểu phân bố, mật độ cá thể). Lấy được ví dụ chứng minh sự ổn định của quần thể phụ thuộc sự ổn định của các đặc trưng đó.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 49, 50 — bản ghi SH-0124', NULL, NULL, '2026-10-26T13:43:01.884Z', '2026-10-26T13:43:01.884Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4204-70da-a23b-b83b75894830', NULL, '0e22beb3-2fe8-58ae-ad98-a43d2bb31b48', 'Phân tích được các đặc trưng cơ bản của quần xã: thành phần loài (loài ưu thế, loài đặc trưng, loài chủ chốt); chỉ số đa dạng và độ phong phú trong quần xã; cấu trúc không gian; cấu trúc chức năng dinh dưỡng. Giải thích được sự cân bằng của quần xã được bảo đảm bởi sự cân bằng chỉ số các đặc trưng đó.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 50, 51 — bản ghi SH-0125', NULL, NULL, '2026-10-26T13:43:01.891Z', '2026-10-26T13:43:01.891Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4209-72d5-8416-817bfe3d018b', NULL, 'b8c61179-e10e-5783-b3a1-cdde105b1e39', 'Phát biểu được khái niệm hệ sinh thái. Phân biệt được các thành phần cấu trúc của hệ sinh thái và các kiểu hệ sinh thái chủ yếu của Trái Đất, bao gồm các hệ sinh thái tự nhiên (hệ sinh thái trên cạn, dưới nước) và các hệ sinh thái nhân tạo.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 51, 52 — bản ghi SH-0126', NULL, NULL, '2026-10-26T13:43:01.896Z', '2026-10-26T13:43:01.896Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-420b-7c7d-a673-12695ce47c27', NULL, '176175eb-b9a0-5967-b127-1ce633a1b5f2', 'Phát biểu được khái niệm chu trình sinh – địa – hoá các chất. Vẽ được sơ đồ khái quát chu trình trao đổi chất trong tự nhiên. Trình bày được chu trình sinh – địa – hoá của một số chất: nước, carbon, nitơ (nitrogen) và ý nghĩa sinh học của các chu trình đó, đồng thời vận dụng kiến thức về các chu trình đó vào giải thích các vấn đề của thực tiễn.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 52 — bản ghi SH-0127', NULL, NULL, '2026-10-26T13:43:01.899Z', '2026-10-26T13:43:01.899Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-420e-7664-8905-529f50a64faa', NULL, 'cf712955-5f5c-5a35-bb90-09f6c62e574d', 'Phát biểu được khái niệm Sinh quyển; giải thích được Sinh quyển là một cấp độ tổ chức sống lớn nhất hành tinh; trình bày được một số biện pháp bảo vệ Sinh quyển.', 1, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 53 — bản ghi SH-0128', NULL, NULL, '2026-10-26T13:43:01.901Z', '2026-10-26T13:43:01.901Z');
