INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-438a-77b0-a507-e0bf49f430b3', NULL, 'bdf4d5e1-4043-568d-814b-952d32519fd5', 'Trình bày được sơ lược lịch sử phát triển của hai hệ điều hành thông dụng cho PC, một hệ điều hành là phần mềm thương mại và hệ điều hành còn lại là phần mềm nguồn mở. Sử dụng được một số chức năng cơ bản của một trong hai hệ điều hành đó.', 1, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 46, 47 — bản ghi TH-0080', NULL, NULL, '2026-10-26T13:43:02.281Z', '2026-10-26T13:43:02.281Z');
