INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2ddd-778c-8408-985408b39898', NULL, '61fbb7fb-a06d-5d31-aa93-464a219f37d9', 'Phân tích được mối quan hệ giữa các luận điểm, lí lẽ và bằng chứng, quan hệ giữa chúng với luận đề của văn bản; nhận biết và giải thích được sự phù hợp giữa nội dung nghị luận với nhan đề của văn bản.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 67, 68 — bản ghi NV-0197', NULL, NULL, '2026-10-26T13:42:56.732Z', '2026-10-26T13:42:56.732Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2de3-742b-9912-139032dbd630', NULL, '52d4144f-1dd9-53f3-a8f1-fb9a5a080919', 'Nhận biết và phân tích được vai trò của các yếu tố thuyết minh hoặc miêu tả, tự sự trong văn bản nghị luận.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68 — bản ghi NV-0198', NULL, NULL, '2026-10-26T13:42:56.738Z', '2026-10-26T13:42:56.738Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2de6-77ad-bf97-15d59a57e06f', NULL, '3b73684f-029a-5072-bf99-323488b75a74', 'Thể hiện được quan điểm đồng ý hay không đồng ý với nội dung chính của văn bản và giải thích lí do.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68 — bản ghi NV-0199', NULL, NULL, '2026-10-26T13:42:56.741Z', '2026-10-26T13:42:56.741Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2deb-7bbf-9a78-4c5dc3543c85', NULL, 'a384585b-1da3-5d6c-ac8b-c2987c8df9ac', 'Phân tích và đánh giá được đề tài, thông tin cơ bản của văn bản, cách đặt nhan đề của tác giả; nhận biết được thái độ và quan điểm của người viết.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68 — bản ghi NV-0201', NULL, NULL, '2026-10-26T13:42:56.746Z', '2026-10-26T13:42:56.746Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2def-76e2-9d4e-93e24ea638dd', NULL, '3bacd9b6-c630-5861-9136-4babd9e10d55', 'Phân tích và đánh giá được tác dụng của các yếu tố hình thức (bao gồm phương tiện giao tiếp phi ngôn ngữ) để làm tăng hiệu quả biểu đạt của văn bản thông tin.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 68, 69 — bản ghi NV-0202', NULL, NULL, '2026-10-26T13:42:56.750Z', '2026-10-26T13:42:56.750Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dfd-7514-93ca-b1ff82548bd0', NULL, '52f1dd5a-3a83-550c-abe4-fb6ed1047def', 'Viết được văn bản nghị luận về một tác phẩm văn học hoặc một bộ phim, bài hát, bức tranh, pho tượng; nêu và nhận xét về nội dung, một số nét nghệ thuật đặc sắc.', 2, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 69, 70 — bản ghi NV-0206', NULL, NULL, '2026-10-26T13:42:56.763Z', '2026-10-26T13:42:56.763Z');
