INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-376b-7ade-8735-6f2f608ec238', NULL, 'facd1308-ac9b-50ea-bf6b-1b6fe69fb7f6', 'Nhận biết được sự chuẩn bị của nhân dân Việt Nam tiến tới khởi nghĩa giành chính quyền: chuyển hướng chiến lược của Đảng Cộng sản Đông Dương; sự ra đời của Mặt trận Việt Minh; cao trào kháng Nhật cứu nước.', 2, 'program', 'Chương trình môn Lịch sử và Địa lí (cấp Trung học cơ sở), ban hành kèm theo Thông tư số 32/2018/TT-BGDĐT ngày 26/12/2018 — ct-lsdl-thcs-official.pdf, trang 47 — bản ghi LSDL-0056', NULL, NULL, '2026-10-26T13:42:59.178Z', '2026-10-26T13:42:59.178Z');
