INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3772-79c4-95d7-b4cfc2b6a30e', NULL, '2b2d7fae-98cb-5e9e-85ae-ddfedc4c1106', 'Mô tả được các thắng lợi tiêu biểu về quân sự của nhân dân miền Nam trong kháng chiến chống Mỹ, cứu nước giai đoạn 1954 – 1975 (phong trào Đồng khởi; đánh bại các chiến lược “Chiến tranh đặc biệt”, “Chiến tranh cục bộ” và “Việt Nam hoá chiến tranh” của Mỹ; Tổng tiến công nổi dậy năm 1968, 1972; Chiến dịch Hồ Chí Minh năm 1975,...).', 2, 'program', 'Chương trình môn Lịch sử và Địa lí (cấp Trung học cơ sở), ban hành kèm theo Thông tư số 32/2018/TT-BGDĐT ngày 26/12/2018 — ct-lsdl-thcs-official.pdf, trang 49 — bản ghi LSDL-0058', NULL, NULL, '2026-10-26T13:42:59.185Z', '2026-10-26T13:42:59.185Z');
