INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-38f5-7060-a0d3-0607232655b8', NULL, 'c5874285-9617-545d-a978-4bf35ab50cb4', 'Nêu được những sự kiện chính về tình hình kinh tế, chính trị, xã hội Mỹ những năm đầu thế kỉ XXI.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 54, 55 — bản ghi LS-0069', NULL, NULL, '2026-10-26T13:42:59.571Z', '2026-10-26T13:42:59.571Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-38f9-7aaf-bfa0-c2a2fda4f005', NULL, '2b544bf5-59e4-57d7-a91a-e16d7ff51236', 'Giải thích được vì sao Trung Quốc phải tiến hành cải cách mở cửa: khủng hoảng kinh tế – xã hội trầm trọng do những sai lầm về đường lối phát triển kinh tế – xã hội trong hai thập niên 1959 – 1978.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 55 — bản ghi LS-0070', NULL, NULL, '2026-10-26T13:42:59.576Z', '2026-10-26T13:42:59.576Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-38fc-754f-be5c-7de1a5333e58', NULL, 'e4534955-8cdb-51d8-86ab-44b253f23539', 'Trình bày được các giai đoạn cải cách mở cửa của Trung Quốc trên đường thời gian: Giai đoạn khởi đầu (1978 – 1991); xây dựng thể chế kinh tế thị trường (1992 – 2000); từng bước hoàn thiện thể chế kinh tế thị trường (2001 – 2012); cải cách mở cửa sâu rộng (2012 – 2020).', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 55 — bản ghi LS-0071', NULL, NULL, '2026-10-26T13:42:59.579Z', '2026-10-26T13:42:59.579Z');
