INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3907-72ef-8843-a26b36f748b5', NULL, '31d55c82-46de-5834-b814-fc05157559e1', 'Nêu được nhận xét về thuận lợi, khó khăn của Cộng đồng ASEAN. Có ý thức sẵn sàng tham gia vào các hoạt động xây dựng Cộng đồng ASEAN.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 57, 58 — bản ghi LS-0075', NULL, NULL, '2026-10-26T13:42:59.590Z', '2026-10-26T13:42:59.590Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-390a-71ed-913a-e68145567ddc', NULL, '38da98a2-42fb-5627-9fba-834fc67e3ce2', 'Nêu được nguyên nhân thắng lợi của Cách mạng tháng Tám năm 1945.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 58 — bản ghi LS-0076', NULL, NULL, '2026-10-26T13:42:59.592Z', '2026-10-26T13:42:59.592Z');
