INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3911-7d8a-b98c-20f907277be6', NULL, '0982bdf6-f6c6-52cc-83c6-91b5d96c039c', 'Trình bày được nét khái quát về bối cảnh lịch sử, các giai đoạn phát triển chính của cuộc kháng chiến chống Mỹ, cứu nước.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 59, 60 — bản ghi LS-0078', NULL, NULL, '2026-10-26T13:42:59.599Z', '2026-10-26T13:42:59.599Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3916-7887-b5a2-16774fb8ca45', NULL, '88dca6aa-aa84-5a1d-8e5c-3adb9459d620', 'Trình bày được những nét khái quát về bối cảnh lịch sử, diễn biến chính của: cuộc chiến tranh bảo vệ Tổ quốc ở vùng biên giới Tây Nam và biên giới phía Bắc (từ sau tháng 4 năm 1975 đến đầu những năm 80 của thế kỉ XX), cuộc đấu tranh bảo vệ chủ quyền quốc gia ở vùng biên giới phía Bắc và ở Biển Đông từ năm 1979 đến nay.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 60 — bản ghi LS-0079', NULL, NULL, '2026-10-26T13:42:59.605Z', '2026-10-26T13:42:59.605Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-391a-7527-9db8-cf4ff4a3cc42', NULL, 'cf837b19-e9bd-5c54-a903-04fb79a3d5f6', 'Phân tích được giá trị thực tiễn của những bài học lịch sử của các cuộc kháng chiến bảo vệ Tổ quốc từ năm 1945 đến nay. Trân trọng những bài học kinh nghiệm trong lịch sử và sẵn sàng góp phần tham gia bảo vệ Tổ quốc khi Tổ quốc cần.', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 60, 61 — bản ghi LS-0080', NULL, NULL, '2026-10-26T13:42:59.609Z', '2026-10-26T13:42:59.609Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3920-73c6-9cc1-3f16a4bc1cf4', NULL, '587b2b63-72e9-52e3-84a1-82f825ab53de', 'Phân tích được công cuộc Đổi mới ở Việt Nam diễn ra từ hai chiều: vừa có sự chỉ đạo từ trên xuống, vừa có sự sáng tạo của nhân dân từ dưới lên (các địa phương, các hợp tác xã, doanh nghiệp).', 2, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 61, 62 — bản ghi LS-0082', NULL, NULL, '2026-10-26T13:42:59.615Z', '2026-10-26T13:42:59.615Z');
