INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ab2-72ac-971a-bf26d1f2fabb', NULL, '931ebcc4-d731-5cc3-939c-a57b6ed3963e', 'Sử dụng được atlat địa lí Việt Nam, bản đồ, số liệu thống kê để trình bày về các tài nguyên thiên nhiên và việc khai thác tổng hợp tài nguyên biển - đảo.', 2, 'program', 'Chương trình môn Địa lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-diali-official.pdf, trang 38 — bản ghi DL-0059', NULL, NULL, '2026-10-26T13:43:00.016Z', '2026-10-26T13:43:00.016Z');
