INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c09-7321-a7db-ae6c082eda7a', NULL, '9525caa7-2a7f-5438-9a88-3b7dea7a55aa', 'Dựa vào sơ đồ (hoặc hình vẽ), mô tả được cấu tạo sơ lược các cơ quan của hệ vận động. Phân tích được sự phù hợp giữa cấu tạo với chức năng của hệ vận động. Liên hệ được kiến thức đòn bẩy vào hệ vận động.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 50 — bản ghi KHTN-0066', NULL, NULL, '2026-10-26T13:43:00.359Z', '2026-10-26T13:43:00.359Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c14-7125-af3f-6c1aec3caf3c', NULL, '9a1bf115-624b-5af4-b4e6-0583fb2d4c16', 'Quan sát hình vẽ (hoặc mô hình, sơ đồ khái quát) hệ tiêu hoá ở người, kể tên được các cơ quan của hệ tiêu hoá. Nêu được chức năng của mỗi cơ quan và sự phối hợp các cơ quan thể hiện chức năng của cả hệ tiêu hoá.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 51, 52 — bản ghi KHTN-0068', NULL, NULL, '2026-10-26T13:43:00.370Z', '2026-10-26T13:43:00.370Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c1a-7a46-b344-d7b46591d69c', NULL, '2feb765b-3859-57cf-9156-fc952ca516aa', 'Nêu được các thành phần của máu và chức năng của mỗi thành phần (hồng cầu, bạch cầu, tiểu cầu, huyết tương).', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 52, 53 — bản ghi KHTN-0069', NULL, NULL, '2026-10-26T13:43:00.377Z', '2026-10-26T13:43:00.377Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c8e-7c17-9aee-9b2d733e7e81', NULL, '1fedfbc6-38d3-5f59-b790-d3f8228fff48', 'Nêu được sơ lược ưu điểm và nhược điểm của năng lượng hoá thạch.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 63 — bản ghi KHTN-0092', NULL, NULL, '2026-10-26T13:43:00.493Z', '2026-10-26T13:43:00.493Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c21-7f70-8750-5b37b5485fa6', NULL, '9a2d3042-750a-5293-8334-a8e6364eda34', 'Quan sát mô hình (hoặc hình vẽ, sơ đồ khái quát) hệ hô hấp ở người, kể tên được các cơ quan của hệ hô hấp. Nêu được chức năng của mỗi cơ quan và sự phối hợp các cơ quan thể hiện chức năng của cả hệ hô hấp.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 53, 54 — bản ghi KHTN-0070', NULL, NULL, '2026-10-26T13:43:00.384Z', '2026-10-26T13:43:00.384Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c28-755d-9a33-b840cbe76675', NULL, '8acfb05f-4fef-5576-990b-c74adc37432d', 'Dựa vào hình ảnh hay mô hình, kể tên được các cơ quan của hệ bài tiết nước tiểu.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 54 — bản ghi KHTN-0071', NULL, NULL, '2026-10-26T13:43:00.391Z', '2026-10-26T13:43:00.391Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c2d-785c-90da-e41d3d77be05', NULL, 'c953f9ea-e8ca-5b27-a32a-80c6efba0716', 'Nêu được khái niệm cân bằng môi trường trong và vai trò của sự duy trì ổn định môi trường trong của cơ thể (ví dụ nồng độ glucose, nồng độ muối trong máu, urea, uric acid, pH).', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 54 — bản ghi KHTN-0072', NULL, NULL, '2026-10-26T13:43:00.396Z', '2026-10-26T13:43:00.396Z');
