INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c3d-7389-a9c9-3a099fc225b1', NULL, 'ecc39393-407b-5ec5-a5ea-c784209cc499', 'Nêu được khái niệm thân nhiệt. Thực hành được cách đo thân nhiệt và nêu được ý nghĩa của việc đo thân nhiệt.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 56 — bản ghi KHTN-0075', NULL, NULL, '2026-10-26T13:43:00.411Z', '2026-10-26T13:43:00.411Z');
