INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c49-79b3-a46a-f0a6e049714e', NULL, '9ffe208c-79d2-50a9-9399-11fe9670ece1', 'Nêu được khái niệm nhân tố sinh thái. Phân biệt được nhân tố sinh thái vô sinh và nhân tố hữu sinh (bao gồm cả nhân tố con người). Lấy được ví dụ minh hoạ các nhân tố sinh thái và ảnh hưởng của nhân tố sinh thái lên đời sống sinh vật.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 57 — bản ghi KHTN-0077', NULL, NULL, '2026-10-26T13:43:00.424Z', '2026-10-26T13:43:00.424Z');
