INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c5d-7ff4-af35-b54207b731db', NULL, '6dd5ffe0-c60f-51a8-94c8-958c22166ada', 'Nêu được khái niệm ô nhiễm môi trường. Trình bày được sơ lược về một số nguyên nhân gây ô nhiễm môi trường (ô nhiễm do chất thải sinh hoạt và công nghiệp, ô nhiễm hoá chất bảo vệ thực vật, ô nhiễm phóng xạ, ô nhiễm do sinh vật gây bệnh) và biện pháp hạn chế ô nhiễm môi trường.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 59 — bản ghi KHTN-0084', NULL, NULL, '2026-10-26T13:43:00.444Z', '2026-10-26T13:43:00.444Z');
