INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ccb-7305-b53a-7f0f4cfff5a1', NULL, 'f540bf4a-6cbf-5086-a689-d15a43a81a19', 'Quan sát mẫu vật hoặc hình ảnh, trình bày được một số tính chất vật lí của acetic acid: trạng thái, màu sắc, mùi vị, tính tan, khối lượng riêng, nhiệt độ sôi.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 68 — bản ghi KHTN-0107', NULL, NULL, '2026-10-26T13:43:00.552Z', '2026-10-26T13:43:00.552Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3cde-7fd5-bf7e-57434d44ff29', NULL, '7b2055b5-8ed8-50ba-9701-b16f4130e783', 'Trình bày được tính chất vật lí của chất béo (trạng thái, tính tan) và tính chất hoá học (phản ứng xà phòng hoá). Viết được phương trình hoá học xảy ra.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 69 — bản ghi KHTN-0108', NULL, NULL, '2026-10-26T13:43:00.573Z', '2026-10-26T13:43:00.573Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ce3-7aa0-a847-2fcefc06f743', NULL, '76bd259a-0b4a-5330-84b7-c5b17d9e4ec5', 'Nêu được công thức phân tử, trạng thái tự nhiên, tính chất vật lí (trạng thái, màu sắc, mùi, vị, tính tan, khối lượng riêng) của glucose và saccharose.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 69 — bản ghi KHTN-0109', NULL, NULL, '2026-10-26T13:43:00.578Z', '2026-10-26T13:43:00.578Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3cea-7cab-a989-d8ece5682f7a', NULL, '4c5b6a33-636f-53db-b6cf-ec1017ffb0ab', 'Trình bày được tính chất hoá học của tinh bột và cellulose (xenlulozơ): phản ứng thuỷ phân; hồ tinh bột có phản ứng màu với iodine (iot). Viết được các phương trình hoá học của phản ứng thuỷ phân dưới dạng công thức phân tử.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 69, 70 — bản ghi KHTN-0110', NULL, NULL, '2026-10-26T13:43:00.583Z', '2026-10-26T13:43:00.583Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3cf2-77ca-b989-26c03a0390f6', NULL, '05aa1d3c-a8a2-5b77-860a-b0ddfecc701d', 'Trình bày được tính chất hoá học của protein: Phản ứng thuỷ phân có xúc tác acid, base hoặc enzyme, bị đông tụ khi có tác dụng của acid, base hoặc nhiệt độ; dễ bị phân huỷ khi đun nóng mạnh.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 70 — bản ghi KHTN-0111', NULL, NULL, '2026-10-26T13:43:00.592Z', '2026-10-26T13:43:00.592Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3cf6-7fbb-afec-9db39776faf7', NULL, 'e619987b-7a0a-5236-ab67-a7cd97e1a3ef', 'Trình bày được tính chất vật lí chung của polymer (trạng thái, khả năng tan).', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 70, 71 — bản ghi KHTN-0112', NULL, NULL, '2026-10-26T13:43:00.597Z', '2026-10-26T13:43:00.597Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3cfc-752c-90d6-17bd0434e171', NULL, 'c30c171c-5b92-57f0-9856-2595f208abfd', 'Nêu được gene quy định di truyền và biến dị ở sinh vật, qua đó gene được xem là trung tâm của di truyền học.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 71 — bản ghi KHTN-0113', NULL, NULL, '2026-10-26T13:43:00.603Z', '2026-10-26T13:43:00.603Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d00-73c7-b3cb-be596470ed08', NULL, '8f6f4b12-13a4-56dd-983f-a9af9857a2b3', 'Dựa vào thí nghiệm lai một cặp tính trạng, nêu được các thuật ngữ trong nghiên cứu các quy luật di truyền: tính trạng, nhân tố di truyền, cơ thể thuần chủng, cặp tính trạng tương phản, tính trạng trội, tính trạng lặn, kiểu hình, kiểu gene, allele (alen), dòng thuần.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 71 — bản ghi KHTN-0114', NULL, NULL, '2026-10-26T13:43:00.606Z', '2026-10-26T13:43:00.606Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d06-73b2-8a82-353c4eb586cd', NULL, 'e999168d-83ba-5588-910d-29c2574bdde7', 'Thông qua hình ảnh, mô tả được DNA có cấu trúc xoắn kép, gồm các đơn phân là 4 loại nucleotide, các nucleotide liên kết giữa 2 mạch theo nguyên tắc bổ sung.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 72 — bản ghi KHTN-0115', NULL, NULL, '2026-10-26T13:43:00.612Z', '2026-10-26T13:43:00.612Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d10-7808-9c72-60a786cfd86c', NULL, '46e58a4b-0b99-58ff-91a2-edf27cc14e96', 'Dựa vào sơ đồ hoặc hình ảnh quá trình dịch mã, nêu được khái niệm dịch mã.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 72, 73 — bản ghi KHTN-0118', NULL, NULL, '2026-10-26T13:43:00.623Z', '2026-10-26T13:43:00.623Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d13-7356-9f10-feafcbb9840e', NULL, 'c17d56ce-e4f8-5c37-9ef4-bd137c003268', 'Vận dụng kiến thức “từ gene đến tính trạng”, nêu được cơ sở của sự đa dạng về tính trạng của các loài.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 73 — bản ghi KHTN-0119', NULL, NULL, '2026-10-26T13:43:00.625Z', '2026-10-26T13:43:00.625Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d16-772d-8c22-3ea144ec30cc', NULL, '8af374a2-d30a-5c0f-b6d1-c61cad0ae67c', 'Mô tả được hình dạng nhiễm sắc thể thông qua hình vẽ nhiễm sắc thể ở kì giữa với tâm động, các cánh.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 73 — bản ghi KHTN-0120', NULL, NULL, '2026-10-26T13:43:00.629Z', '2026-10-26T13:43:00.629Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d1b-7836-a885-e5d5802d8a87', NULL, '4a907c2c-6c58-50b1-bee4-36576f100d65', 'Dựa vào hình vẽ (hoặc sơ đồ, học liệu điện tử) về quá trình giảm phân nêu được khái niệm giảm phân.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 73, 74 — bản ghi KHTN-0121', NULL, NULL, '2026-10-26T13:43:00.634Z', '2026-10-26T13:43:00.634Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d1e-720d-a9aa-a44d5d9b6bc1', NULL, 'df19e9e8-ccc3-59ee-a97b-17b0f49ef140', 'Nêu được nhiễm sắc thể vừa là vật chất mang thông tin di truyền vừa là đơn vị truyền đạt vật chất di truyền qua các thế hệ tế bào và cơ thể.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 74 — bản ghi KHTN-0122', NULL, NULL, '2026-10-26T13:43:00.636Z', '2026-10-26T13:43:00.636Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d23-76fa-b9ef-4b33e97f3118', NULL, '1c8eb5a9-ee8b-5d03-8386-1ac5b2c1506f', 'Nêu được khái niệm về bệnh và tật di truyền ở người.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 74, 75 — bản ghi KHTN-0123', NULL, NULL, '2026-10-26T13:43:00.642Z', '2026-10-26T13:43:00.642Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d29-785a-beb1-9e625fd1ea14', NULL, 'eb63e053-2535-55b4-bf59-b9bc3a6c860a', 'Tìm hiểu được tuổi kết hôn ở địa phương.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 75 — bản ghi KHTN-0124', NULL, NULL, '2026-10-26T13:43:00.647Z', '2026-10-26T13:43:00.647Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d2d-7173-bee7-44f0697d6f05', NULL, '0eddd3a7-d89e-5121-92a1-74d99944c6da', 'Nêu được một số vấn đề về đạo đức sinh học trong nghiên cứu và ứng dụng công nghệ di truyền.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 75 — bản ghi KHTN-0125', NULL, NULL, '2026-10-26T13:43:00.651Z', '2026-10-26T13:43:00.651Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d34-7afc-8ae6-03f13f629ab1', NULL, 'efffb18f-4e68-54df-9136-03347107e1d2', 'Trình bày được một số bằng chứng của quá trình chọn lọc do con người tiến hành đưa đến sự đa dạng và thích nghi của các loài vật nuôi và cây trồng từ vài dạng hoang dại ban đầu.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 75 — bản ghi KHTN-0127', NULL, NULL, '2026-10-26T13:43:00.659Z', '2026-10-26T13:43:00.659Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d38-729a-8e19-1cddd374e1a8', NULL, 'dc3945c7-2252-5e8d-99ff-1788df8d4e7d', 'Thông qua phân tích các ví dụ về tiến hoá thích nghi, chứng minh được vai trò của chọn lọc tự nhiên đối với sự hình thành đặc điểm thích nghi và đa dạng của sinh vật.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 75 — bản ghi KHTN-0128', NULL, NULL, '2026-10-26T13:43:00.662Z', '2026-10-26T13:43:00.662Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d3b-7809-b64a-7b5fc0f57732', NULL, '87127635-1392-5693-a337-125aaf403f19', 'Trình bày được quan điểm của Darwin về cơ chế tiến hoá.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 75, 76 — bản ghi KHTN-0129', NULL, NULL, '2026-10-26T13:43:00.666Z', '2026-10-26T13:43:00.666Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d3f-7695-9440-61b02916a2dc', NULL, '3c5d596c-28b1-5eba-896e-5ee6e1a771ae', 'Dựa vào sơ đồ, trình bày được khái quát sự hình thành loài người.', 2, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 76 — bản ghi KHTN-0130', NULL, NULL, '2026-10-26T13:43:00.669Z', '2026-10-26T13:43:00.669Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d56-7a68-a5b2-4cc1d1834ce1', NULL, '16bd7426-f065-5598-b12c-5fcd9c90a17f', 'Phân tích được một số ảnh hưởng của vật lí đối với cuộc sống, đối với sự phát triển của khoa học, công nghệ và kĩ thuật.', 2, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 9, 10 — bản ghi VL-0001', NULL, NULL, '2026-10-26T13:43:00.692Z', '2026-10-26T13:43:00.692Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d5b-7d32-8ff1-709d52fccbfd', NULL, '09fa5a99-9cff-5e68-814a-85540ca1876e', 'Từ hình ảnh hoặc ví dụ thực tiễn, định nghĩa được độ dịch chuyển.', 2, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 10 — bản ghi VL-0002', NULL, NULL, '2026-10-26T13:43:00.698Z', '2026-10-26T13:43:00.698Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3d63-7be0-9688-6c40426d9ca7', NULL, 'acf52a9a-c0bb-593d-bcbd-80059f5157f5', 'Thực hiện thí nghiệm (hoặc dựa trên số liệu cho trước), vẽ được đồ thị vận tốc – thời gian trong chuyển động thẳng.', 2, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 10, 11 — bản ghi VL-0003', NULL, NULL, '2026-10-26T13:43:00.706Z', '2026-10-26T13:43:00.706Z');
