INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e26-7bbb-be02-5476233f397d', NULL, 'e263c04c-472d-51ac-8fae-9dd557ca8aca', 'Thảo luận để nêu được mỗi độ chia (1°C) trong thang Celsius bằng 1/100 của khoảng cách giữa nhiệt độ tan chảy của nước tinh khiết đóng băng và nhiệt độ sôi của nước tinh khiết (ở áp suất tiêu chuẩn), mỗi độ chia (1 K) trong thang Kelvin bằng 1/(273,16) của khoảng cách giữa nhiệt độ không tuyệt đối và nhiệt độ điểm mà nước tinh khiết tồn tại đồng thời ở thể rắn, lỏng và hơi (ở áp suất tiêu chuẩn).', 2, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 24, 25 — bản ghi VL-0059', NULL, NULL, '2026-10-26T13:43:00.901Z', '2026-10-26T13:43:00.901Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3e29-7f0b-89dd-7579d086413a', NULL, '2681c1a0-66f2-53ea-b3b9-02207971f7c5', 'Thảo luận để thiết kế phương án hoặc lựa chọn phương án và thực hiện phương án, đo được nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng bằng dụng cụ thực hành.', 2, 'program', 'Chương trình môn Vật lí ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-vatli-official.pdf, trang 25 — bản ghi VL-0060', NULL, NULL, '2026-10-26T13:43:00.905Z', '2026-10-26T13:43:00.905Z');
