INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3eda-76de-a98d-68dd6c0e4049', NULL, 'e8ae421d-1cc9-56e1-aa08-34379592a7ea', 'Nêu được ý nghĩa của dấu và trị số của biến thiên năng lượng tự do Gibbs (không cần giải thích ΔrG là gì, chỉ cần nêu: Để xác định chiều hướng phản ứng, người ta dựa vào biến thiên năng lượng tự do ΔrG) của phản ứng (ΔG) để dự đoán hoặc giải thích chiều hướng của một phản ứng hoá học.', 2, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 17, 18 — bản ghi HH-0023', NULL, NULL, '2026-10-26T13:43:01.081Z', '2026-10-26T13:43:01.081Z');
