INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ee6-758f-a02a-589e83025d17', NULL, 'c38ad04c-1182-5b65-8686-adbb068e3453', 'Trình bày được việc sử dụng điểm chớp cháy để phân biệt chất lỏng dễ cháy và có thể gây cháy. (chất lỏng có điểm chớp cháy nhỏ hơn 37,8°C được gọi là chất lỏng dễ cháy. Trong khi các chất lỏng có điểm chớp cháy trên nhiệt độ đó gọi là chất lỏng có thể gây cháy).', 2, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 19 — bản ghi HH-0026', NULL, NULL, '2026-10-26T13:43:01.093Z', '2026-10-26T13:43:01.093Z');
