INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4090-7f19-b05e-20a5258b5c82', NULL, '17e23971-581b-591b-beb9-ddb30cf6df04', 'Nêu được các dấu hiệu đặc trưng của trao đổi chất và chuyển hoá năng lượng (thu nhận các chất từ môi trường, vận chuyển các chất, biến đổi các chất, tổng hợp các chất và tích luỹ năng lượng, phân giải các chất và giải phóng năng lượng, đào thải các chất ra môi trường, điều hoà).', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 24 — bản ghi SH-0019', NULL, NULL, '2026-10-26T13:43:01.519Z', '2026-10-26T13:43:01.519Z');
