INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41d0-7bb8-8801-a65991c1eaa2', NULL, 'ecef396c-19b0-571d-9dea-feede5ffad82', 'Nêu được khái niệm mức phản ứng. Lấy được các ví dụ minh hoạ.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 46 — bản ghi SH-0114', NULL, NULL, '2026-10-26T13:43:01.839Z', '2026-10-26T13:43:01.839Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41d6-7065-a471-8ca3b8c91674', NULL, 'fdddb7df-bfbf-530d-a05c-26e46a733569', 'Nêu được một số thành tựu chọn, tạo giống vật nuôi.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 46 — bản ghi SH-0115', NULL, NULL, '2026-10-26T13:43:01.844Z', '2026-10-26T13:43:01.844Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41da-79e7-8bfb-bc8b16132c2d', NULL, '43c40d32-cb55-5689-93dd-9bb836430567', 'Phân tích được cấu trúc di truyền của quần thể tự thụ phấn và quần thể giao phối gần.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 47 — bản ghi SH-0116', NULL, NULL, '2026-10-26T13:43:01.849Z', '2026-10-26T13:43:01.849Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41df-78b2-943e-2893d260bba9', NULL, 'd0fc9d1d-511f-588c-b18a-66d56cff1cb0', 'Nêu được một số phương pháp nghiên cứu di truyền người (tập trung vào phương pháp phả hệ). Xây dựng được phả hệ để xác định được sự di truyền tính trạng trong gia đình.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 47 — bản ghi SH-0117', NULL, NULL, '2026-10-26T13:43:01.854Z', '2026-10-26T13:43:01.854Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41eb-73e7-9192-9422e98ddc94', NULL, 'a66f6827-3167-507a-ab30-a0c2504d1f7c', 'Trình bày được các nhân tố tiến hoá (đột biến, di – nhập gene, chọn lọc tự nhiên, yếu tố ngẫu nhiên, giao phối không ngẫu nhiên).', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 48 — bản ghi SH-0120', NULL, NULL, '2026-10-26T13:43:01.865Z', '2026-10-26T13:43:01.865Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41ef-7f1d-8875-62151f644cff', NULL, 'd1187e57-acd5-56c8-8728-15594e9945ce', 'Dựa vào sơ đồ cây sự sống, trình bày được sinh giới có nguồn gốc chung và phân tích được sự phát sinh chủng loại là kết quả của tiến hoá.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 48 — bản ghi SH-0121', NULL, NULL, '2026-10-26T13:43:01.870Z', '2026-10-26T13:43:01.870Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41f3-7dab-abd4-c4e14961816d', NULL, '641fa9d4-5cd6-5f7f-a0ab-ae68595e296f', 'Dựa vào sơ đồ, trình bày được các đại địa chất và biến cố lớn thể hiện sự phát triển của sinh vật trong các đại đó. Nêu được một số minh chứng về tiến hoá lớn.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 48, 49 — bản ghi SH-0122', NULL, NULL, '2026-10-26T13:43:01.874Z', '2026-10-26T13:43:01.874Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41f8-7a85-8872-13049f534daf', NULL, 'ac59c02f-08c3-5d02-9c4a-815bb4fab238', 'Nêu được khái niệm nhân tố sinh thái. Phân biệt được các nhân tố sinh thái vô sinh và hữu sinh. Lấy được ví dụ về tác động của các nhân tố sinh thái lên đời sống sinh vật và thích nghi của sinh vật với các nhân tố đó.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 49 — bản ghi SH-0123', NULL, NULL, '2026-10-26T13:43:01.879Z', '2026-10-26T13:43:01.879Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41fd-77d5-999e-5fabead0a3a7', NULL, 'ee1a0d27-9a53-522c-a510-6cdba8995c44', 'Phân biệt được các kiểu tăng trưởng quần thể sinh vật (tăng trưởng theo tiềm năng sinh học và tăng trưởng trong môi trường có nguồn sống bị giới hạn).', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 49, 50 — bản ghi SH-0124', NULL, NULL, '2026-10-26T13:43:01.884Z', '2026-10-26T13:43:01.884Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4224-7796-b297-cf4d994b09ed', NULL, '9d3e5a1e-0209-5617-a3f4-e1b5f4b1a87e', 'Phân tích được giá trị của sinh thái nhân văn trong việc phát triển bền vững.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 56 — bản ghi SH-0133', NULL, NULL, '2026-10-26T13:43:01.923Z', '2026-10-26T13:43:01.923Z');
