INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-420e-7e40-8efe-fb61d958ae37', NULL, 'cf712955-5f5c-5a35-bb90-09f6c62e574d', 'Phát biểu được khái niệm khu sinh học. Trình bày được đặc điểm của các khu sinh học trên cạn chủ yếu và các khu sinh học nước ngọt, khu sinh học nước mặn trên Trái Đất.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 53 — bản ghi SH-0128', NULL, NULL, '2026-10-26T13:43:01.901Z', '2026-10-26T13:43:01.901Z');
