INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4218-7614-8b74-733ddb4c9dbe', NULL, '7e82f434-e8a3-5e51-8573-400be355df81', 'Trình bày được một số thành tựu hiện đại về lí thuyết và ứng dụng của sinh học phân tử.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 54 — bản ghi SH-0130', NULL, NULL, '2026-10-26T13:43:01.910Z', '2026-10-26T13:43:01.910Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-421c-7852-bdaf-01035942468a', NULL, '997c0b2a-7b47-5a4c-b1bc-77209cda6161', 'Giải thích được cơ sở khoa học chuyển gene và vì sao phải sử dụng vector để truyền gene từ tế bào này sang tế bào khác.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 55 — bản ghi SH-0131', NULL, NULL, '2026-10-26T13:43:01.915Z', '2026-10-26T13:43:01.915Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4220-780b-8769-4a26da73030f', NULL, '03d2b724-a409-57e5-a19b-98929bedea82', 'Phân tích được vai trò của kiểm soát sinh học.', 2, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 55 — bản ghi SH-0132', NULL, NULL, '2026-10-26T13:43:01.919Z', '2026-10-26T13:43:01.919Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4247-70d1-acf2-a1672ba34185', NULL, '8c7ed1f9-0fa6-5754-b51d-e624e633e06c', 'Nhận biết được ba dạng thông tin hay gặp: chữ, âm thanh, hình ảnh. Nhận ra được trong ví dụ của giáo viên: Thông tin thu nhận và được xử lí là gì, kết quả của xử lí là hành động hay ý nghĩ gì. Nêu được ví dụ minh hoạcho nhận xét: Bộ óc của con người là một bộ phận xử lí thông tin.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 18 — bản ghi TH-0001', NULL, NULL, '2026-10-26T13:43:01.957Z', '2026-10-26T13:43:01.957Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-424b-7428-a85f-54a0ccae28c8', NULL, '50957237-2197-5405-b860-f94203ee102c', 'Nêu được sơ lược về chức năng của bàn phím và chuột, màn hình và loa. Nhận biết được màn hình cảm ứng của máy tính bảng, điện thoại thông minh,... cũng là thiết bị tiếp nhận thông tin vào.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 19 — bản ghi TH-0002', NULL, NULL, '2026-10-26T13:43:01.961Z', '2026-10-26T13:43:01.961Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4251-756b-8465-980172b265e4', NULL, '6052e30b-be8a-51c6-a52e-2faf085ed81a', 'Biết vị trí đặt các ngón tay trên hàng phím cơ sở và thực hiện được thao tác gõ các phím ở hàng cơ sở, hàng trên, hàng dưới đúng quy định của cách gõ bàn phím.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 19 — bản ghi TH-0003', NULL, NULL, '2026-10-26T13:43:01.967Z', '2026-10-26T13:43:01.967Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4254-7a9d-b4de-d9a4c18ba335', NULL, '3594be47-3b2c-5e87-a8af-a065fc8f7b21', 'Nêu được ví dụ thông tin nào đó không có sẵn trong máy tính đang sử dụng nhưng có thể tìm thấy trên Internet.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 19, 20 — bản ghi TH-0004', NULL, NULL, '2026-10-26T13:43:01.971Z', '2026-10-26T13:43:01.971Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-425b-7970-8c88-a1171f93d553', NULL, '272fff7c-abfd-589d-933f-9ade22cc2593', 'Sắp xếp được đồ vật hay dữ liệu hợp lí theo một số yêu cầu cụ thể. Ví dụ: xếp một số mảnh bìa có ghi chữ cái theo thứ tự abc; xếp sách vở vào một ngăn tủ, xếp ảnh vào một ngăn tủ khác, quần áo vào ngăn khác nữa, trong ngăn tủ lớn xếp sách có thể chia làm các ngăn nhỏ hơn (ngăn chứa sách, ngăn chứa vở, ngăn chứa truyện,...).', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 20 — bản ghi TH-0005', NULL, NULL, '2026-10-26T13:43:01.977Z', '2026-10-26T13:43:01.977Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4260-7ab3-9e54-1558369460a8', NULL, '0b9c7ad0-034a-5202-a772-23be735593b9', 'Mô tả sơ lược được vai trò của cấu trúc cây thư mục trong việc lưu các tệp và các thư mục.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 20 — bản ghi TH-0006', NULL, NULL, '2026-10-26T13:43:01.983Z', '2026-10-26T13:43:01.983Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4266-7872-8f7f-fcecce3fb008', NULL, 'f6296392-9803-5453-84b0-5e937f63db18', 'Có ý thức bảo vệ thông tin cá nhân và gia đình khi giao tiếp qua máy tính; biết được việc người xấu có thể lợi dụng những thông tin này gây hại cho em và gia đình.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 20 — bản ghi TH-0007', NULL, NULL, '2026-10-26T13:43:01.989Z', '2026-10-26T13:43:01.989Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4269-7ea1-89b7-8624ec59df58', NULL, '15e97c4b-5104-5699-88b7-72e8b31461b0', 'Tạo được tệp trình chiếu, gõ được một vài dòng văn bản đơn giản không dấu, đưa được ảnh vào một trang chiếu, lưu và đặt được tên cho tệp trình chiếu.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 20, 21 — bản ghi TH-0008', NULL, NULL, '2026-10-26T13:43:01.992Z', '2026-10-26T13:43:01.992Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-426c-7a7a-a5c6-9402b81ea3ec', NULL, '5a63253a-abe3-5a61-ac6c-89a8714c4438', 'Kể lại được những gì quan sát đã đem lại thêm hiểu biết mới.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 21 — bản ghi TH-0010', NULL, NULL, '2026-10-26T13:43:01.995Z', '2026-10-26T13:43:01.995Z');
