INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-4273-718b-ac5b-af4fb49529a7', NULL, '64ff9fdb-f56f-5972-97ae-f81f3184a86e', 'Nhận biết được việc chia một nhiệm vụ lớn thành những nhiệm vụ nhỏ hơn là để dễ hiểu và dễ thực hiện hơn.', 2, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 21, 22 — bản ghi TH-0012', NULL, NULL, '2026-10-26T13:43:02.001Z', '2026-10-26T13:43:02.001Z');
