INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2d33-7af8-a6f9-a9511a0e9b8d', NULL, 'da4a41ec-6ea6-5b02-8196-fa5b1bc21d97', 'Thuyết minh được về một danh lam thắng cảnh hay một di tích lịch sử, có sử dụng các sơ đồ, bảng biểu, hình ảnh minh hoạ.', 3, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 59 — bản ghi NV-0164', NULL, NULL, '2026-10-26T13:42:56.562Z', '2026-10-26T13:42:56.562Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2d44-7407-a8bd-3fe5a404adba', NULL, 'f7dce7f0-a044-52a3-a3d1-c3bcbee33519', 'Phân tích và đánh giá được tình cảm, cảm xúc, cảm hứng chủ đạo mà người viết thể hiện qua văn bản. Phát hiện được các giá trị đạo đức, văn hoá từ văn bản.', 3, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 60 — bản ghi NV-0170', NULL, NULL, '2026-10-26T13:42:56.578Z', '2026-10-26T13:42:56.578Z');
