INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3b10-7fe3-b1d7-babdaeccd2c1', NULL, '8186cd4b-61e1-56d6-9d65-c1ee627af0df', 'Dựa vào sơ đồ, nhận biết được năm giới sinh vật. Lấy được ví dụ minh hoạ cho mỗi giới.', 3, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 27 — bản ghi KHTN-0010', NULL, NULL, '2026-10-26T13:43:00.110Z', '2026-10-26T13:43:00.110Z');
