INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f0a-7594-a36e-02cdad626817', NULL, 'de057d0a-e634-5aec-b80d-bb0d160d036a', 'Nêu được khái niệm và ý nghĩa của pH trong thực tiễn (liên hệ giá trị pH ở các bộ phận trong cơ thể với sức khoẻ con người, pH của đất, nước tới sự phát triển của động thực vật,...).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 21 — bản ghi HH-0031', NULL, NULL, '2026-10-26T13:43:01.128Z', '2026-10-26T13:43:01.128Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f11-70de-986f-f9d29edde0e3', NULL, 'c2e07389-78e8-5384-96d5-4607ae5a311f', 'Trình bày được sự hoạt động của đơn chất nitơ ở nhiệt độ cao đối với hydrogen, oxygen. Liên hệ được quá trình tạo và cung cấp nitrate (nitrat) cho đất từ nước mưa.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 21, 22 — bản ghi HH-0032', NULL, NULL, '2026-10-26T13:43:01.135Z', '2026-10-26T13:43:01.135Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f15-7c44-8a70-38e72c1d3d7a', NULL, '2251be9c-6785-554d-ab39-711248a38d18', 'Vận dụng được kiến thức về cân bằng hoá học, tốc độ phản ứng, enthalpy cho phản ứng tổng hợp ammonia từ nitơ và hydrogen trong quá trình Haber.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 22 — bản ghi HH-0033', NULL, NULL, '2026-10-26T13:43:01.139Z', '2026-10-26T13:43:01.139Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f1b-777a-bca3-dfea11fe5c5a', NULL, '71c65680-c407-5dbe-b5e5-e734ba0df533', 'Giải thích được nguyên nhân, hệ quả của hiện tượng phú dưỡng hoá (eutrophication).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 22 — bản ghi HH-0034', NULL, NULL, '2026-10-26T13:43:01.145Z', '2026-10-26T13:43:01.145Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f22-77d2-8ccd-4d081ee810d5', NULL, '38d4f724-d3ea-5d46-bb14-dfdeae6fb889', 'Trình bày được tính oxi hoá (tác dụng với hydrogen sulfide) và tính khử (tác dụng với nitrogen dioxide, xúc tác nitrogen oxide trong không khí) và ứng dụng của sulfur dioxide (khả năng tẩy màu, diệt nấm mốc,...).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23 — bản ghi HH-0036', NULL, NULL, '2026-10-26T13:43:01.152Z', '2026-10-26T13:43:01.152Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f26-76ab-8c39-55482bf61226', NULL, 'b0295e6e-0585-568c-94c2-a940d599e6a6', 'Thực hiện được một số thí nghiệm chứng minh tính oxi hoá mạnh và tính háo nước của sulfuric acid đặc (với đồng, da, than, giấy, đường, gạo,...).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23 — bản ghi HH-0037', NULL, NULL, '2026-10-26T13:43:01.156Z', '2026-10-26T13:43:01.156Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f2a-7c14-bb15-a0699845e75b', NULL, '679638fe-74fa-5b37-a964-a64a43a0d071', 'Nêu được khái niệm nhóm chức và một số loại nhóm chức cơ bản.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23, 24 — bản ghi HH-0038', NULL, NULL, '2026-10-26T13:43:01.161Z', '2026-10-26T13:43:01.161Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f43-76e3-99a5-9e5f7abb2696', NULL, '5f1ce91f-0600-5cdd-a92a-97ccd232564d', 'Nêu được khái niệm và xác định được đồng phân hình học (cis, trans) trong một số trường hợp đơn giản.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 25, 26 — bản ghi HH-0043', NULL, NULL, '2026-10-26T13:43:01.185Z', '2026-10-26T13:43:01.185Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f2f-7002-ab15-426dc729a7c9', NULL, 'e9637cd3-8a4c-5700-b28c-e24ce6dd2fd7', 'Vận dụng được các phương pháp: chưng cất thường, chiết, kết tinh để tách biệt và tinh chế một số hợp chất hữu cơ trong cuộc sống.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24 — bản ghi HH-0039', NULL, NULL, '2026-10-26T13:43:01.164Z', '2026-10-26T13:43:01.164Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f33-7ea5-8cf7-d1df991ee687', NULL, '70bf8535-41a1-5482-824f-dffccf6a6b10', 'Lập được công thức phân tử hợp chất hữu cơ từ dữ liệu phân tích nguyên tố và phân tử khối.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24 — bản ghi HH-0040', NULL, NULL, '2026-10-26T13:43:01.168Z', '2026-10-26T13:43:01.168Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f38-72d5-bc6f-002e3acf1eaa', NULL, '80f1e530-7118-5a9d-8a6d-43da57f3bbe3', 'Nêu được khái niệm chất đồng đẳng và dãy đồng đẳng.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24 — bản ghi HH-0041', NULL, NULL, '2026-10-26T13:43:01.174Z', '2026-10-26T13:43:01.174Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fc8-721d-8d10-ad0451746b6f', NULL, '86212fd3-1b5d-5ede-8c69-d66db05f7d4b', 'Nêu được ứng dụng của một số hiện tượng điện phân trong thực tiễn (mạ điện, tinh chế kim loại).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 38, 39 — bản ghi HH-0071', NULL, NULL, '2026-10-26T13:43:01.318Z', '2026-10-26T13:43:01.318Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f3d-787f-9ddc-fbffe880482b', NULL, 'f584af77-e0de-5621-90db-c163c0a96712', 'Trình bày và giải thích được đặc điểm về tính chất vật lí (nhiệt độ nóng chảy, nhiệt độ sôi, tỉ khối, – tính tan) của một số alkane.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24, 25 — bản ghi HH-0042', NULL, NULL, '2026-10-26T13:43:01.179Z', '2026-10-26T13:43:01.179Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f49-7d90-8105-c3f7e41f591a', NULL, 'eacc0eec-d3bb-5f5f-81ca-f2729e8d22b3', 'Trình bày được đặc điểm về tính chất vật lí, trạng thái tự nhiên của một số arene, đặc điểm liên kết và hình dạng phân tử benzene.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 26, 27 — bản ghi HH-0044', NULL, NULL, '2026-10-26T13:43:01.191Z', '2026-10-26T13:43:01.191Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f52-715d-a0b8-23b33e1e1fe9', NULL, 'a0914615-cbc2-5c25-a55b-f6ac0be1cf4a', 'Nêu được đặc điểm về tính chất vật lí của một số dẫn xuất halogen.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27 — bản ghi HH-0045', NULL, NULL, '2026-10-26T13:43:01.200Z', '2026-10-26T13:43:01.200Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f57-7282-8191-98dc8b85ec89', NULL, 'e7e631d5-fd7c-50a0-928b-609839799afc', 'Trình bày được đặc điểm về tính chất vật lí của alcohol (trạng thái, xu hướng của nhiệt độ sôi, độ tan trong nước), giải thích được ảnh hưởng của liên kết hydrogen đến nhiệt độ sôi và khả năng hoà tan trong nước của các alcohol.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27, 28 — bản ghi HH-0046', NULL, NULL, '2026-10-26T13:43:01.205Z', '2026-10-26T13:43:01.205Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f5e-7669-857a-b64f3552ca6e', NULL, '0e15ec30-5eb6-5cbd-bc63-5108685fcbd3', 'Trình bày được tính chất hoá học cơ bản của phenol: Phản ứng thế H ở nhóm –OH (tính acid: thông qua phản ứng với sodium hydroxide, sodium carbonate), phản ứng thế ở vòng thơm (tác dụng với nước bromine, với HNO đặctrong H SO đặc).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 28, 29 — bản ghi HH-0047', NULL, NULL, '2026-10-26T13:43:01.212Z', '2026-10-26T13:43:01.212Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f63-7bb3-a1c4-567d986082a0', NULL, '75330484-1ca9-57b7-b7b1-a0368407701a', 'Mô tả được đặc điểm liên kết của nhóm chức carbonyl, hình dạng phân tử của methanal, ethanal.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 29 — bản ghi HH-0048', NULL, NULL, '2026-10-26T13:43:01.217Z', '2026-10-26T13:43:01.217Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f69-7a46-b02f-6d46c26ae64a', NULL, '5cb339c5-afe4-5101-8294-1a92baebe918', 'Trình bày được đặc điểm cấu tạo và hình dạng phân tử acetic acid.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 29, 30 — bản ghi HH-0049', NULL, NULL, '2026-10-26T13:43:01.223Z', '2026-10-26T13:43:01.223Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f76-7228-8a85-12bbf36ec4c1', NULL, 'eb9e57dd-8ba7-5697-bfe1-04fb31690cfc', 'Trình bày được quy trình sản xuất một số loại phân bón vô cơ.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 30, 31 — bản ghi HH-0051', NULL, NULL, '2026-10-26T13:43:01.235Z', '2026-10-26T13:43:01.235Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f7a-76cb-b2ed-9b1384e8c76c', NULL, '3f4ff4c2-1483-5148-ac0a-b267e2d995a7', 'Trình bày được vai trò của phân bón hữu cơ, cách sử dụng và bảo quản của một số loại phân bón hữu cơ thông dụng và một số quy trình sản xuất phân bón hữu cơ.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 31 — bản ghi HH-0052', NULL, NULL, '2026-10-26T13:43:01.240Z', '2026-10-26T13:43:01.240Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f8e-7989-8323-9db8b228010d', NULL, '954e8429-972e-55e2-bdba-0d1c26399245', 'Nêu được khái niệm chỉ số octane và chỉ số octane của một số hydrocarbon, ý nghĩa của chỉ số octane đến chất lượng của xăng. Trình bày được các biện pháp nâng cao chỉ số octane cho xăng và cách sử dụng nhiên liệu an toàn, tiết kiệm, hiệu quả, bảo vệ môi trường và sức khoẻ con người.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 32 — bản ghi HH-0058', NULL, NULL, '2026-10-26T13:43:01.260Z', '2026-10-26T13:43:01.260Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f97-7b0f-a641-14a25250c914', NULL, '172dfb78-66f2-5eb4-ae85-35ad5b235d4e', 'Viết được công thức cấu tạo và gọi được tên một số ester đơn giản (số nguyên tử C trong phân tử ≤ 5) và thường gặp.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 32, 33, 34 — bản ghi HH-0061', NULL, NULL, '2026-10-26T13:43:01.269Z', '2026-10-26T13:43:01.269Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fa2-71d6-aee0-0d3ff23af0fc', NULL, 'cadb8040-4158-566d-b67c-5d1043e98e0f', 'Nêu được đặc điểm về tính chất vật lí của amine (trạng thái, nhiệt độ sôi, nhiệt độ nóng chảy, khả năng hoà tan).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 34, 35 — bản ghi HH-0062', NULL, NULL, '2026-10-26T13:43:01.280Z', '2026-10-26T13:43:01.280Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fa7-716d-80bb-a46b05b07b72', NULL, 'c4bb9118-9c49-5421-aeef-e0c2fa804c4d', 'Trình bày được tính chất hoá học đặc trưng của amino acid (tính lưỡng tính, phản ứng ester hoá; phản ứng trùng ngưng của - và -amino acid).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 35, 36 — bản ghi HH-0063', NULL, NULL, '2026-10-26T13:43:01.285Z', '2026-10-26T13:43:01.285Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fad-766d-bb38-3bfc75583235', NULL, 'e9eeb883-1c37-5092-9c4e-07003facdff4', 'Thực hiện được thí nghiệm về phản ứng đông tụ của protein: đun nóng lòng trắng trứng hoặc tác dụng của acid, kiềm với lòng trắng trứng; phản ứng của lòng trắng trứng với nitric acid; mô tả các hiện tượng thí nghiệm, giải thích được tính chất hoá học của protein.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 36 — bản ghi HH-0064', NULL, NULL, '2026-10-26T13:43:01.291Z', '2026-10-26T13:43:01.291Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fb1-7694-87f7-97e8b69a590e', NULL, 'aa5cbd86-876b-5f4b-9d1a-0d98a26da881', 'Trình bày được phương pháp trùng hợp, trùng ngưng để tổng hợp một số polymer thường gặp.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 36, 37 — bản ghi HH-0065', NULL, NULL, '2026-10-26T13:43:01.295Z', '2026-10-26T13:43:01.295Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fb4-78b9-af4a-bc3fb034c78c', NULL, '5698b979-95aa-59ed-81eb-f193f7149c13', 'Trình bày được ứng dụng của chất dẻo và tác hại của việc lạm dụng chất dẻo trong đời sống và sản xuất. Nêu được một số biện pháp để hạn chế sử dụng một số loại chất dẻo để giảm thiểu ô nhiễm môi trường, bảo vệ sức khoẻ con người.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 37 — bản ghi HH-0066', NULL, NULL, '2026-10-26T13:43:01.298Z', '2026-10-26T13:43:01.298Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fbb-7421-8d31-580649ff7bc6', NULL, 'afef3b85-6e3f-53a6-8ed2-303110dd81af', 'Trình bày được phản ứng điều chế cao su tổng hợp (cao su buna, cao su buna-S, cao su buna-N, chloroprene).', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 37 — bản ghi HH-0068', NULL, NULL, '2026-10-26T13:43:01.305Z', '2026-10-26T13:43:01.305Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fc3-7e32-ba70-ec8f4d518cd6', NULL, '88f8661d-a5d6-586f-b76b-0af2c35e6618', 'Sử dụng bảng giá trị thế điện cực chuẩn để: So sánh được tính khử, tính oxi hoá giữa các cặp oxi hoá – khử; Dự đoán được chiều hướng xảy ra phản ứng giữa hai cặp oxi hoá – khử; Tính được sức điện động của pin điện hoá tạo bởi hai cặp oxi hoá – khử.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 38 — bản ghi HH-0070', NULL, NULL, '2026-10-26T13:43:01.314Z', '2026-10-26T13:43:01.314Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fce-7a8e-ac60-bc00ccfc974d', NULL, 'd468167f-dafa-54ea-99a8-966ea70355fa', 'Sử dụng bảng giá trị thế điện cực chuẩn của một số cặp oxi hoá – khử phổ biến của ion kim loại/ kim loại (có bổ sung thế điện cực chuẩn các cặp: H + 1/2H ; ; SO2– + SO + 2H O) để giải thích được các trường hợp kim loại phản ứng với dung dịch HCl, H SO loãng và đặc; nước; dung dịch muối.', 3, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 39 — bản ghi HH-0073', NULL, NULL, '2026-10-26T13:43:01.325Z', '2026-10-26T13:43:01.325Z');
