INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41b6-743a-b5a1-0ff21bc47f6e', NULL, 'acafcde6-d896-5b18-9fa3-6d3306b5054b', 'Phân tích được sự vận động của nhiễm sắc thể (tự nhân đôi, phân li, tổ hợp, tái tổ hợp) trong nguyên phân, giảm phân và thụ tinh là cơ sở của sự vận động của gene được thể hiện trong các quy luật di truyền, biến dị tổ hợp và biến dị số lượng nhiễm sắc thể.', 3, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 43 — bản ghi SH-0108', NULL, NULL, '2026-10-26T13:43:01.812Z', '2026-10-26T13:43:01.812Z');
