INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-41f0-764a-9c83-febe88487c27', NULL, 'd1187e57-acd5-56c8-8728-15594e9945ce', 'Làm được bài tập sưu tầm tài liệu về sự phát sinh và phát triển của sinh giới hoặc của loài người.', 3, 'program', 'Chương trình môn Sinh học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-sinhhoc-official.pdf, trang 48 — bản ghi SH-0121', NULL, NULL, '2026-10-26T13:43:01.870Z', '2026-10-26T13:43:01.870Z');
