INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-42cc-71b6-95bb-c84d074b3eaf', NULL, '7cf16b92-0cdd-5793-b47b-e27b470186a2', 'Nêu được tên và độ lớn (xấp xỉ theo hệ thập phân) của các đơn vị cơ bản đo dung lượng thông tin: Byte, KB, MB, GB, quy đổi được một cách gần đúng giữa các đơn vị đo lường này. Ví dụ: 1KB bằng xấp xỉ 1 ngàn byte, 1 MB xấp xỉ 1 triệu byte, 1 GB xấp xỉ 1 tỉ byte.', 3, 'program', 'Chương trình môn Tin học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-tinhoc-official.pdf, trang 29 — bản ghi TH-0037', NULL, NULL, '2026-10-26T13:43:02.090Z', '2026-10-26T13:43:02.090Z');
