INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dc8-7ae6-85ea-8b2b2cb57d39', NULL, '1a167205-e661-5015-9b62-a33d3aa0b4ba', 'Nhận biết và phân tích được vai trò của yếu tố tượng trưng trong thơ. Đánh giá được giá trị thẩm mĩ của một số yếu tố trong thơ như ngôn từ, cấu tứ, hình thức bài thơ thể hiện trong văn bản.', 4, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 66 — bản ghi NV-0194', NULL, NULL, '2026-10-26T13:42:56.709Z', '2026-10-26T13:42:56.709Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2dd4-7702-9c48-892b9abeac02', NULL, 'c49f3c64-60de-52c1-9898-3efcf577b9ec', 'Phân tích được ý nghĩa hay tác động của văn bản văn học trong việc làm thay đổi suy nghĩ, tình cảm, cách nhìn và cách thưởng thức, đánh giá của cá nhân đối với văn học và cuộc sống.', 4, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Ngữ văn — ct-nguvan-official.pdf, trang 67 — bản ghi NV-0195', NULL, NULL, '2026-10-26T13:42:56.721Z', '2026-10-26T13:42:56.721Z');
