INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3be1-7301-9ab1-23b3cc219caa', NULL, '4bb2e227-a845-5f82-b6bf-343b47043bd7', 'Tiến hành được thí nghiệm oxide kim loại phản ứng với acid; oxide phi kim phản ứng với base; nêu và giải thích được hiện tượng xảy ra trong thí nghiệm (viết phương trình hoá học) và rút ra nhận xét về tính chất hoá học của oxide.', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 46 — bản ghi KHTN-0058', NULL, NULL, '2026-10-26T13:43:00.319Z', '2026-10-26T13:43:00.319Z');
