INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3beb-7b9d-9657-31a73cce30f3', NULL, '267392c0-4d9d-5a3c-a96f-d01aaea8e58d', 'Thực hiện thí nghiệm khảo sát tác dụng của chất lỏng lên vật đặt trong chất lỏng, rút ra được: Điều kiện định tính về vật nổi, vật chìm; định luật Archimedes (Acsimet).', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 47, 48 — bản ghi KHTN-0061', NULL, NULL, '2026-10-26T13:43:00.329Z', '2026-10-26T13:43:00.329Z');
