INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3bf7-75e4-9e38-1caf13c617c4', NULL, '49eb6472-9f74-5ce2-a888-4641e3fae349', 'Nêu được nguồn điện có khả năng cung cấp năng lượng điện và liệt kê được một số nguồn điện thông dụng trong đời sống.', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 48, 49 — bản ghi KHTN-0063', NULL, NULL, '2026-10-26T13:43:00.341Z', '2026-10-26T13:43:00.341Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c00-7c41-96c9-da605db02bb7', NULL, '0bba5f78-cc22-5943-942b-a5a9ddb79c94', 'Lấy được ví dụ về hiện tượng dẫn nhiệt, đối lưu, bức xạ nhiệt và mô tả sơ lược được sự truyền năng lượng trong mỗi hiện tượng đó.', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 49 — bản ghi KHTN-0064', NULL, NULL, '2026-10-26T13:43:00.350Z', '2026-10-26T13:43:00.350Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c0a-70ea-a250-84a5914493f0', NULL, '9525caa7-2a7f-5438-9a88-3b7dea7a55aa', 'Nêu được ý nghĩa của tập thể dục, thể thao và chọn phương pháp luyện tập thể thao phù hợp (tự đề xuất được một chế độ luyện tập cho bản thân nhằm nâng cao thể lực và thể hình).', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 50 — bản ghi KHTN-0066', NULL, NULL, '2026-10-26T13:43:00.359Z', '2026-10-26T13:43:00.359Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c14-7e70-aa0f-0ff14ae5673e', NULL, '9a1bf115-624b-5af4-b4e6-0583fb2d4c16', 'Nêu được nguyên tắc lập khẩu phần thức ăn cho con người. Thực hành xây dựng chế độ dinh dưỡng cho bản thân và những người trong gia đình.', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 51, 52 — bản ghi KHTN-0068', NULL, NULL, '2026-10-26T13:43:00.370Z', '2026-10-26T13:43:00.370Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c1b-7a6f-9b9d-a146ae5c4d13', NULL, '2feb765b-3859-57cf-9156-fc952ca516aa', 'Quan sát mô hình (hoặc hình vẽ, sơ đồ khái quát) hệ tuần hoàn ở người, kể tên được các cơ quan của hệ tuần hoàn. Nêu được chức năng của mỗi cơ quan và sự phối hợp các cơ quan thể hiện chức năng của cả hệ tuần hoàn.', 4, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 52, 53 — bản ghi KHTN-0069', NULL, NULL, '2026-10-26T13:43:00.377Z', '2026-10-26T13:43:00.377Z');
