INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ee7-74ce-a4d2-4a6955faefdc', NULL, 'c38ad04c-1182-5b65-8686-adbb068e3453', 'Phân tích được dấu hiệu để nhận biết về những nguy cơ và cách giảm nguy cơ gây cháy, nổ; cách xử lí khi có cháy, nổ. (Chú ý tìm hiểu, thu thập thông tin về điểm chớp cháy, nhiệt độ cháy của những chất hay gặp trong cuộc sống như: xăng, dầu, vật liệu xây dựng)', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 19 — bản ghi HH-0026', NULL, NULL, '2026-10-26T13:43:01.093Z', '2026-10-26T13:43:01.093Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ef3-741b-baf7-0e08b7de64ff', NULL, '2e97d9d4-fa81-5f35-abb1-c0ecb65caadc', 'Giải thích được vì sao lại hay dùng CO2 để chữa cháy (cách li và làm giảm nồng độ O2; CO2 nặng hơn không khí).', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 19, 20 — bản ghi HH-0027', NULL, NULL, '2026-10-26T13:43:01.096Z', '2026-10-26T13:43:01.096Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f0a-7e55-bfbf-f405c38eb12a', NULL, 'de057d0a-e634-5aec-b80d-bb0d160d036a', 'Viết được biểu thức tính pH (pH = –lg[H+] hoặc [H+] = 10–pH) và biết cách sử dụng các chất chỉ thị để xác định pH (môi trường acid, base, trung tính) bằng các chất chỉ thị phổ biến như giấy chỉ thị màu, quỳ tím, phenolphthalein,...', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 21 — bản ghi HH-0031', NULL, NULL, '2026-10-26T13:43:01.128Z', '2026-10-26T13:43:01.128Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f11-78b7-8f35-0e692a7fbc05', NULL, 'c2e07389-78e8-5384-96d5-4607ae5a311f', 'Giải thích được các ứng dụng của đơn chất nitơ khí và lỏng trong sản xuất, trong hoạt động nghiên cứu.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 21, 22 — bản ghi HH-0032', NULL, NULL, '2026-10-26T13:43:01.135Z', '2026-10-26T13:43:01.135Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f16-77c1-84a3-dad19dada03e', NULL, '2251be9c-6785-554d-ab39-711248a38d18', 'Trình bày được tính chất cơ bản của muối ammonium (dễ tan và phân li, chuyển hoá thành ammonia trong kiềm, dễ bị nhiệt phân) và nhận biết được ion ammonium trong dung dịch.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 22 — bản ghi HH-0033', NULL, NULL, '2026-10-26T13:43:01.139Z', '2026-10-26T13:43:01.139Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f23-703f-a449-139b05117faa', NULL, '38d4f724-d3ea-5d46-bb14-dfdeae6fb889', 'Trình bày được sự hình thành sulfur dioxide do tác động của con người, tự nhiên, tác hại của sulfur dioxide và một số biện pháp làm giảm thiểu lượng sulfur dioxide thải vào không khí.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23 — bản ghi HH-0036', NULL, NULL, '2026-10-26T13:43:01.152Z', '2026-10-26T13:43:01.152Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f26-7dcd-9b9d-a0681163b7bf', NULL, 'b0295e6e-0585-568c-94c2-a940d599e6a6', 'Vận dụng được kiến thức về năng lượng phản ứng, chuyển dịch cân bằng, vấn đề bảo vệ môi trường để giải thích các giai đoạn trong quá trình sản xuất sulfuric acid theo phương pháp tiếp xúc.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23 — bản ghi HH-0037', NULL, NULL, '2026-10-26T13:43:01.156Z', '2026-10-26T13:43:01.156Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f2b-737e-8943-d049c50a91e5', NULL, '679638fe-74fa-5b37-a964-a64a43a0d071', 'Sử dụng được bảng tín hiệu phổ hồng ngoại (IR) để xác định một số nhóm chức cơ bản.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23, 24 — bản ghi HH-0038', NULL, NULL, '2026-10-26T13:43:01.161Z', '2026-10-26T13:43:01.161Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f38-7b38-a652-02887834b9ab', NULL, '80f1e530-7118-5a9d-8a6d-43da57f3bbe3', 'Viết được công thức cấu tạo của một số hợp chất hữu cơ đơn giản (công thức cấu tạo đầy đủ, công thức cấu tạo thu gọn).', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24 — bản ghi HH-0041', NULL, NULL, '2026-10-26T13:43:01.174Z', '2026-10-26T13:43:01.174Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f3e-70af-b50a-3f03b4bc1af9', NULL, 'f584af77-e0de-5621-90db-c163c0a96712', 'Trình bày được đặc điểm về liên kết hoá học trong phân tử alkane, hình dạng phân tử của methane, ethane; phản ứng thế, cracking, reforming, phản ứng oxi hoá hoàn toàn, phản ứng oxi hoá không hoàn toàn.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24, 25 — bản ghi HH-0042', NULL, NULL, '2026-10-26T13:43:01.179Z', '2026-10-26T13:43:01.179Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f43-7fcc-8b6a-cf23f757b78a', NULL, '5f1ce91f-0600-5cdd-a92a-97ccd232564d', 'Nêu được đặc điểm về tính chất vật lí (nhiệt độ nóng chảy, nhiệt độ sôi, tỉ khối, khả năng hoà tan trong nước) của một số alkene, alkyne.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 25, 26 — bản ghi HH-0043', NULL, NULL, '2026-10-26T13:43:01.185Z', '2026-10-26T13:43:01.185Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f4a-7620-b680-d05d81f59c3c', NULL, 'eacc0eec-d3bb-5f5f-81ca-f2729e8d22b3', 'Trình bày được tính chất hoá học đặc trưng của arene (hoặc qua mô tả thí nghiệm): Phản ứng thế của benzene và toluene, gồm phản ứng halogen hoá, nitro hoá (điều kiện phản ứng, quy tắc thế); Phản ứng cộng chlorine, hydrogen vào vòng benzene; Phản ứng oxi hoá hoàn toàn, oxi hoá nhóm alkyl.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 26, 27 — bản ghi HH-0044', NULL, NULL, '2026-10-26T13:43:01.191Z', '2026-10-26T13:43:01.191Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f52-7873-a49c-c6c73bf3ed4a', NULL, 'a0914615-cbc2-5c25-a55b-f6ac0be1cf4a', 'Trình bày được tính chất hoá học cơ bản của dẫn xuất halogen: Phản ứng thế nguyên tử halogen (với OH–); Phản ứng tách hydrogen halide theo quy tắc Zaisev.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27 — bản ghi HH-0045', NULL, NULL, '2026-10-26T13:43:01.200Z', '2026-10-26T13:43:01.200Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f57-79c8-91a4-02148f4761e3', NULL, 'e7e631d5-fd7c-50a0-928b-609839799afc', 'Trình bày được tính chất hoá học của alcohol: Phản ứng thế nguyên tử H của nhóm –OH (phản ứng chung của R–OH, phản ứng riêng của polyalcohol); Phản ứng tạo thành alkene hoặc ether; Phản ứng oxi hoá alcohol bậc I, bậc II thành aldehyde, ketone bằng CuO; Phản ứng đốt cháy.', 4, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27, 28 — bản ghi HH-0046', NULL, NULL, '2026-10-26T13:43:01.205Z', '2026-10-26T13:43:01.205Z');
