INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ead-7ee0-b3be-e67a48a3af69', NULL, '6b92ee86-8415-53b0-ba91-5f4d4ec37357', 'Giải thích được sự hình thành liên kết  và liên kết  qua sự xen phủ AO.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 13 — bản ghi HH-0011', NULL, NULL, '2026-10-26T13:43:01.034Z', '2026-10-26T13:43:01.034Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ec6-7dd6-96b8-91413dd57cbc', NULL, '0840ad14-df8b-5a7b-9eaa-0cb734cb8c14', 'Thực hiện được (hoặc quan sát video) thí nghiệm chứng minh được xu hướng giảm dần tính oxi hoá của các halogen thông qua một số phản ứng: Thay thế halogen trong dung dịch muối bởi một halogen khác; Halogen tác dụng với hydrogen và với nước.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 15, 16 — bản ghi HH-0018', NULL, NULL, '2026-10-26T13:43:01.060Z', '2026-10-26T13:43:01.060Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ecc-7725-b213-935f1dba62b7', NULL, '63d8d046-ce40-556b-90b7-dca9453aa1eb', 'Nêu được ứng dụng của một số hydrogen halide.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 16, 17 — bản ghi HH-0019', NULL, NULL, '2026-10-26T13:43:01.065Z', '2026-10-26T13:43:01.065Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ed4-70ab-ad20-6099759953e6', NULL, '83e2da44-239b-56d5-8bb6-fe26c8efa9d1', 'Nêu được các ứng dụng điển hình của phản ứng hạt nhân: xác định niên đại cổ vật, các ứng dụng trong lĩnh vực y tế, năng lượng,...', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 17 — bản ghi HH-0021', NULL, NULL, '2026-10-26T13:43:01.073Z', '2026-10-26T13:43:01.073Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3edf-7cca-9542-ced47bec510c', NULL, '65c3274a-e16e-553d-982a-dc6fb991bef7', 'Nêu được khái niệm phản ứng nổ vật lí và nổ hoá học.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 18 — bản ghi HH-0024', NULL, NULL, '2026-10-26T13:43:01.085Z', '2026-10-26T13:43:01.085Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ef3-7bb7-8644-8eaa778d9a5d', NULL, '2e97d9d4-fa81-5f35-abb1-c0ecb65caadc', 'Giải thích được vì sao lại hay dùng nước để chữa cháy (làm giảm nhiệt độ xuống dưới nhiệt độ cháy,...).', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 19, 20 — bản ghi HH-0027', NULL, NULL, '2026-10-26T13:43:01.096Z', '2026-10-26T13:43:01.096Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3efc-7819-9c18-6fc9ac830a8c', NULL, '9fbaed4b-aa1b-50f7-8b42-851259a03961', 'Sử dụng được kết quả tính toán để thấy được hình học phân tử, xu hướng thay đổi độ dài, góc liên kết và năng lượng phân tử trong dãy các chất (cùng nhóm, chu kì, dãy đồng đẳng,...).', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 20 — bản ghi HH-0028', NULL, NULL, '2026-10-26T13:43:01.112Z', '2026-10-26T13:43:01.112Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f0b-7696-9ef2-000c71bd870b', NULL, 'de057d0a-e634-5aec-b80d-bb0d160d036a', 'Nêu được nguyên tắc xác định nồng độ acid, base mạnh bằng phương pháp chuẩn độ.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 21 — bản ghi HH-0031', NULL, NULL, '2026-10-26T13:43:01.128Z', '2026-10-26T13:43:01.128Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f16-7fd8-8b7d-2dac5395fd25', NULL, '2251be9c-6785-554d-ab39-711248a38d18', 'Trình bày được ứng dụng của ammonia (chất làm lạnh; sản xuất phân bón như: đạm, ammophos; sản xuất nitric acid; làm dung môi...); của ammonium nitrate và một số muối ammonium tan như: phân đạm, phân ammophos...', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 22 — bản ghi HH-0033', NULL, NULL, '2026-10-26T13:43:01.139Z', '2026-10-26T13:43:01.139Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f27-74d4-8b5d-64ac66f3d961', NULL, 'b0295e6e-0585-568c-94c2-a940d599e6a6', 'Nêu được ứng dụng của một số muối sulfate quan trọng: barium sulfate (bari sunfat), ammonium sulfate (amoni sunfat), calcium sulfate (canxi sunfat), magnesium sulfate (magie sunfat) và nhận SO2– Ba2+. biết được ion trong dung dịch bằng ion', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 23 — bản ghi HH-0037', NULL, NULL, '2026-10-26T13:43:01.156Z', '2026-10-26T13:43:01.156Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f39-734b-9005-a95425d33037', NULL, '80f1e530-7118-5a9d-8a6d-43da57f3bbe3', 'Nêu được chất đồng đẳng, chất đồng phân dựa vào công thức cấu tạo cụ thể của các hợp chất hữu cơ.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24 — bản ghi HH-0041', NULL, NULL, '2026-10-26T13:43:01.174Z', '2026-10-26T13:43:01.174Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f3e-796b-a992-c96c693982ba', NULL, 'f584af77-e0de-5621-90db-c163c0a96712', 'Thực hiện được thí nghiệm: cho hexane vào dung dịch thuốc tím, cho hexane tương tác với nước bromine ở nhiệt độ thường và khi đun nóng (hoặc chiếu sáng), đốt cháy hexane; quan sát, mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của alkane.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24, 25 — bản ghi HH-0042', NULL, NULL, '2026-10-26T13:43:01.179Z', '2026-10-26T13:43:01.179Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f44-798d-8148-0e85c4207cb4', NULL, '5f1ce91f-0600-5cdd-a92a-97ccd232564d', 'Trình bày được các tính chất hoá học của alkene, alkyne: Phản ứng cộng hydrogen, cộng halogen (bromine); cộng hydrogen halide (HBr) và cộng nước; quy tắc Markovnikov; Phản ứng trùng hợp của alkene; Phản ứng của alk-1-yne với dung dịch AgNO trong NH ; Phản ứng oxi hoá (phản ứng làm mất màu thuốc tím của alkene, phản ứng cháy của alkene, alkyne).', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 25, 26 — bản ghi HH-0043', NULL, NULL, '2026-10-26T13:43:01.185Z', '2026-10-26T13:43:01.185Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f4b-7462-8c12-5e22334723da', NULL, 'eacc0eec-d3bb-5f5f-81ca-f2729e8d22b3', 'Thực hiện được (hoặc quan sát qua video hoặc qua mô tả) thí nghiệm nitro hoá benzene, cộng chlorine vào benzene, oxi hoá benzene và toluene bằng dung dịch KMnO ; mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của arene.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 26, 27 — bản ghi HH-0044', NULL, NULL, '2026-10-26T13:43:01.191Z', '2026-10-26T13:43:01.191Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f52-7fae-9936-b3324fdcc5c5', NULL, 'a0914615-cbc2-5c25-a55b-f6ac0be1cf4a', 'Thực hiện được (hoặc quan sát video) thí nghiệm thuỷ phân ethyl bromide (hoặc ethyl chloride); mô tả được các hiện tượng thí nghiệm, giải thích được tính chất hoá học của dẫn xuất halogen.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27 — bản ghi HH-0045', NULL, NULL, '2026-10-26T13:43:01.200Z', '2026-10-26T13:43:01.200Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f58-71ba-9bda-6821c59cd88e', NULL, 'e7e631d5-fd7c-50a0-928b-609839799afc', 'Thực hiện được các thí nghiệm đốt cháy ethanol, glycerol tác dụng với copper(II) hydroxide; mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của alcohol.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27, 28 — bản ghi HH-0046', NULL, NULL, '2026-10-26T13:43:01.205Z', '2026-10-26T13:43:01.205Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f5f-7578-ac3d-13eea976ec4e', NULL, '0e15ec30-5eb6-5cbd-bc63-5108685fcbd3', 'Trình bày được ứng dụng của phenol và điều chế phenol (từ cumene và từ nhựa than đá).', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 28, 29 — bản ghi HH-0047', NULL, NULL, '2026-10-26T13:43:01.212Z', '2026-10-26T13:43:01.212Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f64-7bc9-96cc-86cb4ad80652', NULL, '75330484-1ca9-57b7-b7b1-a0368407701a', 'Trình bày được tính chất hoá học của aldehyde, ketone: Phản ứng khử (với NaBH4 hoặc LiAlH4); Phản ứng oxi hoá aldehyde (với nước bromine, thuốc thử Tollens, Cu(OH)2/OH–); Phản ứng cộng vào nhóm carbonyl (với HCN); Phản ứng tạo iodoform.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 29 — bản ghi HH-0048', NULL, NULL, '2026-10-26T13:43:01.217Z', '2026-10-26T13:43:01.217Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f6a-7c23-bda5-1fd242fc0c70', NULL, '5cb339c5-afe4-5101-8294-1a92baebe918', 'Trình bày được tính chất hoá học cơ bản của carboxylic acid: Thể hiện tính acid (Phản ứng với – chất chỉ thị, phản ứng với kim loại, oxide kim loại, base, muối) và phản ứng ester hoá.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 29, 30 — bản ghi HH-0049', NULL, NULL, '2026-10-26T13:43:01.223Z', '2026-10-26T13:43:01.223Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f98-7a40-bb55-b700e0b49335', NULL, '172dfb78-66f2-5eb4-ae85-35ad5b235d4e', 'Trình bày được đặc điểm về tính chất vật lí và tính chất hoá học cơ bản của ester (phản ứng thuỷ phân) và của chất béo (phản ứng hydrogen hoá chất béo lỏng, phản ứng oxi hoá chất béo bởi oxygen không khí).', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 32, 33, 34 — bản ghi HH-0061', NULL, NULL, '2026-10-26T13:43:01.269Z', '2026-10-26T13:43:01.269Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fa3-707f-8348-57a1a0f0a2ee', NULL, 'cadb8040-4158-566d-b67c-5d1043e98e0f', 'Trình bày được tính chất hoá học đặc trưng của amine: tính chất của nhóm –NH (tính base (với quỳ tím, với HCl, với FeCl ), phản ứng với nitrous acid (axit nitrơ), phản ứng thế ở nhân thơm (với nước bromine) của aniline (anilin), phản ứng tạo phức của methylamine (hoặc ethylamine) với Cu(OH) .', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 34, 35 — bản ghi HH-0062', NULL, NULL, '2026-10-26T13:43:01.280Z', '2026-10-26T13:43:01.280Z');
