INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3fe8-70dd-883a-fe3507c8d5eb', NULL, 'd945df1d-748e-53e8-8570-1379239a4524', 'Nêu được mức độ tương tác của kim loại IIA với nước. Chứng minh được xu hướng tăng hoặc giảm dần mức độ các phản ứng dựa vào tính kiềm của dung dịch thu được cùng với độ tan của các hydroxide nhóm IIA.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 41 — bản ghi HH-0080', NULL, NULL, '2026-10-26T13:43:01.349Z', '2026-10-26T13:43:01.349Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3feb-7ebf-9134-792566e4bdb0', NULL, 'a52a80ee-77ac-5796-b836-8c38eb7cdef5', 'Thực hiện được thí nghiệm so sánh định tính độ tan giữa calcium sulfate và barium sulfate từ phản ứng của calcium chloride, barium chloride với dung dịch copper(II) sulfate.', 5, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 41, 42 — bản ghi HH-0081', NULL, NULL, '2026-10-26T13:43:01.353Z', '2026-10-26T13:43:01.353Z');
