INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ec7-74f0-8b9c-f051bf56de82', NULL, '0840ad14-df8b-5a7b-9eaa-0cb734cb8c14', 'Giải thích được xu hướng phản ứng của các đơn chất halogen với hydrogen theo khả năng hoạt động của halogen và năng lượng liên kết H–X (điều kiện phản ứng, hiện tượng phản ứng và hỗn hợp chất có trong bình phản ứng).', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 15, 16 — bản ghi HH-0018', NULL, NULL, '2026-10-26T13:43:01.060Z', '2026-10-26T13:43:01.060Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ee0-74a7-a146-9363045a28c6', NULL, '65c3274a-e16e-553d-982a-dc6fb991bef7', 'Trình bày được khái niệm về “nổ bụi” (nổ bụi là vụ nổ gây bởi các hạt bụi rắn có kích thước hạt nhỏ (hầu hết các vật liệu hữu cơ rắn như bột nhựa, bột đường, bột ngũ cốc cũng như bột kim loại có khả năng tác dụng với oxi và toả nhiệt mạnh) trong không khí)', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 18 — bản ghi HH-0024', NULL, NULL, '2026-10-26T13:43:01.085Z', '2026-10-26T13:43:01.085Z');
