INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f45-7292-85d1-a4c5f86c563a', NULL, '5f1ce91f-0600-5cdd-a92a-97ccd232564d', 'Thực hiện được thí nghiệm điều chế và thử tính chất của ethylene và acetylene (phản ứng cháy, phản ứng với nước bromine, phản ứng làm mất màu thuốc tím); mô tả các hiện tượng thí nghiệm và giải thích được tính chất hoá học của alkene, alkyne.', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 25, 26 — bản ghi HH-0043', NULL, NULL, '2026-10-26T13:43:01.185Z', '2026-10-26T13:43:01.185Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f4c-781b-9d33-56494f0f691a', NULL, 'eacc0eec-d3bb-5f5f-81ca-f2729e8d22b3', 'Trình bày được ứng dụng của arene và đưa ra được cách ứng xử thích hợp đối với việc sử dụng arene trong việc bảo vệ sức khoẻ con người và môi trường.', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 26, 27 — bản ghi HH-0044', NULL, NULL, '2026-10-26T13:43:01.191Z', '2026-10-26T13:43:01.191Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f53-76a7-8e3f-f48f48d2b0e0', NULL, 'a0914615-cbc2-5c25-a55b-f6ac0be1cf4a', 'Trình bày được ứng dụng của các dẫn xuất halogen; tác hại của việc sử dụng các hợp chất chlorofluorocarbon (CFC) trong công nghệ làm lạnh. Đưa ra được cách ứng xử thích hợp đối với việc lạm dụng các dẫn xuất halogen trong đời sống và sản xuất (thuốc trừ sâu, thuốc diệt cỏ, chất kích thích tăng trưởng thực vật...).', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27 — bản ghi HH-0045', NULL, NULL, '2026-10-26T13:43:01.200Z', '2026-10-26T13:43:01.200Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f58-78c1-b754-4a98993a100f', NULL, 'e7e631d5-fd7c-50a0-928b-609839799afc', 'Trình bày được ứng dụng của alcohol, tác hại của việc lạm dụng rượu bia và đồ uống có cồn; Nêu được thái độ, cách ứng xử của cá nhân với việc bảo vệ sức khoẻ bản thân, gia đình và cộng đồng.', 6, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 27, 28 — bản ghi HH-0046', NULL, NULL, '2026-10-26T13:43:01.205Z', '2026-10-26T13:43:01.205Z');
