INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-25c8-71ef-8281-f202ba874fc8', NULL, '04a25927-b1f1-59ce-9513-cf6ed5e7028b', 'Nhận biết được mệnh giá của các tờ tiền Việt Nam (trong phạm vi 100 000 đồng); nhận biết được tờ tiền hai trăm nghìn đồng và năm trăm nghìn đồng (không yêu cầu học sinh đọc, viết số chỉ mệnh giá).', 7, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 32 — bản ghi TOAN-0043', NULL, NULL, '2026-10-26T13:42:54.657Z', '2026-10-26T13:42:54.657Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-2689-7421-a86c-811b524632a4', NULL, '14d12fd9-7b42-5677-8df6-25aee3db486d', 'Giải quyết được vấn đề gắn với việc giải các bài toán (có một hoặc một vài bước tính) liên quan đến các phép tính về phân số.', 7, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 41 — bản ghi TOAN-0080', NULL, NULL, '2026-10-26T13:42:54.855Z', '2026-10-26T13:42:54.855Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-26b1-7901-a28c-94d8dc4fc4a8', NULL, '0373e948-01f4-5744-b80e-78325e4e506d', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán liên quan đến chuyển động đều (tìm vận tốc, quãng đường, thời gian của một chuyển động đều).', 7, 'program', 'Thông tư 32/2018/TT-BGDĐT — Chương trình môn Toán — ct-toan-official.pdf, trang 44 — bản ghi TOAN-0092', NULL, NULL, '2026-10-26T13:42:54.895Z', '2026-10-26T13:42:54.895Z');
