INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3c1c-7e83-a2d4-e7eb00dd9601', NULL, '2feb765b-3859-57cf-9156-fc952ca516aa', 'Dựa vào sơ đồ, trình bày được cơ chế miễn dịch trong cơ thể người. Giải thích được vì sao con người sống trong môi trường có nhiều vi khuẩn có hại nhưng vẫn có thể sống khoẻ mạnh.', 7, 'program', 'Chương trình môn Khoa học tự nhiên ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-khtn-official.pdf, trang 52, 53 — bản ghi KHTN-0069', NULL, NULL, '2026-10-26T13:43:00.377Z', '2026-10-26T13:43:00.377Z');
