INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ec7-7c00-a072-4032a33c8ee9', NULL, '0840ad14-df8b-5a7b-9eaa-0cb734cb8c14', 'Viết được phương trình hoá học của phản ứng tự oxi hoá – khử của chlorine trong phản ứng với dung dịch sodium hydroxide ở nhiệt độ thường và khi đun nóng; ứng dụng của phản ứng này trong sản xuất chất tẩy rửa.', 7, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 15, 16 — bản ghi HH-0018', NULL, NULL, '2026-10-26T13:43:01.060Z', '2026-10-26T13:43:01.060Z');
