INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3ef5-7194-9e17-1a54df6dc783', NULL, '2e97d9d4-fa81-5f35-abb1-c0ecb65caadc', 'Giải thích được tại sao đám cháy có mặt các kim loại hoạt động mạnh như kim loại kiềm, kiềm thổ và nhôm... không sử dụng nước, CO2, cát (thành phần chính là SiO2), bọt chữa cháy (hỗn hợp không khí, nước và chất hoạt động bề mặt) để dập tắt đám cháy.', 7, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 19, 20 — bản ghi HH-0027', NULL, NULL, '2026-10-26T13:43:01.096Z', '2026-10-26T13:43:01.096Z');
