INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-3f3f-7a42-8d4d-5038b0402e47', NULL, 'f584af77-e0de-5621-90db-c163c0a96712', 'Trình bày được một trong các nguyên nhân gây ô nhiễm không khí là do các chất trong khí thải của các phương tiện giao thông; Hiểu và thực hiện được một số biện pháp hạn chế ô nhiễm môi trường do các phương tiện giao thông gây ra.', 7, 'program', 'Chương trình môn Hoá học ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-hoahoc-official.pdf, trang 24, 25 — bản ghi HH-0042', NULL, NULL, '2026-10-26T13:43:01.179Z', '2026-10-26T13:43:01.179Z');
