INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-37b6-79fc-8106-57b23540f0ed', NULL, 'cbf0513d-d7ea-50c3-9394-ba9bc3d11bf5', 'Nêu được một số phương pháp cơ bản của sử học: phương pháp lịch sử, phương pháp logic, phương pháp trình bày lịch sử theo lịch đại và đồng đại, phương pháp tiếp cận liên ngành. Bước đầu vận dụng được một số phương pháp cơ bản của sử học thông qua các bài tập cụ thể (ở mức độ đơn giản).', 8, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 11, 12 — bản ghi LS-0001', NULL, NULL, '2026-10-26T13:42:59.250Z', '2026-10-26T13:42:59.250Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-37e8-7964-a2f7-63278b8efc3b', NULL, '4758df21-6bea-5ed1-aa92-271a274038a4', 'Vận dụng được những hiểu biết về tác động hai mặt của Cách mạng công nghiệp lần thứ ba và lần thứ tư để tuân thủ những quy định của pháp luật trong cách thức giao tiếp trên Internet, mạng xã hội,...', 8, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 18, 19 — bản ghi LS-0011', NULL, NULL, '2026-10-26T13:42:59.299Z', '2026-10-26T13:42:59.299Z');
INSERT INTO "learning_outcomes" ("id", "tenant_id", "node_id", "content", "position", "source_kind", "source_ref", "derived_from_id", "retired_at", "created_at", "updated_at") VALUES ('01a17873-37fa-7d0f-9947-023f4d6b77de', NULL, 'd71ed85e-5a25-576d-b725-4a5eb8923985', 'Biết vận dụng hiểu biết về các nền văn minh cổ nói trên để giới thiệu về đất nước, con người Việt Nam. Nhận thức được giá trị trường tồn của các nền văn minh cổ trên đất nước Việt Nam. Có ý thức trân trọng truyền thống lao động cần cù, sáng tạo của dân tộc Việt Nam trong lịch sử. Có ý thức trách nhiệm trong việc góp phần bảo tồn các di sản văn hoá của dân tộc.', 8, 'program', 'Chương trình môn Lịch sử ban hành kèm Thông tư 32/2018/TT-BGDĐT — ct-lichsu-official.pdf, trang 20, 21 — bản ghi LS-0015', NULL, NULL, '2026-10-26T13:42:59.318Z', '2026-10-26T13:42:59.318Z');
